window.D=window.D||{};D["mb_7"]={"176":[{"s":"<b>שהפת פוטר הפרפרת. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>בירך על הפת פוטר את הפרפרת דהיינו <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>פרורי פת <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>דק דק <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>שדיבקם עם מרק או דבש <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>בירך על הפרפרת לא פטר את הפת: <small>הגה בירך על הפרפרת פוטר מעשה קדרה שהוא דייסא וכיוצא בו וכן אם בירך על מעשה קדרה פוטר את הפרפרת (גמרא פרק כיצד מברכין ורמב\"ם בפירוש המשנה):</small>","m":["(א) דק דק - שאין בהם כזית וגם אבד מהם תואר לחם שברכתן במ\"מ כמבואר בסימן קס\"ח ס\"י ומ\"מ פטר להו פת מפני שהם טפלים לגביה והרי הם נחשבין כמעשה קדרה דפת פוטרתן:","(ב) בירך על הפרפרת - דדרך הוא להביאם קודם הסעודה לתענוג או להמשיך הלב לאכילה ולא פטר את הפת כיון דברכתן במ\"מ. וכתב בשיטה מקובצת שאף אם כוון בפירוש לפטור לא מהני. ולענין ברכה אחרונה אם אכלן רק לתענוג או להשביע קצת צריך לברך עליהם ב\"א קודם הסעודה ואם לא בירך עד שבירך בהמ\"ז בדיעבד בהמ\"ז פוטר כל מיני מזונות כמו שכתבנו לקמן בסימן ר\"ח סי\"ז במ\"ב ע\"ש וי\"א דאם דעתו לאכול מיני מזונות גם בתוך הסעודה נחשבת לאכילה אחת ויכול אף לכתחלה לסמוך על בהמ\"ז שיברך לבסוף ומ\"מ נראה דאף לדעה זו יראה לכוין להדיא בבהמ\"ז לפטור מה שאכל מקודם [עיין באבן העוזר סימן ר\"ח סי\"ז]. ועיין בבה\"ל שבארנו לענין מה שאנו אוכלין אחר קידוש בשחרית לעק\"ך וקיכלי\"ך וכדומה נכון יותר שאף לדעה ראשונה לא יברך עליהם ברכה אחרונה קודם הסעודה אלא יפטרנו בבהמ\"ז וכ\"ש אם אוכל המין כיסנין גם בתוך הסעודה ובברכת במ\"מ שמברך קודם הסעודה פוטר גם אותם לכו\"ע נפטרין הכל בבהמ\"ז מפני דכל זה שייך לסעודה. ואגב אעתיק מפוסקים אחרונים עוד איזה דינים מה ששייך לענין זה. עד הנה כתבנו באוכל מיני מזונות קודם הסעודה ועכשיו נבאר באוכל שאר דברים. א) הרוצה לאכול קודם נט\"י לסעודה מדברים שצריך לברך עליהם בתוך הסעודה כגון פירות ובדעתו לאכול פירות גם בתוך הסעודה ומכוין עכשיו בברכה זו לפטור גם מה שיאכל בתוך הסעודה א\"כ הוי הכל לצורך סעודה וא\"צ לברך אחריהם דבהמ\"ז יפטור הכל כמו מה שפוטרת מה שאוכל בתוך הסעודה ואם לא יאכל פירות בתוך הסעודה צריך לברך ב\"א עליהם דכיון שאכלן קודם הסעודה אין שייכין לסעודה כלל. ואפילו אם לא בירך ב\"א קודם נט\"י צריך לברך בתוך הסעודה. ב) כ\"ז בשאוכל פירות וכנ\"ל אבל אם אכל קודם הסעודה דברים שא\"צ ברכה עליהם כשאוכלן בתוך הסעודה [כגון מיני לפתן ופרי אדמה שקורין ערד עפי\"ל או בולבע\"ס וכדומה] א\"כ אפילו אם דעתו לאכול מהם גם בתוך הסעודה אינו מועיל להם כלל הברכה ראשונה דבלא\"ה הם נפטרין ע\"י ברכת המוציא וע\"כ מה שאוכל קודם הסעודה אין שייך כלל להסעודה וצריך לברך עליהם ברכה אחרונה בורא נ\"ר. ולענין יין ושאר משקין מבואר בסימן קע\"ד סעיף ו' ז' ג) אכן אם אכל קודם הנטילה פרפראות להמשיך הלב לאכילה ולפתוח הבני מעיים [כגון מיני מתיקה שקורין איי\"ן גימאכ\"ץ או דבר מלוח וכדומה] אין לברך עליהם ברכה אחרונה דהם שייכים לסעודה ונפטרין בבהמ\"ז. ד) ודע דהא דמותר לאכול קודם המוציא דברים שא\"צ ברכה תוך הסעודה כגון המבוארים באות ב' דוקא שאין בדעתו לאכול תיכף אבל אם השלחן ערוך והלחם לפניו אסור לגרום ברכה שא\"צ אלא יברך המוציא על הלחם ויפטר שארי דברים [ח\"א] וי\"א דאם אוהב יותר לאוכלן קודם הסעודה מלאכלן בתוך הסעודה אין בזה משום גרם ברכה שאינה צריכה. ואם הם דברים המושכין הלב לתאות המאכל בודאי יש לסמוך להקל לאכלן קודם הסעודה:","(ג) פוטר מעשה קדרה - שברכתן נמי במ\"מ:"]}],"177":[{"s":"<b>דברים הבאים בתוך הסעודה ואחר הסעודה מה דינם. ובו ה סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>דברים הבאים בתוך הסעודה אם הם דברים הבאים מחמת הסעודה דהיינו דברים שדרך לקבוע סעודה עליהם ללפת בהם את הפת כגון בשר ודגים וביצים וירקות וגבינה ודייסא ומיני מלוחים אפי' אוכלם <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>בלא <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>פת אין טעונין ברכה לפניהם דברכת המוציא פוטרתן ולא לאחריהם דבהמ\"ז פוטרתן ואם הם דברים הבאים שלא מחמת הסעודה דהיינו שאין דרך לקבוע סעודה עליהם ללפת בהם את הפת <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>כגון תאנים <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>וענבים <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>וכל מיני פירות <small> (וע\"ל סי' קס\"ח סעיף ח') </small> אם אוכל אותם בלא פת טעונין ברכה לפניהם דברכת המוציא אינה פוטרתן דלאו מעיקר סעודה הם ואינם טעונים ברכה לאחריהם דכיון שבאו בתוך הסעודה ברכת המזון פוטרתם <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>ואם <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>בתחלת אכילתו אכל <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>הפירות <small> (עם פת) </small> <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>ובסוף אכל עמהם פת אפילו אם בנתיים אכל מהם בלא פת אינם טעונים ברכה אף לפניהם:","m":["(א) ללפת בהם וכו' - ודייסא אף שהיא עבה ואינו מלפת בהם הפת ונאכל בפ\"ע מ\"מ כיון שבאת להשביע עיקר סעודה היא ונטפלת להפת וה\"ה כל מיני תבשילין הרגילין לבוא לתוך סעודת הפת [רא\"ש]:","(ב) בלא פת - דכיון שתמיד באים ללפת את הפת מעיקר הסעודה הם ונטפלים להפת:","(ג) פוטרתן - ואם אינו חפץ לאכול פת אלא אוכל מעט פת כדי לפוטרם כתבו האחרונים דיש להסתפק אם יכול לפוטרם דלא שייך לומר שהם נטפלים להפת כיון שלא היה חפץ באכילתו וכ\"ש כשאכל רק פחות מכזית או אולי כיון דדרך העולם לקבוע סעודה על הפת ברכת הפת פוטרתן בכל גווני וע\"כ כתבו דבאופן זה טוב יותר שיברך על השארי דברים הברכה הראויה לכל אחת ולא יאכל פת כלל אם לא בשבת ויו\"ט דאז מצוה לאכול כזית פת חשוב הוא ונעשו הכל טפלים לו:","(ד) כגון תאנים וכו' - וכן כל דבר שבא רק לקינוח ולא להשביע. ואפילו היו הפירות לפניו בשעה שבירך המוציא. ואפילו הם מבושלים ג\"כ אין הפת פוטרתן כיון שאין שייכים לפת [אחרונים] ואפילו אם בישלו הפירות עם בשר משמע מכמה אחרונים דצריך לברך עליהם דאין הפירות נעשין טפילין להבשר והוא דלא כדעת הח\"א שכתב דהפירות טפלין לגבי הבשר אכן בספר יד הקטנה מצאתי שמצדד ג\"כ לומר דלא יברך אלא דכתב טעם אחר בזה דהיכא דמבשל הפירות עם בשר או עם שומן ודבש ועושה מהן תבשיל (שקורין עפי\"ל צימע\"ס או מהאגסים שקורין בארי\"ן) נראה שכל עיקרן הן באין למזון ולסעודה ולא לקינוח בעלמא אלא בתורת תבשיל כשאר תבשילין שנעשין מלפת וירק שא\"צ לברך עליהם מטעם זה ומסיים דלצאת ידי ספק כשרוצה לאכול צימע\"ס מפירות מבושלים יקח תחלה איזה פרי חי ויברך עליה להוציא את זה ואם אין לו פרי חי יאכל תחלה וסוף עם פת עי\"ש. ואין בכלל זה מה שמביאין מעט פירות מבושלין לקינוח סעודה [שקורין קאמפאט] דזה אין בא למזון כלל רק לקינוח סעודה וצריך ברכה:","(ה) וכל מיני פירות - ה\"ה חזרת וקשואין ומלפפונות חיין או צנון ובצל ג\"כ צריך לברך עליהן אכן אם אוכל חזרת או צנון ובצל וכדומה עם בשר הן נעשין טפל לבשר והבשר ללחם [פמ\"ג]:","(ו) וע\"ל סימן קס\"ח - דשם נתבאר לענין פת כיסנין כשאוכלין באמצע סעודתו:","(ז) ברהמ\"ז פוטרתם - דלענין בהמ\"ז נטפלים הם להסעודה דכיון שעתיד לברך על כל מה שאכל גם זה נכלל עמו:","(ח) ואם בתחלת אכילתו וכו' - ר\"ל שתחלת אכילת אותן פירות היה עם פת וגם כונתו הוא לאכול עמהם פת גם אח\"כ אף שאכל עמהם באמצע בלא פת א\"צ לברך עליהם דכיון שאכל אותם תחלה וסוף עם פת נחשבין כדברים הבאים מחמת הסעודה בתוך הסעודה דא\"צ ברכה כנ\"ל אך כ\"ז דוקא כשהובאו ללפת בהם את הפת ולא לקינוח דאם הובאו רק לקינוח אף שאכל עמהם מקצת פת תחלה וסוף לא מהני ומה שאוכל בלא פת צריך ברכה. וגם לא מיירי כשעיקר קביעות סעודתו היתה על אלו הפירות דאז א\"צ שיאכל גם לבסוף עם פת דוקא ורק כיון שהתחיל לאכול עם פת שוב אין מברך עליהם אף כשאכלן אח\"כ לבדן לכו\"ע כמבואר בס\"ג:","(ט) ובסוף אכל עמהם - ואם אין בדעתו לאכול עוד עם פת צריך לברך על הפירות לפניהם ועיין בבה\"ל:","(י) אינם טעונים ברכה - והאחרונים כתבו דראוי ליזהר לכתחלה כשהובאו לפניו פירות בתוך הסעודה ללפת בהם את הפת שיברך מתחלה עליהם קודם שיאכלם עם הפת ויאכלם קצת בפ\"ע ואח\"כ יוכל לאכול בין עם פת בין בלא פת כי יש מהראשונים דסברי דאפילו אם אוכל תחלה וסוף עם פת אם אוכל באמצע בלא פת צריך לברך ובדיעבד אם לא בירך מתחלה מותר לאכול אך שיראה לאכול גם לבסוף עם פת. אמנם אם עיקר קביעת סעודתו היתה מתחלה על הפירות אז לכו\"ע אפילו אם אוכל אח\"כ בלא פת א\"צ לברך כמ\"ש בס\"ג. אם אכל פשטיד\"א שממולא עם פירות א\"צ לברך על הפירות דנטפלים הם להקמח ועיין לעיל בסימן קס\"ח במ\"ב:","(יא) הבאים מחמת הסעודה - כגון בשר ודגים וכיו\"ב וכנ\"ל:","(יב) שלא מחמת הסעודה - כמו פירות ומיני מתיקה הבאים רק לקינוח וכנ\"ל:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i> ודברים הבאים לאחר סעודה קודם ברכת המזון שהיה מנהג בימות חכמי הגמרא שבסוף הסעודה היו מושכים ידיהם מן הפת ומסירים אותו וקובעים עצמם לאכול פירות ולשתות כל מה שמביאים אז לפניהם בין דברים הבאים <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>מחמת הסעודה בין דברים הבאים שלא מחמת הסעודה טעונים ברכה <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>בין לפניהם ובין לאחריהם דהמוציא וברכת המזון אין פוטרתן אלא מה שנאכל תוך עיקר הסעודה ודין זה האחרון אינו מצוי בינינו <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>לפי שאין אנו רגילין למשוך ידינו מן הפת עד ברכת המזון:","m":["(יג) בין לאחריהם - ואף אם אכל דברים שברכתן מעין שלש לא נפטרו בבהמ\"ז דבהמ\"ז אינו פוטר מעין שלש כמ\"ש לקמן בסימן ר\"ח סי\"ז ע\"ש:","(יד) תוך עיקר הסעודה - דאחר שמשכו ידיהם מן הפת שוב אין נטפלים אליו ולכן צריכין ברכה בפני עצמם בין לפניהם בין לאחריהם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ואם <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>קובע ליפתן סעודתו על הפירות הוו ליה הפירות כדברים הבאים מחמת הסעודה <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ואפי' אם אוכל מהפירות בתחלת סעודתו בלא פת אינו מברך לא לפניהם ולא לאחריהם <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ויש חולקין ולכן טוב שיאכל בתחלה מהפירות עם פת ואז אפילו אם אח\"כ יאכל מהם בלא פת אינם טעונים <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>ברכה כלל: <small>הגה ואע\"פ שאינו חוזר לבסוף לאכול עמהם פת מאחר שעיקר קביעות היה עלייהו (ב\"י בשם הר\"י):</small>","m":["(טו) ואם קובע וכו' - ר\"ל שקביעת סעודתו ללפת הפת היה רק אלו הפירות וע\"כ נחשבים הם כשאר דברים הנזכרים לעיל בס\"א:","(טז) ויש חולקין - ס\"ל דמ\"מ אם אכל מהם בתחלה בלא פת אינם נעשים טפל להסעודה וצריך לברך עליהם בתחלה:","(יז) ואע\"פ וכו' מאחר וכו' - ר\"ל דאף דבס\"א אמרינן שיאכל פת דוקא גם לבסוף בזה שעיקר קביעת סעודתו מתחלה היה רק על אלו הפירות יוכל לאכול אח\"כ לכו\"ע בלא ברכה אף שאין דעתו לאכול עמהם עוד פת:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i> אע\"פ שלא היו הפירות לפניו בשעה שבירך על הפת <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>כיון דללפת את הפת הם באים אינם טעונים ברכה כלל:","m":["(יח) שלא היו וכו' - ואפילו לא היה ג\"כ דעתו עליהם בפירוש דכיון שקובע עצמו לאכילה הרי מן הסתם דעתו על כל מה שיביאו לו [מ\"א בסי' רי\"ב]:","(יט) ברכה כלל - פי' למה שאוכל עם הפת ומה שאוכל בלא פת נתבאר בסעיפים הקודמים:","(כ) שדרכן לבוא וכו' - ר\"ל וגם אוכלן עם הפת כיון שהוא מבית אחרים שבודאי לא היה דעתו עליהם כלל אין נפטרין בברכת הפת:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אם אחר שבירך על הפת שלחו לו מבית אחרים שאינו סמוך עליהן ולא היה דעתו על הדורון אפי' מדברים שדרכן לבא ללפת את הפת צריך לברך עליהם כדין נמלך: <small> (ולא ראיתי נזהרים בזה ואפשר דטעמא <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>דסתם <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>דעת האדם על כל מה שמביאים לו בסעודה וע\"ל סי' ר\"ו):</small>","m":["(כא) על כל מה וכו' - והיינו כשהביאו לו דברים הבאים מחמת הסעודה וכנ\"ל בס\"א דאלו אם הביאו לו מיני פירות לא מהני אפי' היה דעתו לזה בשעת ברכת המוציא שיוכל לאכלן אח\"כ בלי ברכה [ואפילו בפירות שלו] אא\"כ מלפת בהם הפת. <br><b>קיצור דיני פירות הבאים בתוך הסעודה:</b> אם אוכל עם הפת פשיטא שא\"צ כלל ברכה דנעשה טפל לפת ואפילו לא היה דעתו לזה בפירוש בשעת ברכת המוציא. ואם אוכל בלא פת פשיטא שצריך ברכה לפניהם ואפילו הם מבושלים דהוי שלא מחמת הסעודה רק לקינוח בעלמא. אבל אם רוצה לאכול פירות קצת עם הפת וקצת בלא פת בזה יש דעות חלוקות ע\"כ יש לנהוג שיאכל תחלה מעט בלא פת ויברך עליהן ואח\"כ יוכל לאכול שאר הפירות בין בפת ובין בלא פת. וזהו בקובע סעודתו ללפת הפת בשאר דברים אבל בקובע סעודתו ללפת הפת בפירות כיון שאכל מתחלה פירות עם פת יוכל לאכול בסוף פירות בלא פת בלא ברכה: "]}],"178":[{"s":"<b>איזה דברים קרוים הפסק בסעודה. ובו ז סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i> היה אוכל בבית זה ופסק סעודתו <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>והלך לבית אחר או <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>שהיה אוכל וקראו חבירו לדבר עמו ויצא לו לפתח ביתו וחזר הואיל ושינה מקומו <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>צריך לברך <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>למפרע על מה שאכל וחוזר ומברך בתחלה המוציא ואח\"כ יגמור סעודתו <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אבל אם דבר עמו בתוך הבית אע\"פ ששינה מקומו מפנה לפנה אינו צריך לברך <small>(ועיין לקמן סי' רע\"ג אם היה <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>דעתו לאכול במקום אחר לא מיקרי שינוי מקום והוא שיהיו שני המקומות בבית א' וע\"ל סי' קפ\"ד):</small>","m":["<b>הנה מפני שהסימן הזה יש בו פרטים רבים ע\"כ אקדים לזה הקדמה קצרה כדי להקל על המעיין:</b> הנה בענין שינוי מקום [היינו שהתחיל לאכול והלך למקום אחר ורוצה לאכול שם או שרוצה לחזור למקומו הראשון ולאכול שם] קי\"ל דצריך לחזור ולברך ויש בזה ג' דברים שצריך לבאר. א) מהו שינוי מקום אם מבית לבית או מחדר לחדר. ב) באיזה דברים שייך דין שינוי מקום. ג) אם שינה מקומו מה דינו בזה ונחזור לבאר אחד אחד. ענין שינוי מקום הוא לא מיבעיא אם הלך באמצע אכילתו מבית זה לבית אחר בודאי הוי שינוי מקום ואפילו אם יצא רק חוץ לפתח ביתו בתוך אכילתו ג\"כ בכלל שינוי מקום הוא ואינו מועיל אפילו היה דעתו לזה בשעת ברכה שישנה מקומו ואפילו אם שינה רק מחדר לחדר ג\"כ סוברים הרבה פוסקים דהוא שינוי מקום [ועיין במש\"כ בזה בבה\"ל] אך בזה יש חילוק דאם היה דעתו בשעת ברכה לשנות המקום מחדר לחדר מותר כיון שהוא תחת גג אחד. ומזוית לזוית אפילו טרקלין גדול לא הוי שינוי מקום כלל כיון שהוא חדר אחד ואין צריך כלל דעתו לזה. ובאיזה דברים שייך שינוי מקום איתא בזה פלוגתא בגמרא [פסחים ק\"א ע\"ב] דרב ששת סבר בין אם אכל פת ובין שאכל פירות ושארי משקין דינם שוה בזה דצריך לחזור ולברך ורב חסדא סבר דוקא אם אכל דבר שאין טעון ברכה במקומו ר\"ל כגון פירות ומשקין שאין מחויב דוקא לברך ברכה אחרונה שלהן במקומו הראשון וע\"כ אמרינן דתיכף שעקר ממקומו נתבטל קביעתו וצריך לחזור ולברך כשירצה לאכול עוד אבל אם אכל פת [וי\"א דה\"ה כל דבר שהוא משבעת המינים] שהוא דבר שצריך לברך במקומו דוקא וע\"כ אמרינן בהו דאפילו אם עקר ממקומו עדיין לא נתבטל קביעותו הראשונה וכל היכא שאוכל על דעת קביעות הראשונה הוא וכאלו יושב במקומו דמי ואין צריך לברך עליו המוציא ונחלקו הפוסקים בזה הרמב\"ם וסייעתו פסקו כרב ששת דבכל גווני צריך לברך וזהו טעם שני סעיפים הראשונים והרא\"ש וסייעתו פסקו כרב חסדא וזהו דעת הגהת הרמ\"א שהובא בסוף סעיף ב'. וכל זה הוא לענין לחזור ולברך אבל לכתחלה אין לעקור ממקומו לכו\"ע בכל גווני. ומה דינו של שינוי מקום נחלקו הפוסקים ג\"כ בזה הרמב\"ם וסייעתו סוברים דמשחזר למקומו בתחלה צריך לברך בהמ\"ז [או הברכה אחרונה כשאכל דבר שחייבין עליו לברך ברכה אחרונה] על האוכל שאכל מקודם ואח\"כ יחזור לברך ברכה ראשונה על מה שהוא רוצה לאכול עתה וזהו המוזכר בסעיף א' ושארי פוסקים סוברים דאין צריך לברך רק הברכה ראשונה על מה שהוא רוצה לאכול אבל הברכה אחרונה יוצא במה שמברך אחר אכילה השניה ויהיה קאי על שניהן וזהו המוזכר בריש הג\"ה שבסוף ס\"ב ולמעשה נקטינן הכל כדעת הפוסקים המובא בהג\"ה ויתר פרטי הדינים המסתעפים לזה יבואר הכל אי\"ה בתוך הסימן ועתה נתחיל לבאר את דברי הסימן:","(א) היה אוכל בבית זה - ומיירי באוכל יחידי דאם אכל ביחד עם עוד אנשים ונשארו בני חבורתו במקומן א\"צ לחזור ולברך לכו\"ע ע\"י יציאתו וכדלקמן בס\"ב:","(ב) והלך וכו' - ואפילו לא נשתהא שם כלל שתיכף חזר למקומו הראשון אפ\"ה שינוי מקום מקרי וכדלקמיה וכ\"ש אם רוצה לגמור סעודתו במקום השני:","(ג) לבית אחר - וה\"ה לחדר אחר ג\"כ בכלל שינוי מקום הוא אם לא שהיה דעתו מתחלה לשנות לחדר אחר וכדלקמיה בהג\"ה ע\"ש:","(ד) או שהיה אוכל וכו' - אשמועינן בזה אע\"פ שלא פסק מסעודתו כלל אלא שקראו חבירו לדבר עמו דיבור בעלמא ויצא לקראתו מפתח ביתו וחזר הוי כמו שינוי מבית לבית:","(ה) לפתח ביתו - ר\"ל שיצא חוץ לפתחו דאם מדבר עמו על הפתח אין זה שינוי מקום:","(ו) צריך לברך וכו' - דע\"י היציאה ממקומו חשיב כנפסקה סעודתו לגמרי ומה שאוכל אח\"כ כסעודה אחרת דמיא ולכן מברך בהמ\"ז למפרע והמוציא על להבא:","(ז) למפרע - ובמקומו הראשון. ולכתחלה כשרוצה לצאת ממקומו צריך לברך בהמ\"ז קודם שיעקור כמ\"ש ס\"ב ורק בדיעבד כשלא בירך מתחלה צריך אח\"כ לחזור ולברך בהמ\"ז במקומו שכך הוא מצותו ואח\"כ יברך המוציא ויאכל במקום שירצה:","(ח) וחוזר ומברך המוציא - והיינו כשעומד באמצע סעודת פת וכ\"ש אם לא אכל מתחלה רק פירות או משקין בודאי שייך בהו שינוי מקום וכדלקמיה בס\"ב:","(ט) מפנה לפנה - היינו באותו חדר ואף שאין נראה לפניו מקומו הראשון מחמת הפסק דבר מתשמישי הבית כמו תנור או פאראוואן וכיו\"ב אין זה שינוי מקום כיון שהוא בחדר אחד:","(י) ועיין לקמן וכו' - ר\"ל דשם מיירי לענין שינוי מקום גבי קידוש וה\"ה לעניננו:","(יא) אם היה דעתו - ר\"ל שבשעת ברכה חשב לאכול גם במקום ההוא:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i> חברים שהיו יושבים לאכול ויצאו לקראת חתן או לקראת כלה אם הניחו שם מקצתן חוזרים למקומן וגומרים סעודתן ואינם צריכים לברך שנייה ואם לא הניחו שם אדם כשהם יוצאים צריכין ברכה למפרע וכשהם חוזרים צריכים ברכה לכתחלה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>וכן אם היו מסובין לשתות או לאכול פירות שכל המשנה מקומו הרי פסק אכילתו ולפיכך מברך למפרע על מה שאכל וחוזר ומברך שנית על מה שהוא צריך לאכול והמשנה מקומו <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>מפנה לפנה <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>בבית אחד אינו צריך לחזור ולברך <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אכל במזרחה של תאנה זו ובא לאכול במערבה <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>צריך לברך <i data-commentator=\"Be'er HaGolah\" data-label=\"•\" data-order=\"6\"></i>: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>ויש חולקים בכל מה שכתוב בסי' זה רק סוברין ששינוי מקום אינו אלא כהיסח הדעת ולכן אם שינה מקומו למקום אחר אין צריך לברך אלא לפני מה שרוצה לאכול אבל לא על מה <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>שכבר אכל (תוס' ורשב\"ם והרא\"ש ומרדכי פרק ע\"פ וטור) <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>ודוקא שלא הניח מקצת חברים בסעודה ואכל מדברים שאין צריכים ברכה במקומן אבל אם הניח מקצת חברים או אפילו לא הניח ואכל <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>דברים שצריכין ברכה במקומם אפי' מה שרוצה לאכול אחר כך <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>אין צריך לברך (סמ\"ק וא\"ז) <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>ולכן מי שפסק סעודתו והלך <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>לבית אחר או שהיה אוכל וקראו חבירו לדבר עמו אפי' לפתח ביתו או למקום אחר כשחוזר לסעודה א\"צ לברך כלל דהא פת צריך ברכה במקומו לכולי עלמא מיהו אם הסיח דעתו כשחוזר ודאי צריך <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>לברך על מה שרוצה לאכול אח\"כ (ב\"י ורשב\"א) <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>ואין חילוק בין חזר למקום שאכל כבר ובין סיים סעודתו במקום <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>אחר (רמב\"ם פ\"ד ור\"ן) וכן נוהגין במדינות אלו מ\"מ לכתחלה לא יעקור ממקומו בלא ברכה <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>דחיישינן שמא ישכח מלחזור ולאכול (הר\"ר מנוח ור\"ן) מיהו לצורך מצוה עוברת כגון שיגיע זמן תפלה מותר (כל בו הל' פסח ועסי' קפ\"ד):</small>","m":["(יב) בבית אחד - היינו תחת גג אחד ואפילו מחדר לחדר או מבית לעליה ואף שאין רואה מקומו וה\"ה אם רואה מקומו הראשון שאכל שם אפילו דרך חלון ואפילו מקצת מקומו נמי מועיל אף שלא היה דעתו מתחלה. ודוקא מחדר לחדר באותו בית אבל מבית לבית אף שסמוכין זה לזה מסתפקים האחרונים דאפשר דאין להקל ע\"י ראית מקום. ודע שלפי המבואר לקמן בהג\"ה דאנו נוהגין כהפוסקים שלא לברך ע\"י שינוי מקום כשעומד באמצע סעודת פת תו אין נ\"מ לדינא כל החילוקים האלו שהזכרנו לענין שינוי מקום רק לענין מסובין לאכול פירות ושארי משקין דבהם לכו\"ע שייך דין שינוי מקום:","(יג) לקראת חתן וכו' - וה\"ה כשיצא לדבר הרשות והא דנקט לקראת חתן לרבותא דבלא הניחו שם אדם צריך לברך בהמ\"ז מקודם שיצאו אף שיוצאין לדבר מצוה:","(יד) מקצתן - ואפילו רק אחד:","(טו) לברך שניה - היינו ברכת המוציא אף ששינו מקומן בינתים דכיון שנשאר מקצתן במקומן לא פסקה סעודתן בהיציאה:","(טז) כשהם יוצאים וכו' - דכיון שלא הניחו שם אדם נפסקה סעודתן ע\"י היציאה וכשאוכל אח\"כ הוי כסעודה חדשה:","(יז) כשהם חוזרים וכו' - באמת כבר כתב זה בס\"א וכפל הדברים בשביל החידוש דהניח מקצת חברים או למה שכתבנו בסקי\"ג:","(יח) וכן אם היו וכו' - אשמועינן דגם בזה מהני הניח מקצת חברים כמו בסעודת פת:","(יט) פסק אכילתו - וגרע מהיסח הדעת שאין מברכין רק ברכה לכתחלה כשחוזר לאכול דזה נחשב כסעודה אחרת לגמרי:","(כ) ולפיכך מברך וכו' - היינו כשלא בירך ברכה אחרונה קודם יציאתו מברך עתה כשחזר וכמו לענין פת לעיל בס\"א:","(כא) למפרע - ובזה א\"צ לחזור למקומו דוקא אלא יכול לברך אפילו במקום השני דרק בפת מצותו לכו\"ע לחזור ולברך במקומו כדלקמן בס\"ה:","(כב) בבית אחד - פי' בחדר אחד [מ\"א וש\"א] ועיין מש\"כ בבה\"ל:","(כג) אינו צריך וכו' - ואף ששינה מקומו לגמרי לאכול בזוית האחרת א\"צ לחזור ולברך דזה אינו נחשב שינוי מקום ואף שאין רואה מקומו הראשון כגון שמפסיק תנור וכיו\"ב כיון שהוא בחדר אחד:","(כד) אכל במזרחה וכו' - ואין חילוק בין שאכל שם פת ושארי דברים או שאכל פירות התאנה עצמה:","(כה) צריך לברך - כיון שהתאנה מפסקת ואינו רואה מקומו הראשון ומיירי שלא עמדה התאנה בתוך היקף מחיצות דאם עמדה בתוך היקף מחיצות אף שאין רואה מקומו א\"צ לברך דחשיב הכל מקום אחד וכמש\"כ לעיל בשינה מקומו בחדר אחד ועיין לקמיה בס\"ג לענין מאילן לאילן. ואם היה דעתו בשעת ברכה לאכול גם במערבו של אילן י\"א דמהני בכל גווני:","(כו) ויש חולקים וכו' - בתרתי פליגי על דעה ראשונה אחד דהם לא מצרכי ברכה למפרע לעולם מחמת שינוי מקום ורק ברכה לכתחלה קודם שיאכל שנית דחשיב רק כהיסח הדעת ולא כמה שסילק סעודה הראשונה לגמרי וע\"כ הברכה אחרונה עולה לשניהם וגם ס\"ל דגם זה שצריך ברכה ראשונה הוא רק בעומד בסעודת פירות או משקין דתיכף ביציאתו חוץ לפתח ביתו נפסקה סעודתו [אם לא הניח שם מקצת חברים ואפילו הלך רק לעשות צרכיו לקטנים] אבל בפת ומיני דגן שצריכין לחזור ולברך במקומן לא נפסקה הסעודה בהיציאה וא\"צ אף ברכה ראשונה וכאלו לא שינה מקומו כלל אם לא שהסיח דעתו מלאכול עוד וכדלקמיה:","(כז) אבל אם הניח וכו' - דכיון שנשארו מקצתן ואפילו אחד במקומו לא נפסקה הסעודה וחוזרין לאכול או לשתות בלי שום ברכה אף שהיתה מסיבתן לאכול פירות או משקין:","(כח) ואכל דברים וכו' - כתב במ\"א סימן ר\"י דוקא כשאכל כזית דאם אכל רק פחות מכזית פת קודם שיצא דינו כמו פירות דהא א\"צ לברך אחריו וממילא מיד שיצא לחוץ צריך ברכה ראשונה אף שחזר למקומו וע\"כ צריך ליזהר לכתחלה שלא לצאת ממקומו אף מחדר לחדר [היכי שאין רואה מקומו] קודם שיאכל כזית:","(כט) או שהיה אוכל וכו' - אף שלא אשמועינן בבבא זו שום רבותא נקט לישנא דהמחבר בס\"א ופסק להיפך:","(ל) ודאי צריך לברך - ברכה ראשונה כדין היסח הדעת ואח\"כ יברך בהמ\"ז על הכל:","(לא) ואין חילוק בין וכו' - אלעיל קאי והיינו באוכל דברים הטעונין ברכה במקומו ולא הניח מקצת חברים ואשמעינן דאף כשמסיים סעודתו במקום אחר ג\"כ א\"צ לברך דעל סמך סעודה ראשונה אוכל אבל כשאוכל דברים שאין טעונין ברכה במקומן כגון פירות וכיו\"ב [או ששותה משקין] אף שהניח מקצת חברים לא מהני אלא כשחוזרין לחבורתן לסעודתן הראשונה אבל לאכול או לשתות במקום אחר צריכין ברכה לכתחלה [מ\"א וש\"א]:","(לב) סיים סעודתו - ואם אכל גם שם פת מבואר בס\"ד דמברך שם בהמ\"ז כיון דשם הוא סיום סעודתו:","(לג) לכתחלה לא יעקור - ר\"ל אף שעומד באמצע סעודת פת ורוצה לצאת ע\"מ לחזור ולאכול ולברך דלדעה זו אינו מצריך שום ברכה ביציאתו מ\"מ לכתחלה לא יצא דחיישינן שמא ישכח לחזור ולאכול ולברך במקומו [או שישהא עד שירעב ויפסיד בהמ\"ז לגמרי] ואם מזמינים לו לאכול פת במקום אחר דאז לא שייך האי חששא כיון שהולך לאכול שם ויברך שם אחר אכילתו כמ\"ש בס\"ד אפ\"ה לכתחלה לא יעקור ממקומו עד שיברך דרק בדיעבד כשכבר יצא אמרינן דמותר לו לאכול ולברך במקום השני דגם שם מקומו הוא אבל לכתחלה מצותו לברך במקומו שאכל קודם שיצא אם לא שהיה דעתו בשעת המוציא לאכול גם שם דאז חשיבי שניהם מקומו ומותר אף לכתחלה ואפילו מבית לבית מהני מחשבתו לדעה זו וכן נהגו כשהולכין לסעודת נשואין שמכוון מתחלה לאכול שם:","(לד) ממקומו - בתוספות ורא\"ש משמע דאין להחמיר בזה רק כשיוצא ע\"מ להפליג דאז חיישינן להנ\"ל אבל כשיוצא ע\"מ לחזור לאלתר מותר:","(לה) בלא ברכה - עיין בחידושי רע\"א מה שכתב בזה ועיין בבה\"ל שהכרענו לדינא דאף דלכתחלה בודאי נכון לנהוג כהרמ\"א שלא לצאת לדבר הרשות מ\"מ כשיוצא אין לו לברך אם יציאתו הוא ע\"מ לחזור ולגמור סעודתו דחשיב כעומד באמצע סעודה ויש בזה חששא דברכה שא\"צ רק אם הוא משער שאפשר שיפליג הרבה נכון יותר שיברך בהמ\"ז כשיוצא:","(לו) דחיישינן וכו' - ואפילו אם לא אכל פת אלא פירות ושארי דברים משמע מכמה אחרונים דנכון ליזהר לכתחלה שלא לצאת ממקומו עד שיברך ברכה אחרונה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"7\"></i>יש מי שאומר שאם היה בגן ורוצה לאכול מפירות כל אילן ואילן כיון שברך על אילן אחד <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>אינו צריך לברך על האחרים והוא שבשעה שבירך היה דעתו לאכול מאותם האחרים אבל מגן לגן צריך לברך אפילו אם הם סמוכים <i data-commentator=\"Turei Zahav\" data-order=\"8\"></i>ואפי' אם כשבירך תחלה היה דעתו על הכל:","m":["(לז) אינו צריך לברך - ואפילו אין רואה מקומו שהאילנות מפסיקין ול\"ד לאוכל במזרחה של תאנה ובא לאכול במערבה דצריך לברך דכאן מיירי שמוקף מחיצות דחשיב כמו מקום אחד כנ\"ל ויש מאחרונים שפירשו דמיירי באין מוקף מחיצות וטעם ההיתר בזה הוא משום שהיה דעתו לזה מתחלה וכמש\"כ לעיל בהג\"ה דדעתו מהני אף מחדר לחדר ואף שאין רואה מקומו מחמת הפסק האילנות לא חשיב אלא כמו מחדר לחדר ולפ\"ז גם לענין מזרחה של תאנה מהני דעתו ולהכי כתב המחבר בשם יש מי שאומר משום דאין דין זה ברור דליהני דעתו באין מוקף מחיצות דהוא רק שיטת הראב\"ד [הגר\"א בביאורו]:","(לח) והוא וכו' היה דעתו - כמו בחדר לחדר בעלמא דבעינן דוקא דעתו וכנ\"ל בס\"א בהג\"ה ובח\"א כלל נ\"ט ראיתי שמחלק בענין זה בין מוקף מחיצות לאינו מוקף מחיצות דבמוקף מחיצות לא בעינן דעתו בפירוש אלא אפילו מסתמא אמרינן דדעתו על כל האילנות [אם לא שהיה דעתו מתחלה לאכול רק מהאחד ואח\"כ נמלך לאכול גם מהשני דאז צריך לברך] ובאינו מוקף מחיצות בעינן שיהיה דעתו בשעת ברכה גם על השני [ואם לא היה דעתו אפילו רואה את מקומו הראשון ג\"כ אינו מועיל כיון שאינו מוקף מחיצות ט\"ז ודה\"ח]:","(לט) ואפי' וכו' - משום שינוי מקום דהוי כמבית לבית דלא מהני דעתו לכו\"ע כמש\"כ לעיל בס\"א בהג\"ה ואפילו אין הגן מוקף מחיצות כיון שכל אחד הוא בפני עצמו חשיב הוא כמו שני בתים ואפילו רואה מקומו הראשון ג\"כ אינו מועיל. מי שבירך על הפרי לאכול כאן ולא אכל ממנו ושינה מקומו כתב הא\"ר בשם ברכת אברהם דאינו יוצא בברכתו [ולפי מש\"כ לעיל בס\"ב בבה\"ל הוא דוקא מבית לבית אבל מחדר לחדר לא] וכתב הח\"א דאפילו אם אוחז הפרי בידו והולך ואוכל יש בו משום שינוי מקום אם יצא ממקומו הראשון שקבע עצמו לאכול לחדר אחר ולא היה דעתו מתחלה לזה דכל פתיתה ופתיתה הוא דבר אחר עי\"ש ולפי מה שכתבתי לעיל יש ליזהר בזה רק לכתחלה אבל בדיעבד אין לחזור ולברך מחמת שינוי מקום שמחדר לחדר:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"8\"></i> אם אכל פת במקום א' <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>וחזר ואכל במקום <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>אחר אינו מברך בהמ\"ז <i data-commentator=\"Turei Zahav\" data-order=\"9\"></i>אלא במקום השני <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>כמו שנהגו הולכי דרכים שאוכלי' דרך הילוכם ויושבים ומברכין במקום סיום אכילתם:","m":["(מ) וחזר ואכל - ואף דלדעת המחבר לעיל בסעיף א' וב' אסור לאכול במקום השני על סמך סעודה הראשונה אלא צריך לברך מקודם בהמ\"ז על אכילה ראשונה והמוציא על להבא וגם דעתו לא מהני מבית לבית צ\"ל דכאן מיירי שכבר אכל דאז מברך במקום השני דגם זה מקומו הוא ולפי מה שאנו נקטינן כדעת ההג\"ה לעיל בסעיף ב' רק לכתחלה אין לעקור ממקומו עד שיברך במקומו אבל אם כבר עקר מותר לאכול כאן על סמך סעודה הראשונה ואם היה דעתו לזה מהני בסעודת פת אף לעקור לכתחלה מבית לבית וכנ\"ל:","(מא) אלא במקום השני - דכאן הוא סיום סעודתו:","(מב) הולכי דרכים - דהם לכו\"ע מותר להם להלוך ולאכול ואף אם אין רואין מקומן הראשון מחמת מרחק הדרך או שמפסיקין אילנות משום דהם לא קבעו עצמן לכתחלה לאכול במקום שברכו ורק לילך ולאכול ולכן אין נחשבין כלל עי\"ז עוקרין ממקומן ואם היה דעתן לאכול סעודתן במקום שברכו המוציא ונמלכו לגמור סעודתן דרך הליכתן כ\"ז שרואין מקומו הראשון מותר להם לאכול דחשיב מקום אחד אבל באין רואין מחמת מרחק הדרך או מחמת הפסק אילנות חשיב שינוי מקום ובפירות צריך לברך שנית ובפת ג\"כ אף לדעת הגהה לעיל עכ\"פ לכתחלה אין להם לעקור ממקומן בלא ברכה כמבואר שם. אך אם מתחלה חשב לאכול מעט במקומו והשאר לאכול בדרך מהני ואף בהפסק אילנות דרק מבית לבית לא מהני דעתו באכילת פירות אמנם אם התחיל לאכול בבית והלך לדרך הרי הוא כמו מבית לבית דלא מהני דעתו בפירות וצריך לחזור ולברך ובפת מהני דעתו ואף לענין לכתחלה:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"12\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"9\"></i>י\"א ששבעת <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>המינים טעונים ברכה לאחריהם במקומם <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"10\"></i>ויש אומרים דדוקא מיני דגן: <small>הגה ויש אומרים דוקא פת לבד: (ב\"י סי' קפ\"ד בשם רשב\"א והגהות מיימוני פרק ד'):</small>","m":["(מג) לאחריהם במקומם - ואם הלך משם צריך לחזור למקומו ולברך כמו לגבי פת:","(מד) מיני דגן - מפני חשיבותן שנקרא מזון:","(מה) לבד - כתבו האחרונים דלכתחלה יחמיר לברך במקומן אפילו בז' מינים וכן לענין שינוי מקום א\"צ לברך על כל השבעה מינים כמו על הפת אם שינה מקומו לפי מה שפסק בס\"ב בהג\"ה ודעת הגר\"א בביאורו דדעה האמצעית היא העיקר לדינא ולפ\"ז פירות של שבעת המינים דומים לסתם פירות דשייך בהו שינוי מקום לכו\"ע:","(מו) וא\"א לו לאכול - ר\"ל דלכאורה יש לדמותו להב לן ונברך דלמ\"ד דאין רשאי לאכול צריך לברך כשחוזר לאכול אבל באמת לא דמי דהתם הטעם משום דהוי היסח הדעת וסילוק משא\"כ הכא דלא הסיחו דעתם מלאכול:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"11\"></i>מי שנזכר בתוך הסעודה שלא התפלל ועמד והתפלל אפי' אם אין שהות לגמור סעודתו ולהתפלל שחייב להפסיק ואי אפשר לו לאכול עד שיתפלל <i data-commentator=\"Turei Zahav\" data-order=\"10\"></i>עם כל זה <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>לא הוי <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>הפסק:","m":["(מז) לא הוי הפסק - ולדעת המחבר בס\"א הוא דוקא כשמתפלל בביתו אבל אם הולך לבהכ\"נ הוי הפסק אכן לפי מה שאנו נקטינן כדעת ההג\"ה בס\"ב לא הוי הפסק אף כשהלכו לבהכ\"נ ורק אם לא הסיחו דעתם מלאכול. כתב המ\"א דאף דהמוציא א\"צ לברך מחמת הפסק התפלה אבל נט\"י צריך דשמא לא שמר ידיו אבל הרבה אחרונים חולקין עליו וס\"ל דאף נט\"י אינו צריך דבעת התפלה בודאי שמר ידיו מלטנפם. אבל בזה דוקא אם מתפלל בביתו אבל אם הלך לבהכ\"נ והתפלל שם כשחזר צריך ליטול ידיו ובלי ברכה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"12\"></i>אדם שישן בתוך סעודתו שינת עראי לא הוי הפסק: <small>הגה וכן אם הפסיק בשאר דברי רשות כגון שהוצרך לנקביו וכיוצא בזה:</small>","m":["(מח) שינת עראי - ואפילו אם שהה משך זמן לערך שעה כיון שנאנס בשינה לא מקרי הפסק וא\"צ לברך המוציא [אבל נט\"י בעי ובלי ברכה פמ\"ג] ואם ישן על מטתו שינת קבע הוי הפסק דזהו סילוק והיסח הדעת לד\"ה:","(מט) לנקביו - ונטילת ידים צריך כמבואר בסימן קס\"ד ע\"ש:"]}],"179":[{"s":"<b>איזה דברי' קרוין היסח הדעת בסעודה שצריך לברך. ובו ו סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i> גמר סעודתו <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>ונטל ידיו מים אחרונים <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>אינו יכול לאכול <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>ולא לשתות <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>עד שיברך ברכת המזון <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ואם אמר הב לן <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ונברך הוי היסח הדעת <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ואסור לשתות אלא אם כן יברך עליו תחילה ואכילה דינה כשתיה להרא\"ש אבל להר\"ר יונה והר\"ן <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>אכילה שאני שאע\"פ שסילק ידו מלאכול ואפילו סילקו השלחן אם רצה לחזור לאכילתו אין צריך לברך פעם אחרת שכל שלא נטל ידיו לא נסתלק לגמרי מאכילה:","m":["(א) לאכול - וה\"ה שיש ליזהר לכתחלה שלא יפסיק בדבור אפילו מעט דתיכף לנטילה ברכה [ומהאי טעמא יש ליזהר שלא לשהות שהיה מרובה אחר הנטילה וכ\"ש שלא לעסוק באיזה עסק] אך אם צריך להפסיק בדבר נחוץ או בדיעבד אם הפסיק יטול ידיו שנית כדי להיות תיכף לנטילת מים אחרונים ברכה:","(ב) עד שיברך בהמ\"ז - ולא דמי להב לן ונברך דמותר לאכול ורק שיברך המוציא מתחלה וכדלקמיה דכיון שנטל ידיו אסור להפסיק. והנה יש כמה פוסקים דס\"ל דאין איסור לאכול אף בנטל ידיו ורק שיברך המוציא מתחלה וכ\"כ האחרונים להקל ורק דאחר אכילתו יטול ידיו שנית שתהא סמוכה נטילה לברכה אלא דלכתחלה דעת הב\"ח והמ\"א דצריך ליזהר בזה ועיין בבה\"ל מה שכתבנו עוד בזה. וכ\"ז לענין אכילה אבל להפסיק בדבור כשאינו רוצה לאכול ולשתות או להתעסק באיזה עסק אסור לכו\"ע [א\"ר וכ\"מ מכמה אחרונים לעיל בסימן קס\"ו]:","(ג) הב לן ונברך - פי' תן לנו כוס לברך וכשמברכין בלא כוס אם אומרים בואו ונברך ג\"כ דינא הכי דהוי היסח הדעת. וכן אם הסיח דעתו בהדיא בלבו מלשתות עוד ואח\"כ רוצה לשתות ג\"כ צריך לברך מתחלה על המשקה:","(ד) לשתות - ואם מסובין רק לשתיה ואמרו בואו ונברך ברכה אחרונה ג\"כ דינא הכי דהוי היסח הדעת ואסור לשתות עוד בלא ברכה:","(ה) ואכילה דינה כשתיה - דבגמרא לא נזכר בהדיא רק לענין שתיה וס\"ל דה\"ה לאכילה:","(ו) שסילק ידו מלאכול - ר\"ל אפילו גמר בדעתו שלא לאכול:","(ז) ואפילו סלקו השלחן - זהו מלשון רבינו יונה והיינו אף דס\"ל דזה חשיב היסח הדעת טפי מהב ונברך אפ\"ה לא מהני לענין אכילה ועיין מש\"כ בבה\"ל בדעת הרא\"ש בזה:","(ח) לחזור לאכילתו וכו' - כתב הט\"ז דאם מחמת אכילה זו שחזר לאכול נגרר לבו גם לשתיה א\"צ ברכה לדעה זו גם על השתיה דבתר אכילה גרירא אף שאמר מתחלה הב לן ונברך ולא מיירי השו\"ע בתחלה לענין שתיה דמצריך לברך לכו\"ע רק כשלא חזר גם לאכילה:","(ט) לא נסתלק - משום דדרך להגרר מאכילה קטנה לגדולה לא חשיב היסח הדעת גמור אלא כשנטל ידיו משא\"כ בשתיה בהיסח הדעת כל דהו כבר נסתלק משתייתו וצריך לברך שנית כשנמלך. ועיין בבה\"ל שהבאנו הרבה פוסקים שסוברים כדעת הרא\"ש דבהב ונברך חשיב גמר סעודה ואף באכילה אסור בלא ברכה וכן סתם המחבר לקמן בסימן קצ\"ז ס\"א עי\"ש וע\"כ לכתחלה בודאי יש ליזהר שלא לאכול אחר שאמר הב לן ונברך וכ\"פ בדה\"ח. ודע דמי שצריך ברכה באמצע סעודה צריך נטילה ג\"כ דכיון דהסיח דעתו לא שמר ידיו ורק ברכת נט\"י אין לו לברך:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>מי שסומך על שלחן אחרים אפי' אמר הב לן ונברך <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>לא הוי היסח <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>הדעת עד <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>שיאמר <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>בעל הבית:","m":["(י) לא הוי היסח הדעת - דודאי דעתו אם ירצה בעה\"ב לאכול ולשתות עמו יאכל וישתה עמו ואם בשעת אמירתו הסיח דעתו בבירור שאף שיאכל וישתה בעה\"ב לא יאכל וישתה עמו ונמלך אח\"כ צריך לברך [היינו לדעת רבינו יונה בשתיה לבד ולהרא\"ש אף באכילה] וכ\"ש כשנטל ידיו דמהני [מ\"א וש\"א]:","(יא) עד שיאמר בעה\"ב - ואז כל המסובין אסורין ודוקא כששתקו והסכימו לדבריו אבל אם האורח דעתו לאכול ולשתות עוד רשאי אף שאמר בעה\"ב הב ונברך וטוב שיגלה לפני המסובין שלא היה לו היסח הדעת שלא יחשבוהו כנמלך:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אם לא אמר הב לן ונברך וגם לא נטל ידיו <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>משנטל הכוס לברך הוי היסח הדעת:","m":["(יב) משנטל הכוס וכו' - ועדיף מהב לן ונברך דכיון שנטל הכוס בידו אפילו בשיחה אסור להפסיק כדלקמן בסימן קפ\"ג ס\"ו:","(יג) הוי היסח הדעת - ודינו כנטילת ידים [מ\"א] ולפ\"ז לדעת המחבר לעיל בס\"א אסור שוב בין באכילה ובין בשתיה לכו\"ע ועיין לעיל בסק\"ב במ\"ב מש\"כ לענין נטילת ידים:"]},{"s":"כשאדם נכנס לבית חבירו ויש שם חבורות הרבה שאוכלים <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>וכל אח' מושיט לו כוס <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>יש מי שאומר שמברך על כ\"א בורא פרי הגפן כי בכל פעם הוא <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>נמלך:","m":["(יד) כשאדם נכנס וכו' - היינו שלא קראוהו להיות נקבע עמהם לשתות ככל המסובין:","(טו) הרבה - וה\"ה בחבורה אחת כשכל אחד מושיט לו כוס דעל כל כוס וכוס הוי נמלך וכדלקמיה:","(טז) נמלך - דאינו יודע אם יושיטו לו כוס אחר ואפילו אם הושיטו לו כוס אחר בשעה דעדיין לא גמר לשתות כוס הראשון נמי דינא הכי דצריך לחזור ולברך עליו בפני עצמו כיון שבשעה שבירך לא היה דעתו ע\"ז שלא היה יודע שיושיטו לו עוד. וכ\"ז דוקא בסתמא אבל אם בשעת ברכתו היה דעתו שתעלה הברכה על כל מה שיתנו לו א\"צ לברך על כל כוס אף שלא היה יודע אז אם יתנו לו מ\"מ מהני דעתו לזה ובמקום שהמנהג שמושיטין כוסות הרבה למי שנכנס במסיבת הקבועים לשתיה אז אפילו בירך בסתמא על כוס אחד אמרינן דדעתו היה על כל מה שיתנו לו וא\"צ שוב לברך על כל כוס וכוס. ומ\"מ טוב יותר שיכוין בשעת ברכה על כל מה שיתנו לו:","(יז) הקרואים וכו' - דכיון שהם קרואים אף כשמברכין תחלה בסתמא ג\"כ דעתם על כל מה שיביאו לפניהם שיודעים דדרך בעה\"ב להביא הרבה מינים זה אחר זה. [ולא דמי לס\"ד הנ\"ל וכן לשמש בסימן קס\"ט ששם אינם יודעים שיתנו לו עוד ובודאי מסתמא לא ברכו אלא על מה שלפניהם לבד] ואף אם הסיחו דעתם אח\"כ שסברו שלא יביא להם עוד ג\"כ אין זה היסח הדעת גמור כיון דתלוים בדעת בעה\"ב וכנ\"ל בס\"ב ולכן אם הביא להם בעה\"ב אח\"כ א\"צ לחזור ולברך:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"4\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>הקרואים בבית בעה\"ב לאכול מיני פירות ומביאין להם בזה אחר זה <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>אינם צריכים לברך אלא על <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>הראשון:","m":[]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אכל כל מאכל ולא אכל מלח שתה כל משקה ולא שתה מים ביום ידאג מפני ריח הפה ובלילה מפני ריח הפה ומפני אסכרה <small> (פי' חולי חונק) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>והאוכל מלח אחר אכילתו לא יאכל בגודל <small> (גודל הוא האצבע הגס. אצבע הוא קרוב לגס. אמה הארוך. קמיצה הוא הסמוך לקטן. זרת הוא הקטן) </small> דקשה לקבור בנים ולא בזרת דקשה לעניות ולא באצבע דקשה לש\"ד אלא באמה ובקמיצה <small> (וע\"ל סי' ק\"ע למה אין אנו נוהגים באכילת מלח ושתיית מים):</small>","m":["(יח) למה אין אנו נוהגים - היינו משום דכל האכילות שלנו מעורב מתחלה במלח וכן כל המשקה שלנו כשכר ומי דבש וכדומה מעורב במים ע\"כ אין להקפיד ע\"ז מיהו בלא\"ה אין להקפיד בזמנינו דהאידנא נשתנו הטבעים [מ\"א]:\n"]}],"180":[{"s":"<b>דיני פרורי הפת. ובו ה סעיפים:</b><br><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אין להסיר המפה והלחם עד אחר ברכת <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>המזון:","m":["(א) אין להסיר - כדי שיהא ניכר לכל שמברכין להשי\"ת על חסדו וטובו הגדול שהכין מזון לכל בריותיו וגם דהברכה אינה שורה על דבר ריק אלא כשיש שם דבר כענין פך שמן של אלישע:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>כל מי שאינו משייר פת על שלחנו אינו רואה סימן ברכה לעולם אבל <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>לא יביא פת <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>שלימה ויתננה על השלחן ואם עשה כן מחזי דלשם ע\"א עביד שנאמר העורכים לגד שלחן:","m":["(ב) כל מי שאינו וכו' - דצריך לשייר כדי שיהא מזומן לעני שיבוא וכעין שאמרו חז\"ל המאריך בשלחנו מאריכין לו ימיו דלמא אתא עניא ויהיב לו וגם כדי שיודה להשי\"ת על חסדו שהשפיע לנו מטובו ששבענו והותרנו כדכתיב אכול והותר:","(ג) אינו רואה סימן ברכה - כדכתיב אין שריד לאכלו על כן לא יחיל טובו וכתב של\"ה דראוי ונכון שיתן להעני הטוב שבשלחן ובפרט אם הוא עני חשוב שמזה יראה לו שמקבלו בסבר פנים יפות. ומשבח אני את הקהלות שמחזיקין לומדים בחורים על שלחנם כל השנה כאחד מבניהם ובזה יוצא הבעה\"ב בשני דברים מצות חלק עניים וגם מצות דברי תורה על השלחן דסתם בחור כזה עני הוא וגם ידבר בדברי תורה על השלחן ובודאי מה שנאכל על השלחן שחרית וערבית נחשב כשני תמידין וכו' עכ\"ל והובא בא\"ר:","(ד) אבל וכו' - ר\"ל אם יש פתיתין על השלחן אבל אם אין פתיתין על השלחן מותר להביא אפילו שלמה ובשם הזוהר כתבו שטוב לעשות כן לכתחלה:","(ה) לא יביא וכו' - עיין במ\"א שכתב דה\"ה אם יש שלמה על השלחן לא יביא פתיתין ופמ\"ג כתב דה\"ה לא ישייר פתיתין על שלחנו כשיש שלמה ויש מקילין בדבר שא\"צ להסירן מעל השלחן ובפרט בשבת בודאי לא יסירן עד לאחר בהמ\"ז בין הפתיתין ובין השלמה שהכל יודעין שבשביל כבוד שבת הוא מונח:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>קודם שיטול ידיו יכבד הבית שלא ישארו שם פירורין וימאסו במים של נטילה אף על פי שמותר לאבד פרורין שאין בהם כזית שמא יהא השמש עם הארץ שמותר להשתמש בשמש עם הארץ ויניח גם פרורים שיש בהם כזית שאסור לאבדן ביד לכך יכבד תחלה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ועכשיו אין אנו נוהגים כך מפני שאין אנו מסלקין השלחן <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ואנו נוטלים הידים חוץ לשלחן במקום שאין שם פירורים וליכא למיחש למידי:","m":["(ו) קודם שיטול ידיו - למים אחרונים:","(ז) יכבד הבית - מקום שאכלו שם אם הסיבו ע\"ג קרקע מכבדין את הקרקע או אם הסיבו על השלחן מכבדין את השלחן משיורי אוכלין שנתפזרו שם [רש\"י] ותר\"י פירשו דהכיבוד הוא במקום שדרך לסלק השלחן קודם נטילה לבהמ\"ז צריך לכבד הקרקע של מקום השלחן דחיישינן שנתפזרו שם פירורי פת ובאופן זה מיירי המחבר כאן שכתב דעכשיו שאין מסלקין א\"צ לכבד והיינו הקרקע שתחת השלחן אבל כשנוטלין הידים בכלי על השלחן כמנהגנו לכו\"ע צריך לנקות הפירורין סביב וכדלקמיה:","(ח) שאין אנו מסלקין - משמע דמלפנים היו נוהגין לסלק וצ\"ל דהיינו מלפני כל המסובין אבל מלפני המברך לא וכמו שכתב בס\"א שאין להסיר וכו':","(ט) ואנו נוטלים וכו' - ואם יושבין במקומן ונוטלין הידים בכלי על השלחן אף עכשיו הדין הוא שצריך לנקות השלחן עצמו מפירורי הפת שלא ימאסו מנצוצי מי הנטילה וכנ\"ל מרש\"י ונראה דמ\"מ ישאיר לחם על השלחן במקצוע אחד שיהיה מונח עד אחר בהמ\"ז וכנ\"ל בס\"א ויהיה קצת רחוק ממקום הזה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אע\"פ שמותר לאבד פירורין שאין בהם כזית מכל מקום <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>קשה <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i>לעניות:","m":["(י) קשה לעניות - ודוקא לדרוס עליהם דהוא בזוי גדול אבל כשמשליכן למים אפילו כשנאבדין עי\"ז אין חשש כיון שהוא פחות מכזית ויש מחמירין כשיש הרבה פירורין ויצטרפו לכזית:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>נוהגים לכסות <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"4\"></i>הסכין בשעת ברכת המזון ונהגו <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>שלא לכסותו בשבת ויום טוב:","m":["(יא) לכסות הסכין - בב\"י ב' טעמים האחד דברזל מקצר ימי האדם ואינו דין שיהיה מונח על השלחן שדומה למזבח שמאריך ימי האדם דע\"כ כתיב לא תניף עליהם ברזל וע\"כ אחר שגמר אכילתו ורוצה לברך בהמ\"ז מכסה הסכין וטעם שני בשם רבינו שמחה לפי שפעם אחד הגיע אחד לברכת בונה ירושלים ונזכר חורבן הבית ותקע סכין בבטנו וע\"כ נהגו לסלקו בשעת ברכה:","(יב) ונהגו שלא לכסותו וכו' - הטעם שאין מקפידין ע\"ז בשבת ויו\"ט עיין באחרונים:"]}],"181":[{"s":"<b>דיני מים אחרונים. ובו י סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>מים אחרונים <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>חובה:","m":["(א) מים אחרונים וכו' - הטעם משום שהידים מזוהמות הן מן האכילה ופסולות לברכה וסמכו חז\"ל אקרא דוהתקדשתם והייתם קדושים והתקדשתם אלו מים ראשונים (שיקדשו ידיהם קודם האכילה לטהרם מטומאה כמו שנתבאר לעיל בסימן קנ\"ח) והייתם קדושים אלו מים אחרונים ואפילו למי שאינו מברך בעצמו אלא שומע לצאת מפי המברך ויותר מזה אפילו כשאין ידיו מזוהמות כלל מן האכילה ג\"כ חייבו חז\"ל בנטילת מים אחרונים והוא מפני חשש מלח סדומית דבכל סעודה הלא נמצא מלח ויש לחוש שמא מעורב בהן מעט ממלח סדומית שמסמא העינים למי שנוגע בם ואח\"כ יגע בעיניו ואף עכשיו שאין מצוי מלח סדומית בינינו יש לחוש למלח אחר שטבעה כמותה ועיין בסעיף י':","(ב) חובה - ואם יש לו מים מצומצמים צריך למעט במים ראשונים כפי שיעור המבואר בסימן קס\"ב סעיף ב' בכדי שישאר לו מעט למים אחרונים ואם אין לו רק כפי שיעור מים ראשונים הם קודמים אפילו למי שנזהר תמיד במים אחרונים דהאידנא דאין מצוי מלח סדומית בינינו אינם חובה כ\"כ כמו מים ראשונים יש אומרים דמתחלה אין לו לאכול אא\"כ יודע שיהיה לו ג\"כ מים אחרונים ומ\"מ אין החיוב עליו יותר ממים ראשונים דהיינו בלפניו ד' מילין ולאחריו מיל ואם בתוך שיעור זה לא נמצא מים אעפ\"כ מותר לו לאכול וגם לברך אח\"כ בהמ\"ז וכל אימת שימצא מים אח\"כ יטול ידיו משום חשש מלח סדומית:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>מים אחרונים אין נוטלי' על גבי קרקע <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>אלא <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>בכלי מפני רוח רעה ששורה עליהם ואם אין לו כלי נוטל על גבי <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>עצים דקים וכיוצא בהן:","m":["(ג) אלא בכלי - ולא יתחוב ידיו בתוך הכלי לרוחצם אלא ישפוך המים על ידיו שירד לתוך הכלי:","(ד) מפני רוח רעה - ויש חשש סכנה לעובר עליהם ובמקום שאין עוברים שם יכולים ליטול ע\"ג קרקע ולכן מותר ליטלם תחת השלחן ואע\"ג שלפעמים מסלקין השלחן מ\"מ יתנגבו ביני וביני:","(ה) ואם אין לו כלי - דכשיש לו כלי ישפכם דוקא בתוך הכלי:","(ו) וכיוצא בהם - כמו אבנים דקים וקוצים וכל כה\"ג שנבלעים בהם המים ואינם מתקבצים למקום אחד ויש מקילין ליטול אף ע\"ג רצפה אם אין לו כלי ליטול בתוכו דס\"ל דדוקא ע\"ג קרקע ממש שורה עליהם רוח רעה אבל לפי מה שכתב הלבוש יש להחמיר בזה:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אין נוטלי' בחמין <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>שהיד <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>נכוית בהם מפני שמפעפעין <small>[פי' מבעבעין מל' שחין אבעבעות] </small> את הידים ואין מעבירין את הזוהמא:","m":["(ז) בחמין - אבל פושרין דהיינו שאין היד סולדת בהן מותר ורש\"ל פסק דוקא בצוננין ומיהו אם אין לו כ\"א אלו הפושרין בודאי אין להחמיר:","(ח) נכוית בהם - ל\"ד דבודאי אין אדם נוטל ידיו במים כאלו שיכוה בהן אלא ר\"ל שהיד סולדת בהן ושיעורו כל שכריסו של תינוק נכוית בו [מ\"א]:","(ט) שמפעפעין - מרככין את הידים ומבליעין בהן את זוהמת התבשיל [רש\"י] ונ\"ל דחמין שנצטננו מותר ליטול בהן:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אין צריך ליטול אלא <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>עד <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>פרק שני של אצבעות:","m":["(י) עד פרק שני - שלמעלה משני פרקי אצבעות אין מגיע לכלוך המאכל [ומן אצבע האגודל צריך ליטול פרק ראשון] ואם היה המאכל מגיע מכאן ואילך צריך רחיצה גם למעלה [א\"ר בשם בלבו] ועיין בבה\"ל. ורע עלי המעשה שראיתי שיש אנשים אשר המה זהירים בנטילת מים האחרונים אבל אינם יוצאים חובת הדין כלל וכלל דאינם נותנים כ\"א איזה טיפים מים על ראשי האצבעות עד אשר אפילו עד סוף פרק הראשון אינה מגעת ולפעמים יוצאים בנגיעה בעלמא במים וידיהם נשארים מטונפות מזוהמת המאכל כבראשונה ובאמת מן הדין צריך לרחוץ לפחות עד סוף שני פרקי אצבעות וכנ\"ל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>צריך שישפיל ראשי אצבעותיו למטה כדי שתרד הזוהמא:","m":["(יא) שתרד הזוהמא - מן הלכלוך שבידיו ע\"י הנטילה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>אם המסובין רבים עד חמשה מתחילין מן המברך ואם הם יותר <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>מתחילין מן הקטן ונוטלי' דרך ישיבתן ואין מכבדין זה את זה ליטול עד שמגיעין <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"6\"></i>לחמשה האחרונים וכיון שלא נשארו אלא חמשה שלא נטלו <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>מתחילין מן המברך:","m":["(יב) מתחילין מן המברך - כדי שיעיין בארבע ברכות של בהמ\"ז בתוך הזמן שיטלו אלו הד' אנשים הנשארים ואע\"ג דהיום המנהג שכל אחד מהמסובין מברך לעצמו ואין יוצאין בברכתו מ\"מ לא נשתנה הדין דגם היום מהנכון שיאמרו המסובין כל ברכה וברכה בלחש עם המברך שמברך בקול רם כדאיתא לקמן בסימן קפ\"ג ס\"ז וגם ברכת הזימון צריך המברך לומר לפניהם משו\"ה צריך לעיין קצת מתחלה:","(יג) מן הקטן - היושב בסוף המסבה והטעם הוא כדי שלא יהא צריך המברך להמתין הרבה אחר נטילתו עד שיטלו כולם וגנאי הוא לו וגם דהוי הפסק:","(יד) ואין מכבדין וכו' - דאין זה כיבוד במה שירמוז לו שהוא ירחץ תחלה ידיו המזוהמות:","(טו) מתחילין וכו' - כדי שבשיעור הזמן שיטלו הד' את ידיהם יוכל הוא לעיין בבהמ\"ז וכנ\"ל ואף דקי\"ל דתיכף לנטילה ברכה בשיעור זה לא חשיב הפסק ומיהו אפשר דבכדי אין להפסיק כלל:","(טז) מן המברך - וכיון שנטל הוא ידיו אותן הד' שאצלו אין מכבדין זה את זה אלא דרך ישיבתן נוטלין:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אין מברכין שום ברכה על מים האחרונים:","m":["(יז) אין מברכין וכו' - דלפי הטעם שבארנו לעיל בסק\"א משום חשש מלח סדומית דהוא סכנה לעינים בודאי אין שייך לברך על נטילה זו כמו שאין מברכין על שמירה משאר סכנות כגון המסנן מים בלילה מפני סכנת עלוקה וכיוצא בזה ואפילו לפי הטעם הראשון שכתבנו לעיל דהנטילה היא כדי להסיר הזוהמא מעל ידיו קודם בהמ\"ז שלפי טעם זה היה ראוי לברך על נטילה זו מ\"מ לא נהגו כן לפי שעכשיו אין עושין המצוה כתקנת חכמים ומנהגם שהיו נוהגים למשוח הידים גם בשמן ערב אחר הנטילה להעביר את הזוהמא מהידים וכיון שאין אנו עושים המצוה כתיקונה נהגו שלא לברך בכל גוונא:","(יח) אינן צריכין ניגוב - כיון שאינם באים רק לנקות את הידים גם בלא ניגוב הן נקיות:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>י\"א שמים אחרונים אינם צריכים נגוב ולהרמב\"ם <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>מנגב ואח\"כ <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>מברך:","m":["(יט) ולהרמב\"ם וכו' - ס\"ל דלא נקרא נטילה בלי נגוב ועיין לעיל סוף סימן קע\"ג משמע דעת המחבר להקל בזה מ\"מ לכתחלה טוב לנגב ידיו לצאת דעת כולם [ח\"א]. כתב הב\"י בשם ספר שלחן של ארבע וכן הביא בא\"ר בשם הכלבו דמים אחרונים אין צריכין שיעור אלא שיהא בהן כדי להדיח בהן את ידיו ובספר מעשה רב הביא דהנהגת הגר\"א היתה ברביעית:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>מים אחרונים נוטלים <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>בכל מיני <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>משקים:","m":["(כ) נוטלים בכל וכו' - שגם הם מנקין הידים מזוהמא כמו מים ומיירי באין לו מים כ\"א משקין הא יש לו מים אין ליטול במשקין [פמ\"ג]:","(כא) מיני משקין - אפילו בשמן ודבש וחלב חוץ מיין מפני חשיבותו. כתבו האחרונים שכל מיני מים הפסולים לראשונים דהיינו שנעשה בהן מלאכה או שנשתנו מראיהן ואפילו מים שנפסלו משתית בהמה וכה\"ג מ\"מ כשרים לאחרונים וגם אין צריך להם כלי וכח גברא כראשונים ואין חציצת הידים פוסלת בהן. גם אין צריך לשפוך על ידיו אלא פעם אחת:","(כב) שאין נוהגים וכו' - מפני שאין מלח סדומית מצוי בינינו ומשום ידים מזוהמות אין חוששין הואיל ועכשיו אין מקפידין לרחצן מלכלוך המאכל אין זה קרוי זוהמא לנו. ודעת הגר\"א בביאורו דצריך ליטול גם האידנא [דטעם מלח סדומית וידים מזוהמות גם עתה שייך וכמ\"ש בס\"א] וכ\"כ המ\"א בשם המקובלים דכל אדם יזהר במים אחרונים וכן החמיר המהרש\"ל בים של שלמה וכ\"כ הברכי יוסף ע\"ש שהחמיר הרבה בזה:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i>יש <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>שאין נוהגין ליטול מים אחרונים ואפילו לנוהגי' כן אדם שהוא אסטניס ורגיל ליטול ידיו אחר הסעודה לדידיה <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>הוו ידים מזוהמות <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>וצריך ליטול ידיו קודם ברכת המזון:","m":["(כג) וצריך ליטול ידיו וכו' - ר\"ל דזה מדינא צריך ליטול ידיו במים אחרונים לכו\"ע וכתבו האחרונים שאפילו רוצה לברך על היין או פירות באמצע הסעודה צריך לקנחם מקודם כיון שידיו מלוכלכות והוא איסטניס:","(כד) קודם בהמ\"ז - וצריך ליזהר שלא להפסיק בין הנטילה לבהמ\"ז אפילו בד\"ת:"]}],"182":[{"s":"<b>דיני כוס בהמ\"ז ושלא יהיה פגום. ובו ז סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>יש אומרים שברכת המזון טעונה כוס אפילו <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>ביחיד וצריך לחזור עליו <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>ולא יאכל אם אין לו כוס לברך עליו אם הוא מצפה ואפשר שיהיה לו אפי' אם צריך לעבור זמן אכילה אחת <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ולפי זה אם שני' אוכלים יחד צריך לקחת כל אחד כוס לברכת המזון <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ויש אומרי' שאינה טעונה כוס אלא בשלשה ויש <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אומרים שאינה טעונה כוס כלל אפילו בשלשה: <small>הגה ומ\"מ מצוה מן המובחר לברך על הכוס: [ר\"ן פ' ערבי פסחים]:</small>","m":["(א) טעונה כוס - שברוב הברכות שתקנו חז\"ל תקנום לסדר על הכוס מפני שכן הוא דרך כבוד ושבח נאה להקב\"ה לסדר שבחו וברכתו ית' על הכוס וכמו שכתוב כוס ישועות אשא ובשם ה' אקרא (לבוש):","(ב) ולא יאכל וכו' - וכמו לענין הבדלה ברצ\"ו דאם מצפה שיהיה לו כוס למחר מבטל סעודת לילה וימתין על הכוס ועיין במ\"א שחולק על זה דמשום כוס בבהמ\"ז אין למנוע מלאכול ולא דמי להבדלה עיין שם ובביאור הגר\"א משמע ג\"כ דמסכים עם המ\"א:","(ג) אם שנים אוכלים וכו' - דבשלשה ויותר שמזמנין יחד אחד מברך על הכוס ומוציא את כולם כמו שמוציאם בברכת הזימון אבל בשנים דמצוה ליחלק ואין אחד מוציא את חבירו א\"כ צריך כל אחד גם כוס בפני עצמו:","(ד) מן המובחר וכו' - ר\"ל דאף לדעה זו שאין טעון כוס כלל היינו שאין בה חיוב אבל כו\"ע מודים דמצוה מן המובחר לברך על הכוס אם יש לו יין בביתו. והנה המחבר לא הכריע בין הדעות ודעת רש\"ל וב\"ח להחמיר דבהמ\"ז צריך כוס מדינא ומנהג העולם להקל בזה כדעה השלישית שלא לחזר אחר כוס אם לא כשיש לו יין או שאר משקין דהוא חמר מדינה בביתו דאז בודאי מצוה מן המובחר לכו\"ע לברך על הכוס וכנ\"ל ודוקא כשהוא בזימון שלשה אבל לענין יחיד מקילים כמה אחרונים לגמרי ועיין לקמיה בסוף ס\"ב בהג\"ה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>כוס ברכת המזון אינו אלא של יין ולא משאר משקים אפילו קבע סעודתו עליהם <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ואם אין <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>יין מצוי באותו מקום והשכר או שאר משקין הוו חמר <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>מדינה מברכין עליהם <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>חוץ מן המים: <small>הגה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>ומה שנוהגין במדינות אלו <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>לברך על השכר אין למחות דהא יש אומרים דאינו טעון כוס כלל ועוד דהא עיקר חמר מדינה הוא שכר <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>וקובעין הסעודה עליו ואע\"ג דיין נמצא בעיר מ\"מ לא מקרי מצוי לדבר זה שהוא ביוקר <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>ואי אפשר לקנות יין בכל סעודה לברך עליו אמנם המצוה מן המובחר לברך על יין [ד\"ע] <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ויש מדקדקין כשמברכין ביחיד על היין <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>שלא לאחוז הכוס בידם רק מניחין אותו על השלחן לפניהם ונכון מנהג זה <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>על דרך הקבלה (ב\"י):</small>","m":["(ה) ולא משאר משקים - כמו לענין קידוש והבדלה דאינו על שאר משקין לכו\"ע במקום דלא הויין חמר מדינה:","(ו) אפילו קבע סעודתו - ר\"ל שתוך הסעודה סמך על משקה והיה עיקר שתייתו מהם אפי' הכי אין זה מחשב אותם לברך עליהם בהמ\"ז כיון דאין אנשי העיר רגילין לשתותו תמיד במקום הזה:","(ז) אין יין מצוי - ואפי' נמצא יין בעיר אלא שאינו מצוי הרבה ומפני זה עיקר שתיית בני העיר הוא שכר ושאר משקין יש להקל לברך בהמ\"ז על שכר ועיין בב\"ח שכתב דאף דאינו מחויב להדר שם אחר יין לקנותו מן החנוני מ\"מ אם יש לו יין בביתו יברך על היין:","(ח) באותו מקום - היינו בכל העיר אף שבשאר עיירות במדינה זו נמצא יין הרבה:","(ט) מברכין עליהם - ואם יש לו שני מיני משקין כגון שכר ומי דבש וכיו\"ב ואחד מהן חביב עליו יברך על אותו המין שהוא חביב עליו וכ\"ש אם מתחלה קודם בהמ\"ז שתה ממנו מפני חביבותו בודאי מהנכון לברך ג\"כ עליו ולא על משקה האחר שלא יהא שלחנך מלא ושלחן רבך ריקם אבל כ\"ז דוקא אם אותו המין הוא חמר מדינה דהיינו שרגילין לשתותו במקום ההוא אבל אם אין שותין אותו אלא לפרקים אף דבעצם הוא חשיב יותר מחבירו לא הוי חמר מדינה מידי דהוי אשאר משקין כגון יין תפוחים ויין רמונים:","(י) חוץ מן המים - אע\"פ שרוב שתייתן מים אין מברכין עליו וה\"ה קווא\"ס ומי בארש\"ט אע\"פ שרוב שתית ההמונים מהם אפ\"ה לא חשיבי יותר ממים וטישביר אפשר דיש להקל בשעת הדחק כשרוב ההמונים שותין מהם ועיין בסימן רצ\"ו במ\"ב סק\"י מה שכתבנו שם:","(יא) ומה שנוהגין וכו' - ר\"ל שנוהגין לברך על השכר אע\"ג דיין מצוי בעיר:","(יב) וקובעין הסעודה עליו - ר\"ל אף אם לא נחשיב אותו לחמר מדינה כ\"כ מפני שמצוי גם יין שם מ\"מ בלא\"ה י\"א דאם קבע סעודתו מתחלה על שאר משקין מחשיב אותם בזה ומברך עליהם בהמ\"ז אף דאיכא יין אלא דהמחבר סתם מעיקרא כהפוסקים דלא מהני קביעותא מ\"מ יש לצרף דעה זו להקל בזה שהיין ביוקר וקשה להשיגו:","(יג) ואי אפשר וכו' - אבל לענין קידוש והבדלה משמע דגם רמ\"א מודה דצריך לחזר דוקא אחר יין כיון דיין נמצא בעיר אלא שהוא ביוקר:","(יד) לקנות יין בכל סעודה - אבל אם יש לו יין בביתו צריך לברך עליו [ב\"ח] ואם יש לו יין בביתו רק מעט לצורך קידוש והבדלה א\"צ לברך עליו דקידוש והבדלה לכו\"ע טעון כוס וחמיר מבהמ\"ז:","(טו) שלא לאחוז - דהמדקדקים שמברכין על הכוס הוא לצאת ידי דעה הראשונה שבסעיף א' דגם ביחיד טעון כוס ורק דמהזוהר משמע דיחיד לא יברך על הכוס וע\"כ מברכין ואין אוחזין בידם ובזה יוצאים ידי הכל דאפילו האומרים טעונה כוס הרי הכוס לפניו על השלחן ואחיזתו אינה אלא למצוה מן המובחר לד\"ה:","(טז) ונכון מנהג זה וכו' - ר\"ל מה שאין אוחזין אותו בידים וכנ\"ל וכהיום מנהג העולם שאין מברכין על הכוס כלל ביחיד:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>צריך שלא יהא פגום שאם שתה ממנו <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>פגמו <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>אבל אם שפך ממנו <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>לתוך ידו או כלי אין בכך כלום ואפי' שתה <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>מהכד או מחבית קטנה הוי פגום אבל אם <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>שתה מחבית של עץ גדולה <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>אין להקפיד <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>יש מי שאומ' שאפי' מים פגומים פסולים למזוג בהם כוס של ברכ':","m":["(יז) פגמו - ואינו ראוי עוד לברך עליו בהמ\"ז וה\"ה לקידוש ולהבדלה וכדלקמן בסימן רע\"א ס\"י וסימן רצ\"ו ס\"א ואפילו טעם ממנו רק משהו בעלמא:","(יח) לתוך ידו - וה\"ה אם טעמו באצבעו דדוקא אם שתה ממנו בפיו פגמו:","(יט) אין בכך כלום - והוא שלא שפך אלא מעט בענין שעדיין שם מלא עליו או שאח\"כ שפכו לתוך כוס קטן ממנו והוא מלא או שזרק לתוכו פירור פת להגביה היין שיהא הכוס מלא שאצ\"ל מלא כולו מיין כי די ברביעית רק שלא יהא הכוס חסר וכדלקמיה:","(כ) הוי פגום - ר\"ל כל מה שיש בזו החבית אף ששפכו אח\"כ לכלים אחרים:","(כא) אין להקפיד - ויש מחמירין אף בזה ויש לחוש לדבריהם לכתחלה שלא להניח לשתות אפילו מפי ברזא מחבית גדולה:","(כב) פסולים למזוג - לכאורה אמאי לא אמרינן קמא קמא בטיל כמו בס\"ה ואפשר דמיירי שהיין חי דא\"א לשתות בלי מזיגה ולכך לא בטיל:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>אם היו כוסות המסובין פגומים <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>צריך לתת מכוס הברכה <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>לתוכם <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>ויש מי שאומר שאינו צריך <small>[וע\"ל סי' ק\"ץ וסי' ער\"א]:</small>","m":["(כג) אם היו וכו' - פי' דפעמים שנותנין כוס לכל אחד ואחד מן המסובין וכשבירך המברך בפה\"ג שותים כל אחד כוסו ואם היו שלהם פגומים צריך שיתן המברך מכוסו מעט לכל אחד ואחד קודם שישתה ויתקן פגימתם וישתו כולם מכוס שאינו פגום:","(כד) מכוס הברכה - ואם רק המברך לבדו אוחז כוס בידו אף שאז המסובין בע\"כ טועמין מכוס פגום אחר ששתה הוא לא איכפת לן כיון דמתחלה היה כוס שלם וכולהו כחד חשיבי:","(כה) ויש מי שאומר וכו' - דס\"ל דלא קפדינן על כוס פגום אלא על המברך ולא על המסובין:","(כו) עיין לקמן וכו' - ר\"ל דשם סתם המחבר כסברא הראשונה:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>אם החזיר יין של כוס פגום לקנקן היין שבקנקן כשר <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i>משום <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>דקמא קמא בטיל:","m":["(כז) כשר - ודוקא בדיעבד אבל לכתחלה אסור לעשות כן ולכן נוהגין להוסיף עליו מתחלה מעט מהקנקן ובזה מתוקן כמו בס\"ו ואח\"כ שופכין אותו להקנקן ואז כשר היין להוציא לברכה:","(כח) דקמא קמא בטל - ובלבד שיהיה היין שבקנקן יותר מהיין שבכוס:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"10\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"4\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>יכולין לתקן כוס פגום ע\"י שיוסיפו מעט יין ואפי' ע\"י שיוסיפו עליו <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>מים מיתקן:","m":["(כט) יכולין לתקן - דענין פגום אינו פסול ממש אלא פגם בעלמא משום ששתה ממנו מעט ולכך כשחוזר ומוסיף עליו נעשה מתוקן בכך:","(ל) מים - ודוקא שהיין חזק שאינו מתקלקל ע\"י המזיגה. ולאו דוקא במים דה\"ה בשאר משקין [א\"ר]:","(לא) מיתקן - והוא שלא יהיו המים עצמם פגומים שלא שתו מהם דאל\"ה א\"א לתקן בהם לי\"א בס\"ג דגם מים נפגמים בשתיה:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"12\"></i><i data-commentator=\"Turei Zahav\" data-order=\"7\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>בשעת <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"10\"></i>הדחק מברכין על כוס פגום:","m":["(לב) בשעת הדחק - שאין לו כוס אחר ואין לו במה לתקן הכוס זה וקמ\"ל דהו\"א דמוטב לברך בלא כוס כלל קמ\"ל דענין פגום הוא רק לכתחלה אם יכול ליזהר בזה ולא לעיכובא. כתבו האחרונים דכשצריך לברך על כוס פגום אם יש לו כוס קטן המחזיק רביעית ישפוך מהגדול לתוכו דעי\"ז נמי מתקן הפגימה קצת. יש שמתקנים הפגימה ע\"י נתינת פירור פת והטור דחה מנהג זה דלא מהני זה לפגימה. ואם אינו פגום רק שאינו מלא ובמה שיש בהכוס יש בו שיעור רביעית לכו\"ע מהני המלוי אפי' ע\"י פת ודוקא בחתיכה א' דבהרבה יש בו משום מיאוס דהקריבהו נא וגו' וגם אדרבה צריך להדיח הכוס מפירורי פת וכדלקמן בסי' קפ\"ג ס\"א [אחרונים]:\n"]}],"183":[{"s":"<b>המברך איך יתנהג בכוס של בהמ\"ז. ובו יב סעיפים:</b><br><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>כוס של ברכה טעון הדחה מבפנים ושטיפה מבחוץ <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ואם הוא נקי ואין בו <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>שיורי <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>כוסות אינו צריך:","m":["(א) טעון הדחה וכו' - וה\"ה אם קנחו במפה עד שהוא נקי דשרי:","(ב) שיורי כוסות - שיורי יין ששרה בו פת:","(ג) אינו צריך - וטוב להדיח אפילו כשאין בו שיורי פת אם לא שהוא נקי וצח [א\"ר]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>יתן היין לתוכו חי עד שמגיע לברכת הארץ ואז <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>מוזגו להודיע שבח הארץ: <small>הגה וי\"א דאם היין אינו חזק אינו צריך למוזגו [טור] וכן נוהגים <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>באלו הארצות ויוציאנו מן החבית <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>לשם <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ברכה [טור בשם רש\"י] ונראה דלדידן שאין לנו הרבה יין א\"צ רק לשפכו מן הקנקן ששומרים בו היין לשם ברכה וחבית לאו דוקא וכן נוהגין במדינות אלו וכוס של ברכה ימלאנו שיהא <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>מלא על כל גדותיו:</small>","m":["(ד) חי - פי' כמו שהוא בלי מזיגה אף שאין ראוי לשתותו כך כמות שהוא:","(ה) לברכת הארץ - פי' לתחלת ברכת הארץ:","(ו) שבח הארץ - שיינה חזק שצריך למוזגה במים ועיין בב\"י שכתב דבמדינתו נהגו העולם למזוג במעט מים אף כשאין היינות חזקים ע\"ש הטעם:","(ז) אין צריך למוזגו - משום דראוי לשתותו כמות שהוא:","(ח) לשם ברכה - היינו שיוציאנו סמוך לברכה מן החבית לשם ברכה ולא יוציאנו מקודם וישתהא בכלי וזהו רק למצוה מן המובחר:","(ט) שיהא מלא וכו' - ואף שרגיל לישפך קצת עי\"ז לארץ ויש שאין ממלאין אותו כ\"כ מטעם זה ואפ\"ה שם מלא עליו. ודע דמלא הוא רק למצוה לכתחלה ואינו מעכב אם אך יש בהיין שיעור רביעית וכמו שכתבתי בסימן רע\"א במ\"ב סקמ\"ב עי\"ש:","(י) לחזור וכו' - מלשון זה משמע דהוא רק לכתחלה ואין עיכוב בדבר:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>צריך לחזור <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אחר <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>כוס <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>שלם:","m":["(יא) שלם - שלא יהיה גוף הכוס שבור ולא פגום בשפתו אפילו חסרון מועט [ובנסדק יש להקפיד לכתחלה אפילו בלא חסרון כלל] וכן אם גוף הכוס שלם רק בסיסו נשבר ג\"כ יש להקפיד ואפילו יכול לעמוד על בסיסו אם לא שאין לו אחר יש להקל בכל זה. ובכיסוי כלים אף שלא נעשו לקבלה ג\"כ אין להקפיד אם אין לו אחר [א\"ר]. כתב המ\"א בשם הב\"ח ירא שמים לא יברך במצנפת רק ישים הכובע על ראשו ויש שנוהגין ג\"כ להתעטף בבגד העליון דכל זה הוא בכלל עיטוף הנאמר בגמרא אצל כוס ברכה וכן נהגו כהיום בישראל בעת בהמ\"ז שמשימין הכובע על ראשיהן אפילו כשהוא מברך ביחיד בלי כוס:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>מקבלו <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>בשתי ידיו וכשמתחיל לברך נוטלו <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>בימינו ולא יסייע בשמאל: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>והיינו דוקא שלא תגע השמאל בכוס אבל אם נותן השמאל <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>תחת הימין <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>לסייעה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>מותר [ב\"י בשם שבולי הלקט] </small> ומגביהו מהקרקע טפח אם הוא יושב על גבי קרקע <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ואם הוא מיסב בשלחן מגביהו מעל השלחן טפח <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ונותן בו עיניו שלא יסיח דעתו: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>וע\"כ אין לוקחין כוס שפיו צר <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>שקורין <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>גלוק גלא\"ז לברך עליו <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i></small> ומשגרו <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"8\"></i>לאשתו שתשתה ממנו:","m":["(יב) מקבלו בשתי ידיו וכו' - כתב הט\"ז דהטעם הוא כדי להראות חביבות קבלת הכוס עליו ואח\"כ אוחזו ביד אחד שלא יהא נראה עליו כמשוי וביד ימין שהוא העיקר והחשוב:","(יג) שלא תגע וכו' - היינו אפילו אם ירצה לאחוז הכוס ביד ימינו באמצע הכוס וביד שמאלו יאחזנו מתחתיו:","(יד) לסייעה - פי' שהכוס מונח על כף ימין ונותן השמאל מתחת לסמוך יד הימין:","(טו) מותר - כיון שאין נוגע בהכוס והאחרונים כתבו דיש להחמיר בזה אם לא לצורך. כתב השל\"ה ע\"פ הקבלה נכון שיעמיד הכוס על כף ימינו והאצבעות יהיו זקופים סביב. לא יטול הכוס בבתי ידים רק יסירם מקודם:","(טז) ומגביהו וכו' - כדי שיהא נראה הכוס לכל המסובין ויסתכלו בו [טור] ובגמרא מסמיך לה אקרא דכתיב כוס ישועות אשא וגו':","(יז) שלא יסיח דעתו - מן הברכה:","(יח) וע\"כ אין לוקחין וכו' - שלא יוכלו להסתכל במה שבתוכו והאחרונים הקשו ע\"ז דכוונת הגמרא מה שאמרו ונותן עיניו בו היינו בהכוס ולא במה שבתוכו וע\"כ אין להקפיד בזה אם אינו יכול להשיג בקל כלי אחר:","(יט) ומשגרו לאשתו וכו' - שע\"י כוס של ברכה מתברכת האשה ואפילו לא אכלה האשה עמהם ואם יש עוד אורחים אצלו יתן גם להם לטעום מהכוס של ברכה וכמבואר לקמן בסימן ק\"צ ס\"א ובסימן רע\"א סי\"ד ע\"ש ואם אורח מיסב אצל בעה\"ב ובירך על הכוס יתן גם לבעה\"ב לשתות מכוס של ברכה כדי שיתברך הבעה\"ב:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>יש מי שאומר שאם המברך <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>אטר <small> (בלע\"ז מנצינ\"ו) </small> אוחז הכוס בימינו שהוא שמאל כל אדם:","m":["(כ) שהוא שמאל כל אדם - ואם הוא שולט בשתי ידיו אוחז בימין שהוא ימין לכל אדם. ודע דמה דהוזכר מסעיף ד' עד סעיף זה הסכים בביאור הגר\"א דהוא רק להידור מצוה לכתחלה:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>משנתנו לו כוס לברך <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>לא ישיח המברך <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>והמסובין אין להם להשיח <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>משהתחיל המברך לא מבעיא בשעה שהוא מברך שצריך לשמוע ולהבין מה שאומר המברך אלא אפילו בין ברכה לברכה אין להם להשיח ואם עברו ושחו בין ברכה לברכה בשעה שהמברך שותק מעט <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>יצאו: <small>הגה אפי' אם סח המברך עצמו <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i></small> אבל אם שחו בשעה שהוא מברך לא יצאו:","m":["(כא) משנתנו לו כוס - ועד אחר שתייתו שהוא לאחר גמר בהמ\"ז:","(כב) משהתחיל המברך - אבל מקודם רשאין להשיח אף שכבר נטל המברך הכוס בידו ויש מן הפוסקי' דס\"ל להחמיר בזה ונכון לחוש לדבריהם:","(כג) שצריכין לשמוע וכו' - דהמברך מוציא אותם בבהמ\"ז ואם לא ישמעו לא יצאו:","(כד) אין להם להשיח - דכיון דשומע כעונה הרי הם כמברך עצמו:","(כה) אפי' - דהשיחה שבינתים אינה מפסדת הברכות בדיעבד. ודע דמ\"א מצדד דכ\"ז הוא דוקא בשיחה בשוגג אבל במזיד אפילו בשיחה מועטת ואפילו בין ברכה לברכה חוזר לראש בהמ\"ז וכמו גבי תפלה לעיל בסימן קי\"ד ס\"ז אמנם בא\"ר נשאר בדין זה בצ\"ע וכן הכרענו לעיל בסימן ס\"ה במ\"ב דבדיעבד אין לחזור אפילו כששח במזיד וע\"ש בבה\"ל אך לכתחלה יש ליזהר בזה הרבה. ואם היה בין ברכה לברכה שיהוי מרובה שהיה יכול באותו הזמן לגמור כל בהמ\"ז מראש ועד סוף אפילו אם לא שח כלל בינתים י\"א דצריך לחזור לראש בהמ\"ז ודוקא אם השיהוי היה מחמת אונס שהיה צריך לנקביו או שהיה המקום אינו נקי וכמבואר לעיל בסימן ס\"ה לענין ק\"ש וה\"ה כאן ועיין בבה\"ל שכתבנו דאין דין זה ברור למעשה דיחזור בשביל שהיה בין ברכה לברכה אך אם שיהוי כזה היה באמצע ברכה צריך לחזור ורק לראש הברכה:","(כו) לא יצאו - ותלוי בזה דאם לא גמר המברך עדיין את הברכה חוזרין המסובין ומברכין בעצמן ממקום שפסקו לשמוע לדברי המברך ואם גמר המברך את הברכה וכוונו לשמוע צריכין המסובין לחזור לתחלת הברכה ולברך בעצמן דכיון שדלגו באמצע הוי כלא אמרוה כלל. וכ\"ז דוקא אם ע\"י השיחה שבאמצע לא שמעו ודלגו דברים שהם מעיקר הברכה כמו ברית ותורה וכיו\"ב שהם לעיכובא כמ\"ש בסימן קפ\"ז אבל אם דלגו רק דברים שהם שלא מעיקר הברכה יצאו בדיעבד ואינם צריכים לחזור בשביל זה וכ\"ש אם לא דלגו כלל כגון שהמברך עצמו שח אז באמצע ושחו גם הם אף דבודאי שלא כדין עשו מ\"מ בדיעבד יצאו ואינם צריכים לחזור:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>נכון הדבר שכל אחד מהמסובין <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>יאמר <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>בלחש עם המברך כל ברכה וברכה ואפי' החתימות: <small>הגה ויקדים לסיים קצת קודם המברך כדי שיענה אמן כדלעיל סי' נ\"ט. אין נותנין כוס של ברכה אלא <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>לטוב עין [גמרא פרק אלו נאמרין]:</small>","m":["(כז) נכון הדבר - היינו אף דמדינא היה יותר נכון שישמעו המסובין כל הבהמ\"ז מפי המזמן והוא יוציאם בברכתו ובעצמן לא יברכו כלל מ\"מ בעבור שמצוי בעו\"ה שהמסובין מסיחין דעתם ואינם מכוונין לדברי המברך כלל ונמצא שחסר להם בהמ\"ז לגמרי ומבטלין עשה דאורייתא בידים לכך נכון כהיום יותר שהמסובין יאמרו בעצמן בלחש כל מלה ומלה עם המברך כדי שיברכו יחדו ונקרא עי\"ז ברכת זימון ומתקיים מה שאמר הכתוב גדלו לה' אתי ונרוממה שמו יחדו דמזה ילפינן ברכת זימון וכמ\"ש לקמן [בסימן קצ\"ב במ\"ב]:","(כח) כל ברכה וברכה - ועכ\"פ יזהרו לומר עמו בלחש ברכה ראשונה דאל\"ה להרבה פוסקים לא מקרי זימון כלל וכדלקמן בסימן רי\"ש [אחרונים] ולפ\"ז מה שנוהגין הרבה אנשים שאחר שאמרו ברוך שאכלנו וכו' כל אחד ואחד מברך בקול רם בפ\"ע שלא כדין הם עושין אלא המברך צריך לברך ברכה ראשונה עכ\"פ בקול רם כדי שישמעו המסובין והם יאמרו בלחש עמו מלה במלה ורק בסיום הברכה יקדימו לסיים כדי שיענו אמן כמו שכתב רמ\"א ועיין במ\"א שהוא מצדד להורות כהתשב\"ץ שס\"ל דעד הזן את הכל צריכין לשתוק ולשמוע ולכוין לצאת מן המברך [ומשם ואילך יברכו בעצמן בלחש עם המברך] דעד שם היא ברכת הזימון אבל אין אנו נוהגין כן ומ\"מ הטוב והישר כשיודע במסובין שיכוונו לדבריו לעשות כהתשב\"ץ רק שיודיע להם מתחלה שיכוונו לצאת וגם הוא יכוון להוציאם ודוקא כשהשומעים כלם מבינים לשון הקדש דאל\"ה בודאי טוב יותר שיברכו בעצמן כל הבהמ\"ז ולא לצאת מן המברך [א\"ר]:","(כט) לטוב עין - שהוא שונא בצע וגומל חסד בממונו שנא' טוב עין הוא יבורך אל תקרי יבורך אלא יברך [גמרא]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>לענין לשאול בבהמ\"ז מפני היראה או מפני הכבוד יש מי שאומר שדינה כתפלה:","m":["(ל) שדינה כתפלה - שאין שואלין ומשיבין כלל והטעם מדמצינו שהחמירו חכמים בבהמ\"ז שאין מברכין אלא במקום אחד כתפלה לאפוקי ק\"ש שיכול לאומרה במהלך מן פסוק ראשון ואילך וי\"א מעל לבבך ואילך וכדלעיל סימן ס\"ג ע\"ש במ\"ב:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>צריך לישב בשעה שמברך בין אם היה הולך בביתו כשאכל או עומד או מיסב כשמגיע לברך צריך לישב כדי שיוכל לכוין יותר וגם לא יהא מיסב שהוא דרך גאוה אלא ישב <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i>באימה: <small>הגה נ\"ל דלאו דוקא המברך אלא ה\"ה כל המסובין לא ישבו בקלות ראש אלא באימה מיהו אם לא עשו כן אפי' בירך מהלך בדיעבד יצא [רמב\"ם פרק רביעי]:</small>","m":["(לא) בשעה שמברך - ומסתימת הפוסקים משמע דגם ברכה רביעית אף שהיא מדרבנן צריך לישב כי היכי דלא לזלזולי בה:","(לב) בביתו - דבמהלך בדרך עיין לקמן בסי\"א:","(לג) ה\"ה כל המסובין - דכיון דכולן יוצאין בברכתו צריכין לישב ובאימה כמברך עצמו:","(לד) אפילו בירך מהלך וכו' - היינו כשהוא מהלך בביתו במקום אכילתו אבל כשהלך למקום אחר ובירך יש דעות בזה עיין לקמן בסימן קפ\"ד ס\"א בהג\"ה:","(לה) שגם ברכת מעין שלש - עיין בביאור הגר\"א שתלה דין זה במה שמבואר לקמן בסימן קפ\"ד ס\"ג והרמב\"ם שהוא בעל דעה זו אזיל לשיטתו שם ולפ\"ז בחמשת מיני דגן עכ\"פ לכ\"ע צריך להיות דוקא ברכה אחרונה שלהם בישיבה:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>יש אומרי' שגם ברכ' מעין שלש צריך לאמרה מיושב:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>אם היה מהלך בדרך ואוכל א\"צ לישב ולברך לפי שאין דעתו מיושבת עליו:","m":["(לו) עליו - אם ישב מפני שיקשה בעיניו איחור דרכו ולא יוכל לכוין יפה אלא מהלך ומברך כתב הח\"א דכל זה דוקא כשאכילתו היה דרך הליכה כמו שכתב המחבר שמהלך בדרך ואוכל אבל אם אכילתו היה בישיבה צריך לברך ג\"כ בישיבה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i> אסור לברך והוא עוסק <i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>במלאכתו:","m":["(לז) אסור לברך - היינו כל הברכות ועיין לקמן בסימן קצ\"א במ\"ב ששם מבואר היטב:"]}],"184":[{"s":"<b>לקבוע ברכה במקום סעודה ועד כמה יכול לברך ומי ששכח ולא בירך. ובו ו סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מי שאוכל במקום אחד צריך לברך <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>קודם <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>שיעקר ממקומו <small> (הגה ועיין לעיל סי' קע\"ח) </small> ואם יצא ממקומו ולא בירך אם היה <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>במזיד <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>יחזור למקומו ויברך ואם בירך במקו' שנזכר יצא: <small>הגה ודוקא לדעת הרמב\"ם אבל לדעת הרא\"ש דס\"ל דאף בשוגג יחזור למקומו לכתחלה במזיד אף בדיעבד <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>לא יצא [טור] </small> ואם היה בשוגג להרמב\"ם יברך במקום שנזכר <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>ולהר\"ר יונה והרא\"ש גם הוא יחזור למקומו ויברך:","m":["(א) קודם שיעקור - ומפינה לפינה אפילו הבית גדול מותר ואפילו כשאין רואה מקומו הראשון כגון אחורי הפארא\"וון וכיו\"ב ואם היה לו מניעה שלא יוכל לברך בהחדר שאכל מותר לברך בחדר שסמוך לו אם יכול לראות מקומו שאכל ואם דעתו היה בשעת ברכת המוציא לברך בחדר אחר בבית זה אפשר דיש להקל בשעת הדחק [כגון שמקום שאכל אינו נקי לברך שם] אפילו אינו רואה מקומו הראשון:","(ב) ממקומו - וכל ד' אמות ממקום אכילתו חשיב מקום אחד ויוכל להעתיק ממקומו ע\"י מניעה קטנה:","(ג) יחזור למקומו - אפילו כבר הלך בדרך למרחוק כמה מילין אם לא שהוא רחוק כ\"כ שעד שיחזור למקומו יתעכל המזון ויפסיד ברכתו לגמרי יברך כאן:","(ד) יצא - היינו אפילו היה מזיד בעקירתו וגם הזיד עתה בברכה דהיינו שידע הדין שצריך לחזור למקומו ונתעצל בזה אפ\"ה יצא בדיעבד:","(ה) לדעת הרמב\"ם - ר\"ל דס\"ל בסמוך דבשוגג אף לכתחלה יוכל לברך במקום שנזכר די לנו אם נחמיר במזיד בלכתחלה שצריך לחזור למקומו אבל לדעת הרא\"ש דאף בשוגג צריך לכתחלה לחזור למקומו מסתברא דבמזיד מחמרינן טפי דאף בדיעבד לא יצא. ולענין הלכה הסכימו האחרונים דא\"צ לחזור ולברך אפילו היה מזיד בהליכה ובברכה כנ\"ל בסק\"ד:","(ו) יברך במקום שנזכר - ומ\"מ גם לדעה זו אם חזר הרי זה משובח אלא דאינו מחויב בדבר:","(ז) יחזור למקומו ויברך - וכתבו האחרונים דכן נכון לנהוג למעשה אם לא שהוא שעת הדחק דאז יוכל לסמוך אסברא ראשונה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>במה דברים אמורים כשאין לו פת עוד אבל <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>אם יש לו פת עוד יאכל במקום השני <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>מעט ויברך <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>רק שלא יהא <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>רעב מאכיל' ראשונ':","m":["(ח) יאכל במקום השני - ואפילו במזיד מהני האי תקנה שיאכל כאן פת דבר מועט וא\"צ לברך תחלה ברכת המוציא ולא ברכת המזון על מה שכבר אכל ואחר אכילת פת שבכאן יברך בהמ\"ז ויעלה להאכילה שאכל במקום אחר:","(ט) מעט - היינו אפילו פחות מכזית דמ\"מ מצטרף זה לאכילה שאכל במקום הראשון. ודוקא אם במקום השני אכל ג\"כ פת אבל פרפרת וכיסנין מצדד בפמ\"ג דאפילו כזית לא מהני:","(י) רק שלא יהא רעב - דאם הוא רעב לא מהני מה שיאכל עתה דכבר הפסיד הבהמ\"ז של אכילה ראשונה כמ\"ש בס\"ה ועתה הוא חיוב חדש וצריך לברך גם ברכת המוציא:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>י\"א שכל שבעת המינים טעונים ברכה לאחריהם <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>במקומם <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>וי\"א דחמשת מיני דגן דוקא <small>[ועיין לעיל סי' קע\"ח סעיף ה']:</small>","m":["(יא) במקומם - ואם יצא ממקומו הוי דינו כמ\"ש סעיף א' ב':","(יב) וע\"ל סי' קע\"ח ס\"ה - ששם הביא הרב עוד שיטה ג' דדוקא פת ולענין דינא כתב שם הגר\"א דהעיקר כדעה השניה דה' מיני דגן חשיבי כפת לענין זה ועיין במה שכתבנו שם במ\"ב:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אכל ואינו יודע אם בירך ברכת המזון אם לאו <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"2\"></i>צריך לברך <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"6\"></i>מספק מפני שהיא <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>מן <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"7\"></i>התורה:","m":["(יג) צריך לברך וכו' - היינו כל ברכת המזון אף ברכה רביעית שאינה אלא מדרבנן כי היכי דלא לזלזולי בה [אחרונים]:","(יד) מספק - וגם יכול להוציא לאחר שאכל ולא בירך [רע\"א בהגהותיו וכ\"כ בתשובותיו סי' ו' וכ\"כ כתב סופר סי' למ\"ד]:","(טו) מפני שהיא מן התורה - ודוקא כששבע דאי לא שבע לרוב הפוסקים הוא מדרבנן. ומ\"מ ראוי לירא שמים בנסתפק אם בירך או לא אפילו שלא אכל אלא כזית שיטול ידיו ויברך המוציא ויאכל כזית ויברך בהמ\"ז [ח\"א]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>עד אימתי יכול לברך <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>עד שיתעכל המזון שבמעיו וכמה שיעורו כל זמן שאינו רעב מחמת אותה אכילה <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ומשעה שהתחיל להיות רעב אע\"פ שלא נתעכל עדיין לגמרי כנתעכל לגמרי דיינינן ליה <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>וכן נמי לענין אכילת פירות ושתיית יין אם אינו רעב ולא צמא ותאב <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>לאות' <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>פירות יברך אם אינו יודע לשער אם נתעכלו:","m":["(טז) עד אימת וכו' - אמי ששכח ולא בירך דלעיל קאי:","(יז) כל זמן שאינו רעב - דלאח\"כ כבר בטל אותה האכילה והפסיד בהמ\"ז. ואם רוצה לאכול עתה מחדש דעת המ\"א שיחזור ויברך המוציא אפילו לא הסיח דעתו עדיין דכיון שנתעכל המזון הפסיד גם ברכה הראשונה אבל הרבה אחרונים פליגי עליה וסברי דברכה הראשונה לא הפסיד כל שלא הסיח דעתו בינתים:","(יח) מחמת אותה אכילה - נראה שבא לאפוקי אם הוא משער שבאותה האכילה לבדה היה כבר שיעור להתעכל והיה חוזר להיות רעב ובעוד איזה משך אכל עוד משארי מיני מזונות ומחמת אלו הדברים אינו רעב ואח\"כ נזכר שלא בירך בהמ\"ז אחר אכילה הראשונה לא יכול לברך עוד בהמ\"ז שכבר בטל אותה האכילה. בד\"א שאחר שגמר אכילתו הראשונה הסיח דעתו מלאכול עוד אבל אם היה הכל במשך סעודה אחת כגון מה שרגילין בסעודות גדולות שיושבין כמה וכמה שעות ולפעמים יש שיעור עיכול מאכילת פת שאכלו בתחלה אעפ\"כ יוכלו לברך לבסוף ברכת המזון כיון דבתוך משך הזה אוכלין פרפראות וכיסנין ושותין הכל סעודה אחת היא וכלא נתעכל מזון הראשון דמי:","(יט) לאותם פירות - לאו דוקא אלא שאינו תאב לשום פירות הוא סימן שלא נתעכל עדיין במעיו:","(כ) אם אינו יודע וכו' - וכ\"ז כשאכל כל צרכו מהלחם או מהפירות אבל אם אכל מעט וחפץ לאכול עוד אלא שלא היה לו יותר מזה בזה קשה מאד לשער השיעור דכל זמן שאינו רעב כיון שתיכף היה לו ג\"כ תאוה אלא שלא היה לו כתבו הרבה אחרונים דמשערינן בזה עד כדי הילוך ד' מילין [שהוא ע\"ב מינוט] ועד כדי שיעור זה מחויב לברך שבודאי לא נתעכל אפילו אכילה מועטת בשיעור מועט כזה ויש מן האחרונים שמצדדים דאם אכל אכילה מועטת ושהה קודם שבירך בהמ\"ז ואינו יודע לשער אם נתעכל המזון אף שהוא בתוך שיעור ד' מילין יאכל עכ\"פ עוד כזית פת ואח\"כ יברך בהמ\"ז ועל אותו פת שאוכל א\"צ לברך המוציא מחדש אם לא הסיח דעתו מלאכול עוד. ומ\"מ אם אין לו פת יש לסמוך אסברא ראשונה ולברך בהמ\"ז עד שיעור ד' מילין וכנ\"ל ועיין בביאור הלכה:"]},{"s":" <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>שיעור אכיל' לברך עליה ברכ' המזון <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>בכזית:","m":["(כא) לברך עליה בהמ\"ז וכו' - ואע\"ג דברכה ראשונה צריך לברך אפילו על כל שהוא התם משום דאסור ליהנות מעוה\"ז בלי ברכה:","(כב) בכזית - היינו מדרבנן אבל מדאורייתא אינו חייב לברך בהמ\"ז כ\"א כשאכל דוקא שיעור שביעה שנאמר ואכלת ושבעת וברכת. ושיעור שביעה משמע מספר החינוך [בפרשת עקב] דאינו שוה בכל אדם אלא כ\"א יודע שביעתו ואם דרכו תמיד לאכול כדי מחייתו לבד גם זה נחשב שביעה:"]}],"185":[{"s":"<b>לברך בהמ\"ז בקול רם ויתר פרטים בבהמ\"ז. ובו ה סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>ברכת המזון <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>נאמרה בכל לשון:","m":["(א) בכל לשון - דכתיב וברכת בכל לשון שאתה מברך ודוקא שמבין באותו הלשון [בה\"ל לעיל בסימן ס\"ב ע\"ש] וכתב הב\"ח בסימן קצ\"ג דכ\"ז מצד הדין ולמצוה מן המובחר בעינן דוקא לשה\"ק. כתב בספר החינוך כל הזהיר בבהמ\"ז מזונותיו מצויות לו כל ימיו בכבוד. והמדקדק יזהר לברך לכתחלה תוך הספר ולא בע\"פ. כתב בספר חסידים מעשה באחד שמת ונתגלה בחלום לאחר מקרוביו וא\"ל בכל יום דנין אותי על שלא הייתי מדקדק לברך כל הברכות בכונת הלב וכו' ע\"ש:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>צריך שישמיע לאזניו מה שמוציא <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>בשפתיו ואם לא השמיע לאזניו יצא <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ובלבד שיוציא בשפתיו:","m":["(ב) בשפתיו - אבל אם הרהר בלבו לא יצא. ואם מחמת חולי או אונס אחר בירך בהמ\"ז בלבו יצא [מ\"א] ועיין לעיל בסימן ס\"ב במ\"ב סק\"ז שביררנו דהאי יצא לא לגמרי קאמר דהא קי\"ל הרהור לאו כדיבור דמי אלא ר\"ל דעכ\"פ בשעה שאינו יכול לברך יהרהר בלבו והקב\"ה יקבע לו שכר עבור זה אבל בעצם אינו יוצא וע\"כ כשנסתלק האונס אם עדיין לא נתעכל המזון יברך ברכת המזון ועיין במה שכתבנו שם במ\"ב ובבה\"ל בכל הסעיף כי הכל שייך לכאן:"]},{"s":" <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>יש מי שאומר דבעל הבית עם בניו ואשתו צריך לברך בקול רם כדי שיצאו בברכתו:","m":["(ג) בקול רם - היינו כשאינם בקיאים בעצמם לברך והם יוצאים בשמיעתם ממנו ויש שכתבו דטוב לעולם לברך בקול רם כי הקול מעורר הכונה ובפרט אם הוא שבת או ר\"ח לא ישכח עי\"ז להזכיר מעין המאורע:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אפי' נשתכר כל כך <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>עד <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>שאינו יכול לדבר כראוי יכול לברך <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ברכת המזון:","m":["(ד) יכול לברך בהמ\"ז - דכתיב ואכלת ושבעת וברכת ואפילו מדומדם [ירושלמי] פי' שאינו יכול לדבר כראוי ומושבעת קדייק ליה שמצוי כמה פעמים שאחר שביעה האדם עומד שיכור ואפ\"ה חייבתו התורה לברך ועיין לקמיה מה שנכתוב בזה:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>אם בירך והיתה צואה כנגדו או שהי' <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>שכור <small>[פי' לגמרי] </small> נסתפקו התוספות והרא\"ש אם צריך לחזור ולברך ומשום מי רגלים פשיטא שאינו חוזר לברך:","m":["(ה) אם בירך והיתה וכו' - ר\"ל דבתפלה קי\"ל לעיל בסימן ע\"ו במי שהתפלל ומצא צואה כנגדו או בצדו תוך ד' אמותיו במקום שהיה ראוי להסתפק ופשע ולא בדק שצריך לחזור ולהתפלל משום שנאמר זבח רשעים תועבה וכן ה\"ה לענין ק\"ש ונסתפקו התוספות והרא\"ש אם גם בבהמ\"ז אמרי' הכי או דלמא שאני בהמ\"ז דקילא מהתם דהרי בשתוי אף שיכול לדבר לפני המלך קי\"ל דאל יתפלל ולענין בהמ\"ז ודאי מותר בשתוי:","(ו) פי' לגמרי - היינו שנשתכר כ\"כ עד שאינו יכול לדבר לפני המלך ונסתפקו אם צריך לחזור ולברך כשיפוג יינו ועדיין לא נתעכל המזון [ומ\"מ מיירי שלא הגיע לשכרותו של לוט דאל\"ה כשוטה יחשב ופטור מכל המצות וחייב לכ\"ע לחזור ולברך] ובסעיף הקוד' שמתיר לברך מיירי שיכול לדבר לפני המלך והקשו כמה אחרוני' דכיון שאינו יכול לדבר כראוי מסתמא אינו יכול לדבר לפני המלך ואפ\"ה מתיר הירושלמי. ולדינא מסקי האחרונים דאם אירע שנשתכר כ\"כ אעפ\"כ יברך ולכתחלה יזהר לברך קודם שיבוא לידי כך ועיין לעיל בסימן צ\"ט סקי\"א במ\"ב:","(ז) אם צריך לחזור ולברך - אבל לכתחלה גם הם מודים דאסור לברך שום ברכה וכן ד\"ת נגד צואה ומן התורה דהא כתיב והיה מחניך קדוש ואטו תפלה כתיב בקרא אלא כל דבר קדושה אסור לקרות במקום שאינו נקי [רמב\"ן בליקוטיו ע\"ש] ולא מסתפקי אלא כשכבר בירך ומצא אח\"כ ולדינא דעת הע\"ת והא\"ר בשם הב\"ח כשמצא צואה כנגדו בתוך ד' אמותיו דצריך לחזור ולברך בהמ\"ז אם עדיין לא נתעכל המזון וכן מצאתי בלקוטי הרמב\"ן על ברכות שהביא מתחלה ספיקא שנסתפקו בעלי התוספות בזה ואח\"כ מסיק דאין חילוק בזה בין תפלה ובין שארי דברי קדושה עי\"ש ועיין בבה\"ל:","(ח) ומשום מי רגלים וכו' - היינו ג\"כ באופן זה דבירך בהמ\"ז ואח\"כ מצא מי רגלים בתוך ד' אמות ולהכי קאמר פשיטא וכו' דאפילו לכתחלה היה מותר לו לברך כ\"ז שלא נודע לו שיש כאן מי רגלים דנגד מי רגלים הוא רק איסורא דרבנן ועל ספיקן לא גזרו וכדלעיל בסימן ע\"ו ס\"ז דאי היה נודע לו מתחלה שיש כאן מי רגלים ועבר ע\"ז ובירך נגדם לא הוה אמר המחבר פשיטא דדין אחד הוא עם מצא צואה כנגדו [פמ\"ג בשם לחם יהודה ע\"ש]:"]}],"186":[{"s":"<b>אם נשים וקטנים חייבים בבהמ\"ז. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>נשים חייבות בברכת המזון <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>וספק הוא אם הן חייבים מדאורייתא ומוציאות את האנשים או אם אינן חייבות אלא מדרבנן ואינן מוציאות <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>אלא למי שאין חיובו <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אלא מדרבנן <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><small>[ועיין לקמן סי' קצ\"ט בענין זימון שלהם]:</small>","m":["(א) אם הן חייבות מדאורייתא - לפי שהיא מ\"ע שלא הזמן גרמא:","(ב) אלא מדרבנן - מדכתיב על הארץ הטובה ונשים אין להם חלק בארץ מצד עצמן (א\"ל בבת יורשת) משא\"כ כהנים ולוים אע\"פ שאין להם חלק מ\"מ יש להם ערי מגרש וי\"א משום שלא ניתן להם ברית ותורה:","(ג) אלא למי שאין וכו' - כגון שלא אכל כדי שביעה שאין חיובו אלא מדרבנן ומסיים הטור דמפני שהוא ספק נקטינן דאין מוציאות את האחרים שאכלו כדי שביעה [מ\"א] וכ\"כ הרמב\"ם פ\"ה מהלכות ברכות. כתב בש\"א אשה שאכלה כדי שביעה ונסתפקה אם בירכה חייבת לברך עי\"ש טעמו וכן הסכים בח\"א ובמגן גבורים אכן בחידושי רע\"א וכן בברכי יוסף פסקו שאינה צריכה לחזור ולברך וכן מצדד בפמ\"ג ומ\"מ נראה דהרוצה לסמוך על דעת ש\"א וסייעתו אין למחות בידו ועיין בבה\"ל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>קטן חייב מדרבנן כדי לחנכו וההיא דבן מברך לאביו כשלא אכל האב <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>כדי <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>שביעה שאינו חייב אלא מדרבנן:","m":["(ד) קטן חייב מדרבנן - היינו אפי' לא אכל רק כזית ג\"כ חייב מדרבנן לחנכו:","(ה) וההיא דבן וכו' - ר\"ל ההיא דאיתא בגמרא דבן קטן מברך ומוציא את אביו בבהמ\"ז כשאין יודע לברך:","(ו) כשלא אכל האב כדי שביעה - אבל אם אכל האב כדי שביעה שחייב לברך מן התורה אין בנו קטן שמחויב רק מדרבנן יכול להוציאו. וכתבו האחרונים דקטן אינו מוציא את האשה דשמא מדאורייתא חייבת:","(ז) שאינו חייב וכו' - ואם גם הבן לא אכל כדי שביעה דהוי אצלו תרי דרבנן אם מוציא לאביו יש דעות בין הפוסקים ויש להחמיר:"]}],"187":[{"s":"<b>דיוקים בנוסח בהמ\"ז. ובו ד סעיפים:</b><br>יש אומרים ברוך משביע לרעבים <i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>ואין לאומרו והמוסיף גורע אם <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אמר במקום ברכת הזן בריך רחמנא מלכא מארי דהאי פיתא <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>יצא <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ויש אומרים שצריך <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>שיחתום בריך רחמנא דזן כולה:","m":[]},{"s":"בברכת הארץ להרא\"ש לא יאמר שהנחלת לאבותינו ארץ חמדה טובה וכו' ברית ותורה שהרי אומר על בריתך שחתמת בבשרינו ועל תורתך שלמדתנו ודי בפעם אחד; והרמב\"ם חולק. <small>[הגה ודברי הרא\"ש הם עיקר]:</small>","m":["(א) י\"א ברוך וכו' - היינו שהיו נוהגין לומר קודם התחלת בהמ\"ז:","(ב) והמוסיף גורע - דאין להוסיף על מטבע שטבעו חכמים לא יאמר כי לעולם חסדו עמנו כי חסדיו הם עם כל חי. שאתה זן קמ\"ץ תחת השי\"ן. אנחנו מודים ולא אנו דאנו הוא לשון אנינות. בפי כל חי ולא בפה. רענו בשו\"א תחת הרי\"ש ולא בחול\"ם כי הוא לשון בקשה. ומטעם זה צ\"ל זוננו במלאפו\"ם. לא חסר לנו ואל יחסר לנו [א\"ר בשם של\"ה]:","(ג) מלכא מאריה וכו' - ולפי מה שכתב המחבר לקמן בסי' רי\"ד מיירי דאמר מלכא דעלמא ועיין במש\"כ שם:","(ד) יצא - ידי ברכה ראשונה שהיא ברכת הזן ואף שקיצר מאד הברכה ולא אמרה כנוסח שתיקנו חכמים בלה\"ק אפ\"ה יצא בדיעבד הואיל והזכיר שם [דהש\"י היו קורין אותו בלשון רחמנא] ומלכות וענין הברכה ומשמע עוד דלדעה ראשונה אף שלא חיתם ג\"כ מהני דאף דקי\"ל דמקום שאמרו לחתום אינו רשאי שלא לחתום מ\"מ בדיעבד יצא והדעה השניה ס\"ל דהוא לעיכובא אף בדיעבד ועיין בב\"ח שכתב דנ\"ל לעיקר הדעה הזו והביאו בא\"ר. והנה כ\"ז הוא דוקא בדיעבד אבל לכתחלה לכו\"ע אין לשנות כלל מנוסח הברכה שתקנו לנו חכמים ז\"ל וכמו שמבואר ברמב\"ם פ\"א מק\"ש ופ\"א מהלכות ברכות ומשמע באחרונים דילדים קטנים נוכל לחנכם לכתחלה בנוסח זה מברכת הזן וכן מעט מכל ברכה עד שידעו לברך כל ברכה כתיקונה:","(ה) ברית ותורה - כי בנוסחתם הי' כתוב שהנחלת לאבותינו ארץ חמדה טובה ורחבה ברית ותורה וע\"ז כ' הרא\"ש דלא יאמר שהרי יאמר אח\"כ על בריתך וכו' ומה דאמר בגמ' צריך שיזכיר בה ברית ותורה היינו הענין של ברית ותורה כמו שאנו אומרים על בריתך וכו' לא תיבות ממש:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אם לא הזכיר בברכת הארץ ברית <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ותורה אפי' אם לא חיסר אלא אחד מהם מחזירין אותו: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i>ונשים ועבדים לא יאמרו ברית ותורה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>דנשים לאו בני ברית נינהו ועבדים לאו בני תורה נינהו [כל בו]:</small>","m":["(ו) אם לא הזכיר וכו' - והא דלא הזכיר המחבר אם לא אמר ארץ חמדה טובה ורחבה דמחזירין אותו כדאיתא בש\"ס דהא מלתא דפשיטא היא דהיא עיקר ברכת הארץ אלא אפילו לענין ברית ותורה נמי מחזירין אותו [א\"ר]:","(ז) בברכת הארץ וכו' - שע\"י ברית נתנה הארץ לאברהם בפרשת מילה שנאמר ונתתי לך לזרעך אחריך את ארץ מגוריך וגו' ובזכות התורה והמצות ירשו את הארץ שנאמר למען תחיון ורביתם ובאתם וירשתם את הארץ וגו' ואומר ויתן להם ארצות גוים וגו' בעבור ישמרו חקיו ותורותיו וגו':","(ח) מחזירין אותו - היינו לראש בהמ\"ז דכולהו ג' ברכות ראשונות חשובות כאחת כ\"כ מ\"א לקמן בסימן קפ\"ח סק\"ח ועיין במה שכתבנו שם בזה בשם שאר אחרונים:","(ט) דנשים לאו וכו' - באמת לאו בני תורה נינהו ג\"כ והא דחלקינהו לשתים משום דעבדים איתנהו בברית. ומ\"מ בימינו נהגו הנשים לומר ג\"כ על בריתך שחתמת בבשרנו ועל תורתך שלמדתנו וכו' והכוונה על ברית הזכרים שחתמת בבשרנו וכן תורתך שלמדתנו על למוד הזכרים שבזכות התורה והברית נחלו ישראל את הארץ ועוד שגם הנשים צריכות ללמוד מצות שלהן לידע היאך לעשותן כמ\"ש בסי' מ\"ז:","(י) בבונה וכו' - מפני שע\"י דוד נתקדשה ירושלים וגם שאין נחמה גמורה אלא בחזרת מלכות ב\"ד למקומה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אם לא הזכיר בבונה ירושלים מלכות בית דוד מחזירין אותו: <small>הגה ואומרים על הנסים בחנוכה ובפורים קודם על הכל וכו' ואם לא אמרו אין מחזירין אותו [טור] וע\"ל סי' תרפ\"ב ומ\"מ יוכל לאמרו בתוך שאר הרחמן ויאמר הרחמן הוא יעשה לנו נסים כמו שעשה בימים ההם וכו' והכי נהוג [כל בו]:</small>","m":[]}],"188":[{"s":"<b>נוסח ברכה ג' ודיני ברכת המזון בשבת והטועה בברכת המזון. ובו י סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אחר שחתם בונה ירושלים יענה אמן אחר ברכת עצמו מפני שהיא סיום הברכות דאורייתא דהטוב והמטיב אינה דאורייתא:","m":["(א) מפני שהיא סיום וכו' - עיין לקמן בסימן רט\"ו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אמן זה יאמרנו בלחש כדי שלא ירגישו שברכת הטוב והמטיב אינה דאורייתא <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>ויזלזלו בה: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>ונראה דדוקא כשמברך לבד ואין עונים אמן אחר שאר ברכות אבל כשמזמנין עונין עליו כשאר אמן שעונין על ברכות הראשונות אע\"ג דהמברך עונה ג\"כ מ\"מ אינו ניכר כ\"כ הואיל ואחרים עונין ג\"כ עמו וכן המנהג במדינות אלו לאומרם בקול רם אפי' המברך עצמו כשמזמנין ואולי מהאי טעמא:</small>","m":["(ב) ונראה דדוקא וכו' - ויש מיישבין המנהג מטעם אחר שלא חששו לזלזול ברכה רביעית אלא בימיהם שהיו הפועלים הולכים למלאכתם כששומעים אמן שאחר בונה ירושלים (שלא חייבום חכמים בברכה רביעית מפני בטול מלאכתו של בעה\"ב) לכך היה צריך לענות אמן בלחש כדי שלא ישמעו הפועלים ויכירו שברכה רביעית אינה מן התורה ויבואו לזלזל בה אף שלא במקום בטול מלאכת בעה\"ב אבל עכשיו שגם הפועלים מברכים ד' ברכות כמ\"ש בסימן קצ\"א אין לחוש לזה ולפי טעם זה בין כשמברך בזימון ובין כשמברך ביחידי יכול לענות אמן בקול רם וכמדומה שכן המנהג. לא יאמר בונה ירושלים אמן בנשימה אחת רק ימתין קצת אחר תיבת ירושלים ואח\"כ יאמר אמן כדי שלא יהא משמע שגם האמן מסיום הברכה הוא:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>צריך להזכיר בברכה שלישית מלכות בית דוד ואין להזכיר בה שום מלכות אחר <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>והאומר ומלכותך ומלכו' בית דוד משיחך טועה שאין להשוות מלכותא דארעא עם מלכותא דשמיא וכן אין לומר בה אבינו מלכנו: <small>הגה וי\"א דאף כשאומר יעלה ויבא לא יסיים מלך חנון ורחום אלא ידלג מלת מלך [אבודרהם] וסברא נכונה היא <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אבל לא ראיתי <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>נוהגים כן:</small>","m":["(ג) שום מלכות אחר - היינו כגון הא דמסיים המחבר לקמיה:","(ד) והאומר וכו' - צ\"ל לכן האומר וכן הוא בטור:","(ה) אבינו מלכנו - אלא יאמר אבינו רוענו ואע\"ג דאינו אומר ביחד ממש עם מלכות בית דוד מ\"מ כיון דבחד ברכה הוא לאו אורח ארעא לאדכורי מלכותא דשמיא אצל מלכותא דבשר ודם:","(ו) אבל לא ראיתי וכו' - והאחרונים כתבו טעם לזה כיון דענין בפ\"ע לגמרי הוא לא קפדינן בזה ואומרים אותה כמו שהיא מסודרת בתפלת י\"ח לכן אין למחות ביד הנוהגין כן:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>נוסח ברכה זו <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>פותח בה רחם ה' אלהינו או נחמנו ה' אלהינו וחותם בה בונה ירושלים או מנחם ציון בבנין ירושלים ואין לשנות <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>הנוסחא משבת לחול דבין בשבת בין בחול אומר נוסחא אחת: <small>[הגה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"4\"></i>וי\"א דאמרי' בונה ברחמיו ירושלים וכן נוהגין]. מרדכי סוף ברכות:</small>","m":["(ז) או נחמנו - היינו נחמנו ה' אלהינו בירושלים עירך ובציון משכן כבודך ובמלכות בית דוד משיחך ובבית הגדול והקדוש וכו':","(ח) וחותם בה וכו' או מנחם - מלשון זה משמע שאף אם פתח ברחם מותר לחתום במנחם ואף שאין החתימה מעין הפתיחה ממש לית לן בה דעכ\"פ הענין אחד אבל יש מאחרונים שמחמירין בזה וסוברין דצריך להיות מעין הפתיחה ממש:","(ט) ואין לשנות וכו' - ר\"ל דאם אומר בחול רחם יאמר בשבת ג\"כ רחם ואע\"ג דאסור לתבוע צרכיו בשבת הכא שאני דתופס ברכה כך היא תמיד וגם כל הרחמן יכול לומר בשבת אע\"פ שאינן מתופס הברכה שתקנו חכמים שכיון שנהגו הכל לאומרם בכל פעם שמברכין בהמ\"ז נעשה להם כטופס ברכה ואין בזה משום שאלת צרכיו בשבת:","(י) נוסחא אחת - והגר\"א כתב שעיקר כהרי\"ף שבחול יאמר רחם נא כמנהגנו ובשבת יאמר נחמנו וכו' ומסיים מנחם וכו' וכי יש עוד כמה ראשונים שסוברים כן:","(יא) דאומרים בונה ברחמיו וכו' - משום דכתיב שבתי לירושלים ברחמים וגו' וגם מאחר שהתחיל בתחלת הברכה ברחם מסיים נמי ברחמים כדי שיהיה החתימה מעין הפתיחה ממש ומ\"מ לכ\"ע אין מעכב כלל ועיין במעשה רב:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>בשבת <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>אומר בה רצה והחליצנו ובראש חדש וי\"ט וחולו של מועד אומר יעלה ויבא ואם חל אחד מהם בשבת אומר רצה והחליצנו ואח\"כ יעלה ויבא <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>ואינו מזכיר של שבת ביעלה ויבא ולא של יו\"ט וחולו של מועד ור\"ח ברצה והחליצנו:","m":["(יב) אומר בה - לפי שהזכרה זו וכן ביעלה ויבוא הם בקשת רחמים קבעום בברכת בונה ירושלים שהיא ג\"כ בקשת רחמים ולא בברכת הארץ שהיא הודאה ואם הזכירם בברכת הארץ לא יצא וצריך לחזור ולהזכיר בבונה ירושלים:","(יג) ואח\"כ יעלה ויבוא - מפני ששבת הוא תדיר וקי\"ל בכל מקום תדיר קודם ובדיעבד אם החליף בודאי יצא:","(יד) ביעלה ויבוא - דהא כבר הזכיר שבת ברצה ולמה יחזור ויזכירנו:","(טו) ברצה והחליצנו - דהא תקנו ע\"ז נוסח בפ\"ע יעלה ויבוא ולמה יכפילנה פעמים:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"4\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>טעה ולא הזכיר של שבת אומר ברוך אתה ה' אלהינו מלך העולם שנתן שבתות <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>למנוחה לעמו ישראל באהבה לאות ולברית ברוך אתה ה' מקדש השבת ואם טעה ולא הזכיר של יו\"ט אומר ברוך אתה ה' אלהינו מלך העולם <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>אשר <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>נתן ימים טובים <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>לישראל לששון ולשמחה את יום חג פלוני הזה ברוך אתה ה' מקדש ישראל והזמנים. ואם חל יום טוב בשבת אומר שנתן שבתות למנוחה לעמו ישראל באהבה לאות ולברית וימים טובים לששון ולשמחה את יום חג פלוני הזה ברוך אתה ה' מקדש השבת וישראל והזמנים. וכל ברכות הללו בשם ומלכות והא דסגי בהך ברכה דוקא כשנזכר קודם שהתחיל הטוב והמטיב אבל אם לא נזכר עד שהתחיל הטוב והמטיב צריך לחזור <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>לראש ברכת המזון:","m":["(טז) ולא הזכיר של שבת - ואפילו אם ספק לו אם הזכיר או לא תלינן דמסתמא בודאי לא הזכיר:","(יז) אומר ברוך אתה וכו' - ואם אינו יודע נוסח ברכה זו חוזר לראש ואם יודע ההתחלה והסיום אף שאינו יודע שאר הנוסח שבאמצע כראוי אומרה וא\"צ לחזור לראש [ט\"ז וש\"א] ועיין מה שכתבנו בבה\"ל:","(יח) ימים טובים לישראל - צ\"ל לעמו ישראל:","(יט) לששון ולשמחה - ובר\"ה אין אומרים לששון ולשמחה גם אין אומרים ודברך מלכנו וכו' וזה נוסחו בא\"י אמ\"ה שנתן ימים טובים לעמו ישראל את יום הזכרון הזה ואינו חותם בה כמו בר\"ח וזהו דעת המ\"א שחולק על כנה\"ג שמשוה ר\"ה לשאר י\"ט אבל הרבה אחרונים הסכימו לדעת כנה\"ג וע\"כ צריך לחתום בא\"י מקדש ישראל ויום הזכרון ואם שכח והתחיל הטוב והמטיב ג\"כ דעת המ\"א דשוב אינו חוזר כמו בר\"ח וא\"ר חולק עליו וס\"ל דחוזר. וביוה\"כ לענין חולה שצריך לאכול בו וצריך לומר בו יעלה ויבוא כדלקמן בסימן תרי\"ח ס\"י אם פתח בהטוב והמטיב ונזכר שלא אמר יעלה ויבוא אינו צריך לחזור וכמו בר\"ח ואם נזכר קודם שהתחיל ברכת הטוב והמטיב י\"א דצריך לומר ברוך שנתן ימים קדושים לישראל את יוהכ\"פ הזה בלי חתימה וי\"א דבזה לא תקנו חכמים כלל נוסח ברכה להשלים הזכרת יעלה ויבוא וכל שלא אמר במקומו שוב אינו חוזר וכן מסתברא:","(כ) יו\"ט בשבת אומר וכו' - ומיירי ששכח ולא אמר שניהם לא רצה ולא יעלה ויבוא ולהכי צריך לכלול שניהם אבל אם שכח של שבת לבד אומר רק אשר נתן שבתות למנוחה וכן בשכח של יו\"ט לבד אומר אשר נתן ימים טובים לעמו ישראל וכו' [אחרונים]:","(כא) וכל ברכות הללו וכו' - פי' פתיחת הברכות:","(כב) קודם שהתחיל הטוב וכו' - היינו שעומד אחר ברכת בונה ירושלים. ואם נזכר אחר שאמר תיבת ברוך אתה פשוט דחוזר לומר רצה והחליצנו או יעלה ויבוא ואומר אח\"כ ובנה ירושלים וכו' ואם נזכר אחר שאמר כבר ברוך אתה ה' מהנכון שיסיים תיכף למדני חקיך כדי שלא יהיה השם לבטלה והוי עדיין כלא סיים הברכה וחוזר לרצה:","(כג) עד שהתחיל הטוב וכו' - כתב הח\"א ר\"ל שאמר ברוך אתה ה' אמ\"ה האל זה מקרי התחלה לברכה זו אבל אם אמר רק בא\"י אמ\"ה יסיים אשר נתן שבתות למנוחה וכו' ואח\"כ יחזור ויאמר ברכת הטוב והמטיב ועיין בבה\"ל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>אם טעה ולא הזכיר בה של ר\"ח בין ביום בין בלילה אומר ברוך שנתן ראשי חדשים לעמו ישראל לזכרון <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>ואינו חותם בה והוא שנזכר קודם שהתחיל הטוב והמטיב. <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>אבל אם לא נזכר עד שהתחיל הטוב והמטיב אינו חוזר מפני <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>שאינו חייב לאכול פת כדי שיתחייב לברך ברכת המזון <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>וחול המועד דינו כר\"ח: <small>הגה ואפשר דמ\"מ יש לאמרו בתוך שאר הרחמן כמו שנתבאר לעיל ססי' קפ\"ז גבי על הנסי' ואולי יש לחלק כי ביעלה ויבא יש בו הזכרת שמות <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>ואין לאמרו לבטל' כן נ\"ל וכן נוהגין. </small> <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>אם חל ראש חדש בשבת והזכיר של שבת ולא הזכיר של ראש חדש ולא נזכר עד שהתחיל הטוב והמטיב <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>אינו חוזר ואם <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>שכח (גם) של <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>שבת ונזכר קודם שהתחיל הטוב והמטיב כולל ראש חודש עם שבת ואומר שנתן שבתות למנוחה וראשי חדשים לזכרון ואם פתח בהטוב והמטיב חוזר לראש ברכת המזון ומזכיר של שבת ושל ראש חודש ויש מי שאומר שאם שכח של שבת וראש חדש ונזכר קודם שהתחיל הטוב והמטיב אומר שנתן שבתות למנוחה וראשי חדשים לזכרון וחותם בשל שבת <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>ואינו חותם בשל ראש חדש:","m":[]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"6\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>סעודה שלישית <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>בשבת <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>דינה <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>כראש חודש:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>ג' שאכלו בשבתות וי\"ט ושכחו להזכיר מעין המאורע והם צריכין לחזור לראש בהמ\"ז יברך כל אחד בפני עצמו כי מידי זימון כבר יצאו:","m":["(כד) לראש בהמ\"ז - דכיון דכבר סיים סדר ברכות דאורייתא והסיח דעתו מהם ופתח בהטוב והמטיב דמי לעקירת רגלים בתפלת י\"ח דחוזר לראש אם טעה באיזה דבר. ואם טעה בברכה רביעית כגון שלא אמר בה שם ומלכות אע\"פ שכבר גמר אותה אינו חוזר אלא להטוב והמטיב שהיא ברכה בפני עצמה [מ\"א וש\"א]:","(כה) אומר ברוך שנתן - עיין בבה\"ל שביררנו בשם רוב הפוסקים דגם אותה צ\"ל בשם ומלכות:","(כו) מפני שאינו חייב וכו' - דדוקא בשבת וביו\"ט שמחויב לאכול דוקא פת וא\"כ חיוב ברהמ\"ז קבוע הוא בימים האלה לכן תקינו רבנן לעיכובא ג\"כ להזכיר שם מעין המאורע וכמו בתפלה אבל בר\"ח אע\"ג שאסור להתענות בו מ\"מ אינו מחויב לאכול דוקא פת וא\"כ אין חיוב ברהמ\"ז קבוע בו ולהכי לא תקנו חכמים הזכרת מעין המאורע שלו לעיכובא בבהמ\"ז וע\"כ אם שכח אין צריך לחזור וכתב המ\"א דה\"ה ביו\"ט יותר מסעודה אחת ביום וסעודה אחת בלילה שמחויב לאכול אם אכל ושכח להזכיר מעין המאורע בבהמ\"ז אינו צריך לחזור כמו בר\"ח אם לא כשלא אכל הסעודה בלילה שמחויב לאכול ביום שתים כדלקמן בסימן תקצ\"ט דאז אפילו בסעודה שניה חוזר [פמ\"ג]:","(כז) וחוה\"מ דינו כר\"ח - לענין שאין צריך לחזור וה\"ה לענין שאם נזכר קודם שהתחיל הטוב והמטיב אומר בא\"י אמ\"ה שנתן מועדים לעמו ישראל לששון ולשמחה ואינו חותם כמו בר\"ח:","(כח) אינו חוזר - כמו בכל ר\"ח כששכח ואע\"ג דבההוא יומא לא סגי דלא אכיל פת ההיא משום שבת היא ולאו משום ר\"ח דאכילת פת בר\"ח ליכא חיובא ושל שבת הרי הזכיר:","(כט) ואם שכח של שבת - כצ\"ל. וכן הגירסא בש\"ע של עולת תמיד ובשכח של שבת לבד בודאי אין צריך לכלול גם של ר\"ח בברכה זו כיון שכבר הזכיר ר\"ח ביעלה ויבוא. ומ\"מ אם לא נזכר עד לאחר שפתח בהטוב והמטיב וחוזר לראש בהמ\"ז בשביל הזכרה של שבת אז צריך לומר עוד הפעם גם יעלה ויבוא דבהמ\"ז הראשון נתבטל לגמרי:","(ל) ואינו חותם בשל ר\"ח - כדלעיל דליכא חתימה בר\"ח ואע\"ג דהכא מזכיר השם בחתימה בלא\"ה משום שבת מ\"מ אינו כדאי להזכיר דהזכרת השם הוא על שניהם ומ\"מ לדינא מסקי האחרונים דיזכיר בחתימה גם ר\"ח מטעם דבלא\"ה הרבה פוסקים ס\"ל דגם בכל ר\"ח צריך לחתום בברכה כמו ביו\"ט ואע\"פ שאין אנו נוהגין כוותייהו משום חשש ברכה שא\"צ הכא דבלא\"ה חותם בברכה בשביל שבת שפיר דמי לומר מקדש השבת וישראל וראשי חדשים:","(לא) דינה כר\"ח - שאינו חוזר אם התחיל ברכת הטוב והמטיב לפי שי\"א שסעודה שלישית אין צריך פת ואף שאין דבריהם עיקר כמש\"כ המחבר בסימן רצ\"א ס\"ה מ\"מ יש לחוש לדבריהם שלא לכנוס לספק ברכה לבטלה. ובסעודה ג' ביו\"ט לד\"ה אינו חוזר שהרי לד\"ה אינו אלא רשות וכמש\"ל בס\"ק כ\"ו ומ\"מ אם נזכר קודם שהתחיל ברכת הטוב והמטיב אפילו בסעודה רביעית או חמישית בשבת ויו\"ט אומר בא\"י אמ\"ה שנתן שבתות למנוחה וכו' או שנתן ימים טובים וכו' כמו שאומר בר\"ח אע\"פ שא\"צ אז פת כלל באותו יום:","(לב) דאזלינן וכו' - וכיון שהתחלת הסעודה היה מבעוד יום כבר נתחייב להזכיר מעין המאורע וע\"כ אפילו נמשך זמן רב בלילה לא נפקע חיובו וכתבו האחרונים דאם התפלל מעריב קודם בהמ\"ז שוב אינו מזכיר של שבת בבהמ\"ז דמחזי כסתרי אהדדי:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>היה אוכל ויצא שבת <i data-commentator=\"Magen Avraham\" data-order=\"17\"></i><i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>מזכיר של שבת בברכת המזון דאזלינן בתר התחלת <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"7\"></i>הסעודה <i data-commentator=\"Magen Avraham\" data-order=\"18\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"8\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i>וה\"ה לר\"ח ופורים וחנוכה:","m":["(לג) בתר התחלת הסעודה - ולפיכך אף אם חל ר\"ח במו\"ש יזכיר בבהמ\"ז של שבת לבד ולא של ר\"ח ודוקא כשגמר סעודתו מבעוד יום אבל אם אכל פת גם בלילה ויש עליו חיוב להזכיר גם של ר\"ח ושניהן אי אפשר להזכיר דהוי תרתי דסתרי דהיאך יאמר ביום השבת הזה ואח\"כ יאמר ביום ר\"ח הזה דהא ר\"ח הוא ביום א' א\"כ מוטב להזכיר של ר\"ח דזה יש חיוב לכ\"ע משא\"כ בהזכרת שבת דיש פלוגתא בין הראשונים אם חייב להזכיר כלל כשמברך במו\"ש (ואף דאנן פסקינן כאן בש\"ע דאזלינן בתר מעיקרא וחייב להזכיר של שבת במו\"ש מ\"מ כאן שהוא מקום הדחק מוטב שידחה הזכרת שבת מפני הזכרת ר\"ח דהוא חיוב לכ\"ע) אכן במו\"ש לחנוכה ופורים אפילו אם גמר סעודתו בלילה אינו מזכיר של חנוכה ופורים רק של שבת לבד כיון דבלא\"ה הזכרה מעין המאורע דחנוכה ופורים אינו אלא רשות כנ\"ל בסימן קפ\"ז ס\"ד כ\"כ המ\"א ועוד הרבה אחרונים וי\"א דאם חל יו\"ט או ר\"ח במו\"ש יזכיר רצה וגם יעלה ויבוא דאזלינן בתר התחלת הסעודה וגם בתר שעה שהוא מברך בו ולא קפדינן במה דנראה כסותרים אהדדי דברצה נתחייב משעה שהתחיל הסעודה ביום ואח\"כ כשנמשך הזמן ולא בירך והגיע לילה של יו\"ט או של ר\"ח ניתוסף עליו חיוב לזכור מעין המאורע של שעה שהוא מברך בו:","(לד) וה\"ה לר\"ח וכו' - ר\"ל דאם אכל בהם ונתאחר הבהמ\"ז עד הערב צריך להזכיר דאזלינן בתר זמן התחלת הסעודה והוא שלא התפלל ערבית וכנ\"ל ועיין לקמן בסימן תי\"ט:"]}],"189":[{"s":"<b>נוסח ברכה רביעית ודינה. ובו ב סעיפים:</b><br><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>ברכה רביעית <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>לא יאמר תתברך ולא יאמר בה החי כי אם בבית <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>האבל <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ואומר בה ג' מלכיות בא\"י אלהינו מלך העולם האל אבינו מלכנו כו' המלך הטוב <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>וג' הטבות <i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>הוא <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>הטיב לנו הוא מטיב לנו והוא ייטיב לנו. ושלשה גמולות הוא גמלנו הוא גומלנו הוא יגמלנו:","m":["(א) לא יאמר תתברך - שכבר אמר ברוך אתה ה':","(ב) החי - כי בקצת סדורים היה כתוב המלך החי הטוב וכו':","(ג) כ\"א בבית האבל - וכדלקמיה בס\"ב:","(ד) שלשה מלכיות וכו' - וטעם כל זה הוא דברכת הטוב והמטיב אינו מן התורה אלא שחכמים תקנוה על הרוגי ביתר שניתנו לקבורה ואמרו הטוב שלא הסריחו והמטיב שנתנו לקבורה וקבעוה לברכת המזון מפני שכולה הודאה ושבח על הטובה שהטיב עמנו וגם זו מן הטובות וסמכוה לברכת בונה ירושלים מפני שכשנחרבה ביתר נגדעה קרן ישראל ואינה עתידה לחזור עד שיבוא בן דוד ומפני שכבר סיימו ברכות שהם מן התורה וזו היא מדרבנן לא מקרי זו ברכה שהיא סמוכה לחברתה ולהכי פותחת בברוך [ומה שאין אנו חותמים בה בברוך אע\"פ שהיא ברכה ארוכה מפני שמתחלה תקנוה במטבע קצר שלא הוזכר בה אלא הטוב והמטיב לכל ואח\"כ הוסיפו בה יתר הדברים] ותקנו בה ג' מלכיות מפני שכבר תקנו להזכיר מלכות בית דוד בבונה ירושלים וכיון שמזכירין מלכות בית דוד היה ראוי להזכיר גם מלכות שמים אלא מפני שאין זה דרך כבוד להזכיר בסמוך ממש מלכותא דשמיא למלכות בו\"ד רצו להשלימה ולהזכיר בברכת הטוב והמטיב מלכות כנגדה ואגב שתקנו להזכיר מלכות כנגד ברכת רחם תקנו להזכיר עוד פעם מלכות כנגד ברכת הארץ שלא הוזכר גם בה מלכות (ואע\"פ שמעיקר הדין אין צריך בה מלכות שהיא סמוכה לברכת הזן ובה נזכר מלכות) וכיון שאומרים בה ג' מלכיות אומרים בה ג\"כ ג' הטבות מפני שעיקר הברכה היא על שם ההטבה דהיינו הטוב והמטיב וכיון שאומרים בה ג' הטבות והיא ברכת הודאה כמו שכתבנו אומרים ג\"כ ג' תגמולות עכ\"ל הלבוש:","(ה) המלך הטוב - אין לומר אל שבכל יום וכו' דמשמע ח\"ו שיש שתי רשויות ואותו אל שבכל יום אנו מברכין אלא יאמר אל בכל יום וכו' ויותר נכון שלא לומר כלל מלת אל שהרי כבר אמר האל אבינו. בבהמ\"ז בעה\"ב מסיים ונאמר אמן שאין יכול לגזור אומר ואמרו אמן משא\"כ בברכת עושה שלום במרומיו שהוא שבח של הקב\"ה וכל ישראל מצווין אומר ואמרו אמן. אחר הרחמן יש לענות אמן וכן אחר כל תחנה ובקשה אע\"פ שאין בה שם [כל בו ושל\"ה]. יאמר ונשא ברכה מאת ה' כלשון הפסוק ישא ברכה מאת ה'. נוהגים לומר בשבת ויו\"ט ור\"ח מגדול ובחול מגדיל ויתר דקדוקים שבנוסח בהמ\"ז עיין בא\"ר סימן קפ\"ז שהאריך בזה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>בבית האבל אומר ברוך אתה ה' אלהינו מלך העולם האל אבינו מלכנו בוראנו גואלנו קדושנו קדוש יעקב המלך החי הטוב והמטיב אל אמת דיין אמת וכו' <small> (ועיין בי\"ד סי' שע\"ט):</small>","m":["(ו) בבית האבל אומר - בין כשהאחרים האוכלין עמו מברכין ובין כשהוא עצמו מברך ואם בעינן לזה עשרה או לא עיין ביו\"ד סימן שע\"ט ובאחרונים שם:","(ז) הטוב והמטיב - לפ\"ז אין אומר בבית האבל ג' הטבות וג' גמולות וכן הוא בב\"י ועיין בב\"ח פה ובש\"ך שם סימן שע\"ט שאין סוברים כן:"]}],"190":[{"s":"<b>שתיית היין אחר הברכה ודיניו. ובו ה סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>אחר שסיים ברכת המזון <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>מברך <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>בורא פרי הגפן <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ויטעום המברך <small>[ואם הפסיק בין הברכ' לטעימה ע\"ל סי' רע\"א סעיף ט\"ו] </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ואח\"כ יטעמו האחרי' אם כול' זקוקי' לכוס אחד ונותן המברך מכוסו לכוס ריקן שבידם לא יטעמו עד שיטעום הוא אבל אם אינם זקוקים לכוסו יכולים לטעום קודם שיטעום הוא. אין צריך המברך לשפוך מכוסו לכוס המסובין <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אלא אם הכוס המסובין פגום <small> (ועיין לעיל סימן קפ\"ב וס\"ס רע\"א):</small>","m":["(א) אחר שסיים וכו' - ר\"ל כשמברך בהמ\"ז על כוס כמבואר לעיל סימן קפ\"ב יברך בפה\"ג אחר שסיים בהמ\"ז והיינו אפילו אם כבר בירך על היין שבתוך הסעודה שכל מה שאוכל ושותה אחר בהמ\"ז סעודה אחרת היא לפי שבהמ\"ז היא סילוק והיסח הדעת למה שלפניה:","(ב) ע\"ל סימן רע\"א סט\"ו - דחוזר ומברך ובמילתא דשייך לסעודה אינו חוזר ומברך בדיעבד:","(ג) ואח\"כ יטעמו האחרים - שכיון שהוא בירך על כוס זה נכון הוא שישתה הוא תחלה:","(ד) אם כולם זקוקים - הלשון מגומגם קצת וכונתו כאלו כתב וכן אם כולם זקוקים ור\"ל דלא מיבעיא אם יש רק כוס אחד וכולם שותים מכוס זה בודאי נכון לכתחלה שהוא יטעום מקודם ואפילו אם כל אחד כוס ריקן לפניו והוא מערה לאחר ברכה קודם טעימתו מכוסו לכוסם ג\"כ אין ראוי שיטעמו הם קודם מאחר שעכ\"פ הם זקוקים כולם לכוסו:","(ה) אבל אם אינם וכו' - ר\"ל אם יש לפני כל אחד כוס יין והוא מוציאם בברכתו והוי כאלו הם מברכין בעצמם אינם צריכין להמתין עליו:","(ו) אין צריך וכו' - קאי אדלעיל שלא היו זקוקין לכוסו של המברך והטעם דא\"צ לשפוך משום דכיון דיצאו בברכתו א\"כ כוסות כל אחד מקרי כוס של ברכה:","(ז) פגום - שאז צריך לשפוך מכוסו לכוסם מעט קודם שטעם ממנו כדי לתקן פגימתם ובזה צריכין ליזהר שלא יטעמו קודם שיטעום הוא תחלה כיון שהם זקוקים לכוסו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>אחר ששתה כוס של ברכת המזון יברך ברכה אחת <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>מעין <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>שלש:","m":["(ח) אחר ששתה וכו' - ואם דעתו לשתות עוד לא יברך אחריו אלא לבסוף אחר גמר שתייתו ודוקא כשדעתו לשתות מיד דאל\"ה יש לחוש שמא יתעכל דעיכול של שתיה איננו שיעור גדול כ\"כ עיין לעיל סימן קפ\"ד ס\"ה מ\"א ועיין בבה\"ל:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>שיעור <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>שתיית <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"4\"></i>יין להתחייב בברכ' אחרונה יש ספק אם די בכזית <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"5\"></i>או ברביעית <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>לכך יזהר לשתות או פחות מכזית או רביעית כדי להסתלק מן הספק והכא אי אפשר לשתות פחות מכזית דכל דבר שצריך כוס צריך לשתות ממנו כמלא לוגמיו <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>שהוא רוב רביעית הלכך ישתה רביעית <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>שלם:","m":["(ט) שתיית יין - וה\"ה בשאר משקין יש ספק זה:","(י) אם די בכזית - כמו באכילה דקי\"ל בכל מקום שיעור אכילה בכזית [והוא כחצי ביצה כמבואר בסימן תפ\"ו] ולפ\"ז במשקין יחוייב בברכה אחרונה בשליש רביעית דרביעית הוא ביצה וחצי כידוע ועיין סימן רע\"א סי\"ג מה שכתבתי שם במ\"ב ובה\"ל:","(יא) או ברביעית - כמו שמצינו בכמה דיני התורה לענין משקין דשיעורן ברביעית:","(יב) והכא וכו' - פי' דבשאר שתיות שהם רשות יכול גם להסתלק מן הספק באם ישתה פחות מכזית דבזה פטור לכו\"ע מלברך אחריו אבל הכא בכוס של ברכת המזון א\"א לעשות כן דכיון דטעון כוס צריך עכ\"פ לשתות מלא לוגמיו שהוא רוב רביעית והוא הרבה יותר מכזית:","(יג) שהוא רוב רביעית - היינו באדם בינוני מחזיק שיעורו כך אבל באדם גדול ביותר משערינן במלא לוגמיו דידיה ומ\"מ לא בעי לשתות טפי מרביעית:","(יד) רביעית שלם - עיין ט\"ז שכתב דלעיקר הדין קי\"ל במלא לוגמיו ולפיכך אם לא שתה רק כמלא לוגמיו חייב לברך ברכה אחרונה אלא דלכתחלה יראה לשתות רביעית כדי לצאת לכו\"ע אכן כל האחרונים דחו דבריו והעלו דכל שלא שתה רביעית שלם בין ביין בין בשאר משקין אין רשאי לברך ברכה אחרונה וכדעת השו\"ע עוד הסכימו דאין חילוק בין שאר משקין ובין יין שרף אע\"פ דביי\"ש מייתבא דעתיה דאינשי בפחות מרביעית דלא חילקו חכמים בשיעורן ודלא כט\"ז לקמן בסימן ר\"י:","(טו) יטעום אחד מהמסובין - דכיון שהמסובין שמעו מתחלה את הברכה והוא כוון עליהם להוציאם מהני טעימתם לכולם ועיין בבה\"ל מה שכתבנו בשם חי' רע\"א:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>אם המברך אינו רוצה לטעום <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>יטעום א' מהמסובין כשיעו' ואין שתיית שנים מצטרפת ומ\"מ מצוה מן המובחר שיטעמו כלם <small>[ועיין לקמן סי' רע\"א סעיף י\"ד]:</small>","m":["(טז) ואין שתיית וכו' - דבעינן שיטעום בעצמו או אחד מהמסובין שיעור הנאה שתתיישב דעתו עליו והיינו כמלא לוגמיו:","(יז) שיטעמו כולם - היינו טעימה בעלמא וא\"צ מלא לוגמיו רק לאחד. והנה הכא איירי המחבר רק לענין מצות שתיית הכוס ולפי מה שביאר המחבר לעיל בס\"ג דלצאת ידי ספק יראה לשתות רביעית שלם לא יצוייר מה שכתב דמצוה מן המובחר שיטעמו כולם בכוס המחזיק רביעית אם לא שהוא מחזיק יותר מרביעית:","(יח) סימן רע\"א - דיש מי שאומר דשתיית כולם מצטרפין למלא לוגמיו ועיין לקמן בסימן רע\"א ס\"ק ס\"ט במ\"ב:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>כשמסובין בסעודה גדולה ואין יודעים עד היכן יגיע כוס של ברכת המזון כל אחד <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>מהמסופקים אם יגיע לו צריך לברך בורא פרי הגפן <small>[וע' לעיל סי' קע\"ד סעיף ה' בהגה:</small>","m":["(יט) צריך לברך - דמסתמא אינו מכוין לצאת בברכת המברך מאחר שאינו יודע אם יגיע לו וכתב המ\"א דאם המסובין נתכונו בהדיא אם יגיע להם הכוס שיצאו בברכתו יוצאין בזה אם גם המברך נתכוין להוציא בברכתו כל אחד מהמסובין וכן הסכימו הרבה אחרונים. ואך יזהרו כולם מי שרוצה לטעום מן הכוס על סמך ברכת המברך שלא ישיחו עד שיטעמו מן הכוס כדי שלא יהיה הפסק בין הברכה להטעימה:"]}],"191":[{"s":"<b>אם הפועלים מחויבים לברך. ובו ג סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>פועלים העושים מלאכה אצל בעל הבית <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>מקצרים <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>בברכת המזון כדי שלא לבטל מלאכת בעל הבית כיצד ברכה ראשונה כתקנה ושניה פותח בברכת הארץ וכולל בה בונה ירושלים וחות' בברכת הארץ ואין אומרים ברכת הטוב והמטיב כלל במה דברים אמורים כשנוטלים שכר על מלאכתן מלבד הסעודה אבל אם אין נוטלים שכר אלא הסעודה שאוכלים לבד מברכין כל ד' ברכות כתקון וכן אם בעל הבית מיסב עמהם אע\"פ שנוטלים שכר מלבד הסעודה מברכין כל ד' ברכות:","m":["(א) וכולל בה בונה ירושלים - דאף דדרשינן בגמרא מקרא שיברך לה' בבהמ\"ז על המזון ועל הארץ ועל ירושלים אין ר\"ל שמן התורה צריך לחתום על כל אחד ואחד בברכה בפ\"ע אלא מדאורייתא די כשיברך על שלשתן בברכה אחת אך דרבנן תקנו לחתום בברכה על כל אחד ובפועלים משום בטול מלאכה תקנו שרק הזן יברך בפ\"ע אבל ברכת הארץ ובנין ירושלים כיון שדומות זו לזו יכללם בברכה אחת [מ\"א בביאור דברי רש\"י וכ\"כ עוד הרבה אחרונים לדינא]:","(ב) כלל - שזו אינה כ\"א מדרבנן בעלמא ועקרוה אצל פועלים בין שמברכין בעצמן בין ששומעין מפי אחר המזמן ומברך בהמ\"ז כתיקונה הרי הן עומדין למלאכתן כשחותם ברכת ירושלים ולענין ברכת הזימון אם מחויבין פועלים בכך או לא יש דעות בין האחרונים ולפי מה שכתב בס\"ב לא נ\"מ מידי לדידן דבודאי חייבין אך כשאוכל פועל עם אנשים אחרים והוא גמר סעודתו מקודם נראה דלא ימתין עליהם אם אינם רוצים לענות אותו דבכגון זה בודאי בעה\"ב מקפיד ועיין לקמן בסימן ר' במ\"א סק\"ב:","(ג) כשנוטלין שכר - וע\"כ צריכין למהר המלאכה [רש\"י]:","(ד) מיסב עמהם וכו' - דמסתמא מוחל להם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>והאידנא לעולם מברכים כל ארבע ברכו' שאין דרך בני אדם עכשיו להקפיד בכך ומסתמא אדעתא דהכי שוכרים פועלים שיברכו כל ד' ברכות כתקנם:","m":[]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אסור לעשות <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>מלאכה בעודו מברך <small> (וכן הוא לעיל סוף סי' קפ\"ג):</small>","m":["(ה) אסור לעשות מלאכה וכו' - מפני שנראה כמברך בדרך עראי ומקרה ואפילו תשמיש קל אסור לעשות ואצ\"ל שלא יעסוק בדבר שצריך לשום לבו אליו וכתב הט\"ז שיש ליזהר שלא לעיין אפילו בד\"ת בשעה שמברך בהמ\"ז כי זה מורה על היות הבהמ\"ז אצלו רק על צד המקרה וההזדמן ולאו דוקא בבהמ\"ז ה\"ה כשעוסק בתפלה או באיזו ברכה אחרת וזה נכלל במאמר תורתנו ואם תלכו עמי קרי דהיינו שלא יהיו המצות אצלנו על צד המקרה וההזדמנות בעלמא:","(ו) לעיל סוף סימן קפג - אלא דשם מיירי שמקודם התחיל במלאכה וכאן מיירי שמקודם התחיל לברך והיא היא:"]}],"192":[{"s":"<b>ברכת זימון בשלשה או בעשרה. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>היו מסובין ג' חייבים בזימון <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>שאומר אחד מהם <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>נברך שאכלנו משלו והם עונים ואומרי' ברוך שאכלנו משלו ובטובו חיינו <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>והוא חוזר <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>ואומר ברוך שאכלנו משלו ובטובו <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>חיינו <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i>בא\"י אמ\"ה הזן את העולם וכו' <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואם הם ד' <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>יכול לומר ברכו שאכלנו משלו <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אבל <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>יות' טוב לומר <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>נברך שלא להוציא עצמו מן הכלל <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ואם הם עשרה צריך להזכי' את ה' שאומ' נברך אלהינו וכו' והם עונים ואומרים ברוך אלהינו וכו' <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ואין לומר נברך לאלהינו <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>בלמ\"ד <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ובין שיהיו עשרה או מאה או אלף או רבוא כך הם מברכים <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>וכל המשנה מזה הנוסח כגון שאומ' נברך <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>על המזון שאכלנו או שאומ' <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>למי שאכלנו משלו או שאומר במקום ובטובו <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>מטובו או במקו' חיינו אומ' חיים הרי זה בור <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>וכשהם עשרה <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>כיון שמזכירים את השם יכול לומ' נברך אלהינו על המזון שאכלנו משלו:","m":["(א) חייבין בזימון - דהיינו שחייבין להזדמן ולצרף ברכתם בלשון רבים דהיינו שאחד יאמר נברך שאכלנו וכו' ואסמכו רבנן אקרא דכתיב גדלו לה' אתי ונרוממה שמו דמשמע שאחד יאמר לשנים גדלו א\"נ ממאי דכתיב כי שם ה' אקרא הבו גודל לאלהינו וכ\"ש אם הם יותר עד עשרה כמו שיתבאר לפנינו:","(ב) נברך - בזוהר הזהירו לומר בפיו קודם בהמ\"ז תן לנו הכוס ונברך או באו ונברך לפי שכל דבר שבקדושה צריך הזמנה בפה עובר לעשייתו כדי להמשיך הקדושה ומזה נוהגים לומר בל\"א (רבותי, מיר וועלין בענטשין) והם עונים יהי שם ה' מבורך מעתה ועד עולם:","(ג) והוא חוזר ואומר וכו' חיינו - ואם המסובין צריכין לענות אמן אחריו יש דעות בין האחרונים והמנהג שלא לענות:","(ד) ובטובו חיינו בא\"י אמ\"ה וכו' - משמע מזה דלא יאמר ברוך הוא וברוך שמו ויש פוסקים כתבו לומר ב\"ה וב\"ש וכן המנהג ועיין במ\"א ובשארי אחרונים דעכ\"פ לא שייך זה ביחיד וגם בשלשה אין לומר אותו רק המברך ולא שנים המזמנים עמו:","(ה) יכול לומר ברכו - כיון שהם שלשה וראוים לברך בלשון רבים בלעדו אבל בשנים לא יכול לומר ברכו רק נברך ובדיעבד אם אמר בשנים ברכו אפשר דיצא:","(ו) בלמ\"ד - דגבי ברכה לא כתיב למ\"ד דכתיב ברכו עמים אלהינו:","(ז) על המזון שאכלנו - דמשמע דמברך לבעה\"ב המאכילו דאי לרחמנא למה הוא מזכיר מזון בלא מזון יש הרבה לברכו [תוס']:","(ח) למי שאכלנו משלו - דמשמע דרבים הם זה זן את זה וזה זן את זה ולפי דבריו הוא מברך לבעה\"ב [רש\"י] וגבי מטובו פירש משום דממעט בתגמוליו של מקום דמשמע דבר מועט כדי חיים וטעם שלא לומר חיים דמשמע דהוא מוציא עצמו מן הכלל:","(ט) יכול וכו' - דתו ליכא למטעי דקאי על בעה\"ב המאכילו:","(י) אינם יכולים לחזור - דבדיעבד יצאו בזימון בלא שם ואם יכול המזמן לחזור אח\"כ ולומר ברוך אלהינו וכו' או שצריך לומר ג\"כ בלא שם מאחר שהעונים אמרו מתחלה בלא שם יש דעות בין האחרונים עיין בשע\"ת ולכו\"ע אם הם אמרו בשם יכול גם הוא לחזור ולומר ברוך אלהינו וכו' אף דנברך אמר בלא שם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>אם טעה המזמן <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"5\"></i>בעשר' והעוני' ולא הזכירו אלהינו אין יכולים לחזור אבל אם עדיין לא ענו אחריו יחזור ויזמן בשם:","m":["(יא) יחזור ויזמן בשם - דכיון שלא ענו עדיין לא נתקיים מצות זימון והוי כלכתחלה:"]}],"193":[{"s":"<b>אם מצטרפין לזימון אם לאו. ובו ו סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>שנים שאכלו אע\"פ שבברכת המוציא <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>פוטר א' את חבירו <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>מצוה לחלק שיברך כל אחד ברכ' המזון לעצמו <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>בד\"א כשהיו שניה' יודעים לברך ברכת המזון אבל אם אחד יודע והשני אינו יודע מברך היודע ויוצא השני <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אם <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>מבין לשון הקודש אלא שאינו יודע לברך <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>וצריך לכוון מלה במלה לכל מה שיאמר: <small>הגה וצריך המברך שיכוין להוציאו [מרדכי ר\"פ שלשה שאכלו וב\"י בשם סמ\"ג]: </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אבל <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אם אינו <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>מבין אינו יוצא בשמיעה <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>אבל שלשה שאכלו אינ' רשאים ליחלק ושנים שאכלו <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>מצוה שיחזרו אחר שלישי שיצטרף עמהם לזימון <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>וכן ארבעה או חמשה אסו' להם ליחלק <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>שכלם נתחייבו <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>בזימון ששה נחלקים כיון שישאר זימון לכל חבורה עד עשר' ואז אין נחלקים עד שיהיו עשרי' כיון שנתחייבו בהזכרת השם: <small>הגה <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>דאז יכולי' לחלוק אם ירצו <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>ונ\"ל דה\"ה בששה אין מחויבים לחלק רק אם ירצו נחלקים </small> ומצוה לחזור אחר עשרה <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>ומיהו אם היו רבים מסובים יחד ואינם יכולי' לשמוע <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>ברכת <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>זימון מפי המברך ואינם רשאים ליחלק לחבורות של עשרה עשרה מפני שיצטרכו <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>לברך בקול רם <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>וישמע בעל הבית <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>ויקפיד עליהם יכולים ליחלק לחבורות של <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>ג' ג' ולברך בנחת כדי שלא ישמע בעל הבית <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>וזה טוב להם ממה שלא יצאו ידי חובת ברכת זימון שהרי <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>אינם יכולים לשמוע מפי המברך:","m":["(א) פוטר אחד וכו' - ר\"ל דבהמוציא אף לכתחלה יכול כ\"א לצאת בברכת חבירו:","(ב) מצוה לחלק - כלומר דאע\"ג דבדיעבד אף בבהמ\"ז בודאי יוצא ע\"י חבירו המוציאו מ\"מ לכתחלה מצוה ליחלק והטעם שחלקו בין בהמ\"ז להמוציא דבתחלת הסעודה שקובעים לאכול יחדו דעתן להצטרף משא\"כ בסוף הסעודה דעתן להפרד זה מזה הלכך צריך לברך כ\"א לעצמו ויש עוד טעם משום דבהמ\"ז דאורייתא החמירו בה ועיין בפמ\"ג שכתב דנכון לחוש לטעם הראשון וע\"כ אף אם לא אכל כדי שביעה דחיובו הוא רק מדרבנן ג\"כ מצוה ליחלק ולברך כ\"א לעצמו:","(ג) אחד יודע וכו' - עיין לקמן סימן קצ\"ז ס\"ד במ\"ב:","(ד) שיכוין להוציאו - וגם השומע צריך שיכוין לצאת כמ\"ש בסימן רי\"ג ס\"ג ועיין במה שכתבנו שם:","(ה) אבל אם אינו וכו' - ולפי זה הנשים יברכו לעצמן וה\"ה ע\"ה כשאינו מבין ברכת המוציאו ויש פוסקים שסוברין שבלה\"ק יוצא אדם ידי חובתו בשמיעה אע\"פ שאינו מבין הלשון (משא\"כ בשאר לשונות דלכו\"ע אינו יוצא אם אינו מבין הלשון) וכן המנהג שנשים יוצאות י\"ח בשמיעה מהמברך אע\"פ שאינן מבינות כלל ואפילו בקידוש שהוא דאורייתא לכו\"ע להנשים אפ\"ה יוצאות בשמיעה וכן ע\"ה אע\"פ שאינן מבינים דברי המקדש [אחרונים] ומ\"מ יותר טוב שיאמרו אחרי המברך והמקדש מלה במלה בלחש אם אפשר להם דבזה יצאו לכל הפוסקים ובלא\"ה נכון לעשות כן לכו\"ע דא\"א לכוין ולשמוע היטב וכמבואר לעיל בסימן קפ\"ג ס\"ז ע\"ש:","(ו) אינם רשאין ליחלק - דכבר נתחייבו בזימון משאכלו ביחד. ודע דחיוב זימון הוא דוקא כשאכלו פת שחייבין עליו בהמ\"ז אבל אם אכלו פירות ואפילו הן משבעה מינים לא כדקי\"ל בסימן רי\"ג דאין זימון לפירות ויש מחמירין בז' מינים להצריכו זימון ולכן טוב שלא יקבעו ג' ביחד על ז' מינים כדי לאפוקי נפשין מפלוגתא [ב\"ח] וברכי יוסף כתב שהמנהג פשוט לקבוע כמה אנשים על פירות מז' מינים וכן לאכול פת הבאה בכיסנין:","(ז) מצוה שיחזרו - היינו אם הוא עמהם בביתם מצוה ליתן לו דבר מה לאכול כדי שיצטרף עמהם ומשמע בגמרא דאף אם הוא שמש המשמשם בסעודה שאין דרכן לאכול אתו ביחד מצוה שיקראו לו לאכול אתם כדי שיוכלו לזמן:","(ח) אחר שלישי - ופשוט דאם הוא אחד א\"צ לחזור אחר שנים:","(ט) שכולם נתחייבו - כלומר אע\"פ שאם ילך אחד ישארו שלשה ויזמנו מ\"מ הוא לא יצא ידי חובתו שגם הוא נתחייב בזימון:","(י) יכולים ליחלק - עשרה לכאן ועשרה לכאן ונמצא שכולם זמנו בשם:","(יא) אינן מחויבין לחלק - היינו דלא אמרינן טוב יותר להתחלק כדי להרבות בברכות ועיין בד\"מ שדעתו דאדרבה שמצוה מן המובחר שלא להתחלק בין בעשרים ובין בששה משום ברוב עם הדרת מלך רק דמדינא אין איסור בדבר אם יתחלקו ויש שחולקים ע\"ז וס\"ל כיון שיש בכל כת ג\"כ מקצת רוב עם וגם נתקיים מצות ברכת זימון בכל חד וחד ולהכי שקולים הם ויכול לעשות כמו שירצה אפילו לכתחלה:","(יב) אחר עשרה - כדי שיהיו יכולים לברך בשם ועיין באחרונים דאפילו אם הם שבעה מצוה לחזר אחר עוד שלשה ועיין במש\"כ לעיל בסק\"ז:","(יג) לשמוע ברכת הזימון - דאם היו יכולין לשמוע ברכת זימון מפי המזמן אף דכל ברכת המזון אינם יכולין לשמוע מרחוק לא היו רשאין ליחלק על ג' אלא ישמעו ברכת זימון לבד מפי המזמן וברהמ\"ז יברכו כ\"א בפני עצמו בלחש וכמבואר לעיל סימן קפ\"ג ס\"ז:","(יד) ואינם רשאים וכו' - דאם היו יכולין ליחלק לעשרה עשרה לא היו רשאין ליחלק לחבורה של ג' כדי שלא יפסידו מלהזכיר הזימון בשם:","(טו) בקול רם - כדי להשמיע ברכת הזימון לכל העשרה:","(טז) ויקפיד עליהם - במה שעושין חבורות לעצמן. וה\"ה אם צריכין ללכת לדבר מצוה ואין להם שהות להמתין שתתבטל המצוה שרשאין לחלק לג' ג' כ\"כ המ\"א ובח\"א מגמגם בזה ופוסק דעכ\"פ כשלא נשארו עשרה בלעדם בודאי אסור לצאת אפילו לדבר מצוה. ומ\"מ אם הוא מצוה דאורייתא אפשר דיש להקל בכל גווני ועיין בפמ\"ג:","(יז) ברכת זימון שהרי וכו' - אבל אם היו יכולין לשמוע ברכת זימון לא היו רשאין ליחלק וכנ\"ל בסקי\"ג והאחרונים חולקים ע\"ז משום דנהי דקי\"ל בסימן קפ\"ג דהאידנא מברכין כ\"א מהמסובין כל הבהמ\"ז בלחש מ\"מ צריכין לשמוע היטב גם לדברי המברך ולומר עמו בלחש כל מלה ומלה ולענות אמן על כל ברכה וברכה ועכ\"פ עד הזן את הכל בודאי צריכין להאזין גם לדברי המברך דעד שם הוא ברכת הזימון כדלקמן בסימן רי\"ש בהג\"ה וא\"כ אף אם יכולין לשמוע ברכת זימון מפי המברך כל שאין יכולין לשמוע מלה במלה מפי המברך עד הזן את הכל מוטב להם ליחלק ג' ולברך בלא שם ממה שלא יצאו כלל ידי חובת זימון מדינא. כתבו האחרונים היכא שיש מסיבה גדולה יש ליתן לברך ברכת הזימון למי שקולו חזק כדי שישמעו כל המסובין וכנ\"ל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>אפי' לא הוקבעו מתחלה כולם לאכול יחד אלא שהשנים קבעו ואחר כך בא השלישי וקבע עמהם או שאחד קבע תחלה ואח' כך קבעו השנים עמו אינם רשאי' ליחלק כיון שהם <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>קבועים יחד בגמר האכילה ומכל מקו' אם יאכל עמהם בלא קבע רשאים ליחלק אלא א\"כ הוא שמש: <small>הגה ומ\"מ אפי' כ\"מ שרשאין ליחלק עדיף טפי לזימון משום דברוב עם הדרת מלך (ב\"י):</small>","m":["(יח) שהשנים קבעו - קביעות נקרא כשיושבים ואוכלים על שלחן אחד או במפה אחת אפילו כל אחד אוכל מככרו וכמבואר לעיל בסימן קס\"ז סי\"א ועיין לעיל שם בסי\"א בביאור הגר\"א דדעתו שם דבעה\"ב עם בני ביתו שישבו לאכול הוי קביעות ומצטרפי אפילו בלא שלחן אחד:","(יט) בגמר האכילה - חל עלייהו חובת זימון עי\"ז שאכלו לבסוף ביחד ומשמע מזה הא אם לא גמרו גם סוף אכילה ביחד כגון שבא אחד לאכול אצל שנים אחר שכבר התחילו לאכול וגם גמרו סעודתן שלא בזמן אחד אותן שגמרו מקודם רשאין לברך בפני עצמן דעכ\"פ התחלה או גמר בעינן ביחד ומ\"מ אם המתינו לאחר אכילתם ולא ברכו עד שגמר גם השלישי לאכול חייבין לזמן ואין רשאין ליחלק ואע\"ג שלא גמרו ביחד כל היכי דאי מייתי להו מידי מצי למיכל מינייהו כמו גמרו ביחד דיינינן להו וכעין ההיא דריש סימן קצ\"ז ע\"ש:","(כ) ומ\"מ אם וכו' - הוא כמו אבל:","(כא) בלא קבע - היינו שלא אכלו בדרך קבע בישיבה ועל שלחן אחד ואפילו התחילו לאכול בשלשה מתחלת הסעודה ועד סופה:","(כב) הוא שמש - שדרך אכילתו בלא ישיבת קבע לכך הוא מצטרף בכל גווני:","(כג) כ\"מ שרשאין ליחלק - היינו שאכלו השלשה בלא קביעות וכן בעשרים או בששה אף שע\"פ דין רשאים ליחלק מ\"מ עדיף טפי שלא ליחלק:","(כד) עדיף טפי לזמן - עיין במ\"א שהקשה דמהרבה פוסקים משמע לענין שלשה שאכלו בלא קבע דאין אחד יכול להוציא חבירו בביהמ\"ז וממילא גם לענין זימון אין רשאין וע\"ש שהאריך בזה ואף דיש איזה אחרונים שדחו ראייתו לענין זימון מ\"מ יותר מסתבר כדבריו וכן בפמ\"ג כתב ג\"כ דבמקום שאין אחד יכול להוציא חבירו בבהמ\"ז אם יכולים להצטרף לענין זימון צ\"ע למעשה ומסיים דבעשרה שיש הזכרת השם אפשר דאסור לכ\"ע לזמן באין חייבין וכן משמע בחיי אדם כלל מ\"ח דין ז':"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>אם היו רוכבים ואמרו נאכל אע\"פ שכל אחד אוכל מככרו ולא ירדו מהבהמות מצטרפין כיון שעמדו במקום אחד אבל אם היו הולכים ואוכלי' לא ואם היו אוכלים בשדה מפוזרי' ומפורדי' אע\"פ שאוכלי' כלם בשעה אחת ומככר א' כיון שלא קבעו מקום לאכול אינם מצטרפין: <small>הגה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>המנהג <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>שלא לזמן בבית <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"5\"></i>עכו\"ם ונראה לי הטעם משום דלא יוכלו לקבוע עצמן בבית עכו\"ם משום יראת העכו\"ם הוי כאלו אכלו בלא קבע ועוד דיש לחוש לסכנה אם ישנו בנוסח הברכ' ולא יאמרו הרחמן יברך ב\"ה הזה ולכן מתחלה לא קבעו עצמן רק לברך כל א' לבדו ולכן אין לשנות המנהג אף אם לא היו טעמים אלו מספיקים מ\"מ מאחר דכבר נהגו כך הוי כאלו לא קבעו עצמן ביחד:</small>","m":["(כה) אם היו רוכבים וכו' - סעיף זה כלשונו ממש מובא לעיל בסימן קס\"ז סעיף י\"ב אלא דשם מיירי לענין להוציא בברכת המוציא והכא מיירי לענין צירוף זימון ודין אחד לשניהן וכבר ביארתי שם במ\"ב באר היטב ע\"ש:","(כו) הולכים ואוכלים לא - וביושבין בעגלה ואוכלין ביחד כשהם נוסעין עיין בסימן קס\"ז מה שכתבתי בשם המ\"א שמסתפק בזה ובח\"א הכריע דבזה וכן בכל מקום שיש ספק בשלשה יזמנו אבל בעשרה יש לחוש להזכרת השם לבטלה. ומ\"מ נ\"ל דיזמן בלא שם דהא בדיעבד יצא בעשרה אף אם לא הזכיר השם וכדלעיל בסוף סימן קצ\"ב:","(כז) שלא לזמן וכו' - האחרונים חולקים ע\"ז וכהיום המנהג שמזמנין ובהרחמן אומרים הרחמן הוא ישלח לנו ברכה מרובה בהליכתנו ובישיבתנו עד עולם ונוכל לומר הרחמן הוא יברך את בעה\"ב הזה וקאי על בעל הסעודה. ומכ\"ש אם כל אחד אוכל משלו שאז אפילו בבית ישראל אומרים הרחמן הוא יברך אותנו וכו' ואם אוכלין במלון ביום דרך עראי בבית עו\"ג אפשר דאין זה קביעות ואין מזמנין [מ\"א] וטוב שלא יקבעו אז שלשתן יחד ויצאו מידי ספק [פמ\"ג]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>שלשה שישבו לאכול וברכו ברכת המוציא אפי' כל אחד אוכל מככרו <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>ואפי' לא אכל עדיין כזית פת <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>אינם רשאים <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>ליחלק:","m":["(כח) אינם רשאים ליחלק - היינו אפילו רוצה לגמור סעודתו קודם שיגמרו האחרים כיון שהחיוב של זימון חל כבר עליו בהתחלת אכילה שלו:","(כט) כל אחד לשנים - עיין בביאור הלכה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>שלשה שבאים משלש חבורות של שלש שלש בני אדם ונתחברו אלו השלשה <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>אם זימנו עליהם במקומם כגון שהפסיקו כל א' לשנים <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>עד שאמרו הזן <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>שוב אינם יכולים לזמן <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>אפי' אכלו אח\"כ יחד וגמרו סעודתן ואם לא זמנו עליהם במקומם חייבים לזמן ואינם רשאים ליחלק <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i><i data-commentator=\"Turei Zahav\" data-order=\"8\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>ואפי' לא אכלו אלו השלשה ביחד <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"7\"></i>משנתחברו:","m":["(ל) אפי' אכלו אח\"כ - דכבר פרח זימון מינייהו ע\"י שזימנו עליהם מקודם ומ\"מ בהמ\"ז חייבים לברך מתחלת ברכת הזן וכדלקמן בסימן רי\"ש בהג\"ה:","(לא) ואינם רשאים ליחלק - כיון שנועדו עתה יחדו וכל אחד בא מחבורה שכבר נתחייב שם בזימון ואף דנתבאר בס\"ו בהג\"ה דאסור ליפרד מחבורה של ג' שעי\"ז מפסיד הזימון שלהם וא\"כ היה לכל אחד ואחד לחזור לחבורה שלו י\"ל דמיירי הכא שנתפרדה חבורתם הראשונה א\"נ לפי מה דמבואר לקמן בסי' רי\"ש בא\"ר וש\"א דבמקום שיש אונס או הפסד ממון מותר לאחד לגמור סעודתו מקודם שגמרו השנים ולברך בפני עצמו מיירי הכא ג\"כ בכה\"ג שהיו אלו השלשה מוכרחין למהר ולגמור סעודתן מקודם ולכן אם נזדמנו אלו השלשה ביחד יזמנו בפני עצמן:","(לב) ואפילו לא אכלו וכו' - וקשה הא קי\"ל לעיל סימן קפ\"ד דבהמ\"ז צריך לברך דוקא במקום שאכל וא\"כ כל אחד ואחד צריך לחזור למקום שאכל מתחלה יש מתרצים דהכא מיירי בעקרו בשוגג ממקומם דבזה לא מטרחינן אותו לחזור למקומו לדעת הרמב\"ם וכנ\"ל שם בסעיף א' וכן פסקו שם האחרונים במקום הדחק ובעניננו נמי כיון דכאן יכול לזמן וכשיחזור לשם יברך ביחידי כשעת הדחק דמי ועוד י\"ל דה\"ק ואפילו לא אכלו יחד כלומר אלא כל אחד אכל בפני עצמו שלא קבעו דאינם חייבים בזימון כמ\"ש ס\"ב הכא חייבין כיון שכבר נתחייבו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i>שלש חבורות שהיו בכל אחת ארבעה ופירש אחד מכל חבורה ונצטרפו לחבורה אחרת וזימנו השלשה הנשארים פרח זימון מינייהו כיון שחבריהם זימנו <i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>והוא הדין אם לא היו בכל חבורה אלא שלשה והלך א' מכל חבורה קודם זימון ונתחברו אלו השלשה ובא אחד לכל חבורה ונצטרף עם שנים הראשונים וזימנו יחד פרח זימון מאלו השלשה כיון שכבר זימנו חבורתם אע\"פ שלא זימנו עמהם: <small>הגה שלש חבורות שאכלו ובכל חבורה שלשה בני אדם אסור לכל אחד ליפרד מכל חבורה ולזמן ביחד דהרי השנים הנשארים בכל חבורה אינן יכולים לזמן אח\"כ אבל אם היה בכל חבורה ד' מותר ליפרד אחד מכל חבורה ולזמן ביחד והנשארים יזמנו כל חבורה במקומם [ב\"י בשם הרשב\"א]:</small>","m":["(לג) פרח זימון מינייהו - ובזה דוקא אם לא אכלו אח\"כ יחדו אבל אם אכלו אח\"כ יחד מצטרפין ואינו דומה להא דסעיף ה' דהא לא זימנו עליהם מקודם [חי' רע\"א בשם תר\"י]:","(לד) כיון שחבריהם זימנו - עיין בביאור הלכה:","(לה) ובא אחד וכו' - היינו אחד מן השוק אכל מעט בסוף סעודתן ונצטרף עמהם ולישנא לכל חבורה שכתב המחבר לאו דוקא דאפילו רק לחבורה אחת א\"כ פרח זימון מן אחד ולא נשאר כאן אלא שנים:","(לו) מותר ליפרד וכו' - ומיירי שכל החבורות היו מתחלה ג\"כ בבית זה אלא שלא נצטרפו ביחד דאל\"ה הלא צריך לברך בהמ\"ז במקומו:"]}],"194":[{"s":"<b>שלש' שאכלו כאחד ונפרדו לענין הזימון מה דינם. ובו ג סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>שלשה שאכלו כאחד ושכחו ובירך כל אחד לעצמו בטל מהם הזימון ואין יכולים לחזור ולזמן למפרע <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>וכן אם ברכו שני' מהם <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אבל אם שכח אחד מהם ובירך השנים <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>יכולים לזמן עם השלישי אע\"פ שכבר בירך <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>יכול לומר ברוך שאכלנו משלו והם יוצאי' ידי חובת זימון והוא אינו יוצא ידי זימון שאין זימון למפרע: <small>הגה ואם האחד זימן עם אחרים אף שנים הנשארים אינן יכולים לזמן (ב\"י בשם רשב\"א):</small>","m":["(א) ואין יכולים וכו' - לומר נברך וכו' דלמאי יזמנו זה את זה והרי כבר ברכו בהמ\"ז ואין לשון זימון אלא שאחד יזמן השנים שיהיו מוכנין ומזומנין להצטרף יחד לברכת המזון:","(ב) יכול לומר וכו' - דהא באמת מחוייב בזימון הוא שאכל עמהם ביחד אלא שאין לו תקנה משום שכבר בירך ואין זימון למפרע לכן מהני הצטרפותו עכ\"פ שיהיו הם יוצאין על ידו:","(ג) עם האחרים - היינו שבא לחבורה של שלשה או אפילו שבא לשנים בסוף סעודתם ואכל עמהם מעט:","(ד) אינן יכולין לזמן - על האחד מפני שכבר יצא ידי חובת זימון מיהו אם נזדמן להם אחד מן השוק יכולין לזמן עליו כשיטעום עמהם דחיוב זימון שלהם לא נפקע בשביל אותו שזימן:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>שלשה שאכלו ויצא אחד מהם לשוק <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>קוראי' אותו ומודיעים לו שרוצים לזמן כדי שיכוין ויצטרף עמהם ויענה עמהם ברכת זמון ויוצאי' ידי חובתן <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אף על פי שאינו בא ויושב <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>עמהם והני מילי בשלשה אבל בעשרה כיון שצריכין להזכיר את השם אינם מצטרפים עד שיבא וישב עמהם <small>[ועיין לקמן סי' ר' עד היכן ברכת הזימון]:</small>","m":["(ה) כדי שיכוין - לשמוע ברכת הזימון:","(ו) ויענה עמהם - אבל אם אינו עונה אין מזמנין עליו משום דאינו עומד עמהם אבל אם היה עומד עמהם אף אם אינו עונה עמהם מזמנין עליו בע\"כ כמבואר לקמן סי' רי\"ש [שיו\"ב ומגן גבורים וא\"ר בתירוץ ב']:","(ז) ויוצאין ידי חובתן - וגם הוא יוצא ידי חובת זימון בזה:","(ח) שאינו בא - אלא שעומד נגד הפתח בסמוך להם [ועיין סימן נ\"ה ס\"כ דמבואר שם דאם יש טינוף בינתים מפסיק] וכשיגמור ענינו יבוא הביתה שאכל שם ויברך בהמ\"ז [רמב\"ם] מיהו אם נשתהה שם עד גמר בהמ\"ז וכוון לבו לצאת יצא ידי בהמ\"ז וא\"צ לברך:","(ט) וע\"ל סי' רי\"ש - ס\"ב ולפי מה דפסק שם רמ\"א צריך העונה להמתין עד שיגמרו ברכת הזן:","(י) ואין אחד מהם יודע - דאי אחד מהם יודע כל ברכת המזון בודאי נכון שהוא יברך כל הברכות ויוציאם ידי חובתם ולא לחלק בהמ\"ז לפרקים פרקים:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>שלשה שאכלו כאחד ואין א' מהם יודע כל ברכת המזון אלא <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>אחד יודע ברכה ראשונה ואחד השנייה ואחד השלישית חייבים בזימון וכל אחד יברך הברכה שיודע ואף על פי שאין בהם מי שיודע ברכה רביעית אין בכך כלום <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אבל לחצאין אין לברך אם האחד אינו יודע כי אם חצי הברכ' שאין ברכ' אחת מתחלק' <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>לשתי':","m":["(יא) ברכה ראשונה - היינו לבד מברכת נברך שצריך המזמן לומר בתחלת ברכת הזימון:","(יב) וכל אחד יברך - ר\"ל ויכוין להוציא את חבירו:","(יג) אין בכך כלום - דברכת הטוב והמטיב לאו דאורייתא היא ולפיכך אינה מעכבת להשלש ברכות ומשמע מזה דבאחת משלש ברכות הקודמים אם אין אחד מהם שיודע אותה מעכב שלא יברכו כלל דברכות מעכבות זו את זו ויש פוסקים שסוברים דאף דמן התורה חייב לברך אותם מ\"מ אין מעכבות זו את זו ולפיכך מי שאינו יודע לברך כל הברכות וא\"א לו לקרא לבקי שיוציאו בבהמ\"ז צריך לברך עכ\"פ הברכה שיודע אותה ולענין דינא אם אכל כדי שביעה דחיוב בהמ\"ז שלו הוא מן התורה יש להחמיר כשיטה זו ולברך אותה:\n"]}],"195":[{"s":"<b>חבורות שאוכלים בהרבה מקומות מה דינם. ובו ג סעיפים:</b><br><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>שתי חבורות שאוכלות בבית אחד <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>או בשני בתים אם מקצתן רואים אלו את אלו מצטרפות לזימון ואם לאו אינם מצטרפות <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ואם יש שמש אחד לשתיהן הוא מצרפן <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>וכגון שנכנסו מתחלה על דעת להצטרף <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>יחד <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ויש מי שאומר <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>שאם <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>רשות הרבים מפסקת בין שני הבתים אינם מצטרפין <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>בשום ענין:","m":["(א) רואין אלו וכו' - אפילו כשאוכלים כל אחת על שלחן בפני עצמו:","(ב) מצטרפות לזימון - ר\"ל אם ירצו יכולין להצטרף ולהוציא אחד את כולם בבהמ\"ז:","(ג) ואם לאו וכו' - אפילו כשהם בבית אחד ואפילו אם נכנסו מתחלה ע\"ד להצטרף יחד:","(ד) ואם יש שמש - היינו אפילו אינו אוכל כלל:","(ה) הוא מצרפן - היינו אפילו הם בשני בתים ואין רואין אלו את אלו:","(ו) וכגון שנכנסו וכו' - מסתימת המחבר משמע דאפילו בית אחד ורואין זה את זה ג\"כ לא מצטרפי שתי החבורות יחד אא\"כ כשנכסו מתחלה ע\"ד זה אבל הרבה אחרונים כתבו דבבית אחד לא בעינן כלל שיכנסו מתחלה ע\"ד זה ובכל שרואין זה את זה בלחוד או אפילו באין רואין זה את זה ויש שמש בין שתי החבורות סגי לענין צירוף וכן דעת הגר\"א בבאורו ובאדרת אליהו ע\"ש:","(ז) רשות הרבים וכו' - כתב הט\"ז לאו דוקא ר\"ה ממש שהוא רחב ט\"ז אמות דה\"ה כשיש שביל היחיד מפסיק בינתים ואפשר דדוקא כשהוא קבוע גם בימות הגשמים [א\"ר]:","(ח) בשום ענין - היינו אפילו כשהן רואין זה את זה ויש שמש המשמש לשתיהן:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אכלו מקצתן בבית ומקצתן חוץ לבית אם המברך יושב על <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>מפתן הבית הוא מצרפן:","m":["(ט) מפתן הבית - דהוא רואה אלו ואלו והו\"ל כמקצתן רואין זה את זה:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>כל היכא שמצטרפות שתי חבורות צריך שישמעו שתיהן דברי המברך <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>ברכת <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>זימון <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>בביאור: <small>הגה ובשאר ברכת המזון יברך כל א' לעצמו אבל אם ירצו שהמזמן יוציא כולם צריכים שישמעו כל ברכת המזון דבלא זה לא יצאו כלל (ד\"ע):</small>","m":["(י) ברכת זימון - עיין לקמן בסימן רי\"ש ס\"ב דדעת המחבר דברכת זימון הוא נברך וברוך שאכלנו ודעת הרמ\"א דדוקא עד גמר ברכת הזן וכל זה הוא ג\"כ רק במקום הצורך אבל לכתחלה יותר נכון שישמעו כל הבהמ\"ז מפי המברך והוא יוציאם בכל הברכת המזון [מ\"א והגר\"א] ועיין לעיל סימן קפ\"ג ס\"ז במ\"ב שם:","(יא) בביאור - ובדיעבד אם לא שמע דברי המזמן שאמר נברך רק שמע להעונים שעונים ברוך שאכלנו משלו וכו' מותר גם כן לענות עמהם ביחד:","(יב) צריכים שישמעו וכו' - ויכונו לצאת:"]}],"196":[{"s":"<b>מי שאכל דבר איסור אם מצטרף לזימון. ובו ד סעיפים:</b><br><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i> <i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אכל דבר איסור <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אף על פי שאינו אלא <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>מדרבנן אין מזמנין עליו <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>ואין מברכין עליו לא בתחלה <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ולא <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>בסוף:","m":["(א) דבר איסור - אפילו אין איסורו בעצם אלא משום שהוא אסר ע\"ע דבר זה:","(ב) ואין מברכין עליו - וה\"ה שאין עונין אמן על ברכתו:","(ג) לא בתחלה וכו' - הואיל ודבר איסור הוא ויש עבירה באכילתו מנאץ את ה' בברכתו ע\"ז וכענין שנאמר בוצע ברך נאץ ה':","(ד) ולא בסוף - ואפילו אם אכל כדי שביעה ואם אכל בשוגג ונזכר אחר אכילתו דעת הט\"ז ועוד כמה אחרונים דבזה יוכל לברך בסוף [והיינו אפילו לא אכל כדי שביעה] דבזה לא שייך נאוץ אלא דלענין זימון אפילו בשוגג אין לזמן ע\"ז דאכילת איסור לא חשיבא קביעות. אם גנב או גזל חטים וטחנן ואפאן י\"א שאע\"פ שקנאן בשינוי והרי הם שלו אלא שחייב לשלם לו דמים עבורם מ\"מ אסור לברך ע\"ז בין ברכה ראשונה ובין בהמ\"ז דלענין ברכה דאית בה הזכרת השם חמיר טפי ותמיד הוא בכלל נאוץ וי\"א דהואיל וקנה יכול לברך ודעת המ\"א דלענין בהמ\"ז אם אכל כדי שביעה יש להורות בזה שיברך בהמ\"ז דהוא דאורייתא ויש להחמיר ולברך:","(ה) דבר איסור - ואפי' אכל איסור דאורייתא במקום סכנה כגון מפני חולי והטעם דכיון דסכנה הוא התירא קאכיל ואדרבה מצוה קעביד להציל נפשו וכדכתיב וחי בהם ואחז\"ל וחי בהם ולא שימות בהם:","(ו) וע\"ל סי' ר\"ד - דשם נשנה דין זה ונתבאר שם בס\"ח בהג\"ה דאם אנסוהו לאכול אינו מברך אע\"ג דהיה מוכרח לאכול מפני הסכנה וע\"ש במ\"ב:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אם אכל דבר איסור במקום <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>סכנה מברכים עליו <small> (ועיין לקמן סי' ר\"ד):</small>","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>שלשה שאכלו כאחד וא' נזהר בפת עכו\"ם וא' אינו נזהר או אחד מהן כהן ואוכל חלות אע\"פ שאותו שנזהר <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>אינו יכול לאכול עם אותו שאינו נזהר ולא ישראל עם הכהן כיון שאותו שאינו נזהר יכול לאכול עם הנזהר וכהן עם הישראל <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i>מצטרפין <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i>אבל אם היו כהנים וזר אוכלים כאחד והכהנים אוכלים חלה ונזהרים מפת של עכו\"ם <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>והזר אוכל פת של עכו\"ם אינם מצטרפין <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>וה\"ה לשלשה שמודרים <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>זה מזה שאינם מצטרפין לזימון: <small>הגה ודוקא כשכל אחד אוכל מככרו אבל <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>אם אוכלים מככר בעל הבית מצטרפין דהא אוכלים מככר אחד (א\"ז):</small>","m":["(ז) מצטרפין - אע\"פ שכל אחד אוכל מככרו:","(ח) אינם מצטרפין - שכל צירוף לזימון אינו אלא כשהם יכולים להתחבר יחד באכילתן לאכול לחם אחד וכאן כ\"א נזהר מלחם חבירו:","(ט) לשלשה שמודרים וכו' - בין שכל אחד מהם מודר מחבירו בין שאחד מודר מהשנים והשנים ממנו דעכ\"פ אותו האחד אינו יכול לאכול משלהם והם משלו לכך אינם מצטרפין אבל כששנים מודרים מאחד והוא אינו מודר מהם ודאי מצטרפין כיון שהאחד יכול לאכול עמהם. כתבו הפוסקים דה\"ה כשאחד אוכל חלב או גבינה והשנים בשר מצטרפין שהאוכל גבינה הרי יכול לאכול מלחמם אע\"פ שהוא מלוכלך בבשר אם יקנח פיו וידיחנו [והמנהג שהאוכל גבינה הוא המברך ברכת הזימון ולא להיפוך שהוא הגורם להזימון] אבל אם אוכל גבינה קשה אינן מצטרפין שהמנהג עכשיו שלא לאכול בשר אחר גבינה קשה ע\"י קינוח והדחה וכן מר\"ח עד ט\"ב שאין אוכלים בשר רק בסעודת מצוה ויש שנזהרין גם בזה ואוכלין רק מאכלי חלב כמו שכתב בסימן תקנ\"א אותן שנזהרין מבשר ואוכלין חלב אין מצטרפין עם אוכלי בשר דהרי אין יכולין לאכול זה עם זה אלא אם כן אכלו כזית פת קודם שאוכלי בשר התחילו לאכול בשר בלחמם שאז עדיין היו יכולין לאכול ביחד או שאחד מבני הסעודה אכל כזית לחם אחר שאינו מלוכלך לא בבשר ולא בחלב שזה מצרף את כולם שהרי כולם יכולים לאכול מלחמו:\n"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"4\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אין מזמנין על מי שאכל פחות מכזית:","m":[]}],"197":[{"s":"<b>דיני צירוף לזימון ג' או עשרה. ובו ד סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>שנים שאכלו כא' וגמרו ובא שלישי <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>כל היכא דאי מייתי להו מידי <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>מצו למיכל מיניה מצטרף בהדייהו <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>וחייבים ליתן לו לאכול כדי שיצטרף עמהם <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>והוא שבא עד שלא אמרו הב לן ונברך אבל אם אמרו הב לן ונברך ואח\"כ <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>בא הג' אינו מצטרף <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>עמהם: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>ונטילת מים אחרונים כהב לן ונברך דמי (מרדכי פ\"ג שאכלו) ועיין לעיל סימן קע\"ט:</small>","m":["(א) ובא שלישי - ורוצה לאכול ולהצטרף עמהם לזימון:","(ב) מצו למיכל מיניה - היינו שאינם שבעים כ\"כ ואם היו מביאים להם דברים הממשיכים את הלב לקינוח סעודה כגון פירות וכמהין ופטריות וגוזלות וכה\"ג היו יכולין לאכול ואפילו מעט מהם:","(ג) מצטרף בהדייהו - דחשבינן להו כאלו לא גמרו סעודתן עדיין והוא שקבע עמהם דהיינו שאכל אצלם בשלחן שיושבים וכמ\"ש בסי' קצ\"ג ס\"ב ע\"ש במ\"ב. כתב במאמר מרדכי דה\"ה אם אחד גמר סעודתו מתחלה ואח\"כ באו שנים אצלו ואוכלין ג\"כ מצטרף בהדייהו לזימון אם היו מביאים לו מידי ומצי למיכל מניה ע\"ש עוד כתב דה\"ה בכל זה לענין צירוף עשרה לזמן בשם:","(ד) וחייבים ליתן וכו' - לאו דוקא אלא שר\"ל שמצוה ליתן לו וכמו שכתב לעיל בריש סימן קצ\"ג:","(ה) אינו מצטרף עמהם - דכיון שאמרו כן הרי כבר הסיחו דעתם מאכילה ושתיה ואסור להם שוב לאכול כמבואר לעיל בסימן קע\"ט ס\"א בדעה הראשונה ולהכי אינו יכול להצטרף עמהם דכבר נסתלקו מאכילתם הראשונה ועיין בה\"ל:","(ו) וע\"ל סי' קע\"ט - דשם נתבארו פרטי דינים של הב לן ונברך ונט\"י:","(ז) ואחד אכל וכו' - דאף דעל ירק אין מברכין בהמ\"ז מ\"מ יכול להצטרף ולענות ברוך שאכלנו משלו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>תשעה שאכלו דגן <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>וא' אכל כזית ירק <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>מצטרפין להזכיר השם ואפי' לא טיבל עמהם אלא <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>בציר או לא שתה עמהם אלא כוס אחד שישבו רביעית מכל משקה <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>חוץ מן <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"4\"></i>המים מצטרף עמהם והוא שיהיה המברך אחד מאוכלי הפת <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ואפילו שבעה אכלו דגן ושלשה ירק מצטרפין <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>אבל ו' לא דרובא דמינכר בעינן:","m":["(ח) כזית ירק - טעמו דכיון שאומר שאכלנו ואין אכילה פחותה מכזית או משום דבעינן שיתחייב עכ\"פ בשום ברכה ובפחות מכזית אין חיוב בשום ברכה אחר אכילתו כמבואר לקמן סי' ר\"י:","(ט) מצטרפין - ואם כבר בירך ברכה אחרונה שוב אין יכולין לזמן עליו דכבר נסתלק מהם [מ\"א וש\"א]:","(י) בציר - היינו שטבל ירק בהציר ובין כולם היה רק כזית אפ\"ה מצטרף:","(יא) כוס אחד - דשתיה בכלל אכילה ויכול לומר שאכלנו:","(יב) חוץ מן המים - דמים לא זייני ואינו חשוב להצטרף אפי' הוא צמא ורוצה לשתות ומ\"א חולק ופסק דמצטרף דכל שתיה בכלל אכילה היא והעתיקוהו איזה אחרונים להלכה אכן בספר בגדי ישע ובמגן גבורים הסכימו להמחבר וכן מצדד בספר חמד משה:","(יג) המברך אחד וכו' - דכיון שהוא מוציא את חבריו בברכת הזימון חמיר טפי:","(יד) ירק - וה\"ה איזה משקה וכנ\"ל:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>המצטרף צריך לברך ברכה אחרונה על מה שאכל <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>ואינו נפטר בברכת המזון <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"5\"></i>של אלו במה דברים אמורים דסגי בכל מאכל להצטרף לעשרה <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אבל לשלשה אינו מצטרף עד שיאכל כזית פת <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>וי\"א דבכזית דגן מהני אפי' אינו פת ויש אומרים <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>דבירק ובכל מאכל <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>מהני הילכך שנים שאכלו ובא שלישי אם יכולים להזקיקו שיאכל כזית פת מוטב ואם אינו רוצה <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>לא יתנו לו <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>לשתות ולא מאכל אחר; ואם אירע שנתנו לו לשתות או מאכל אחר יזמנו עמו אע\"פ שאינו רוצה לאכול פת:","m":["(טו) צריך לברך - לאחר שגמר לשמוע ברכת הזימון:","(טז) ואינו נפטר - ר\"ל אפילו אם ירצה לכוין לצאת בבהמ\"ז ג\"כ לא מהני כדקי\"ל [לקמן בסימן ר\"ח סי\"ז ובאחרונים שם] דאין ברכת שלשה פוטרת מעין שלשה ולא ברכת בנ\"ר אך אם אכל תמרים או שתה יין בודאי מהני בדיעבד דהא קי\"ל בסימן ר\"ח דאם בדיעבד בירך עליהן בהמ\"ז יצא ולפי מה דפסקו שם כמה אחרונים דאף על דייסא אם בירך בהמ\"ז יצא גם בדייסא דינא הכי וכתב המ\"א דמ\"מ לכתחלה יכוין בהם שלא לצאת בבהמ\"ז דצריך לברך על כל מין ברכתו הראויה לו:","(יז) להצטרף לעשרה - דבלאו דידיה יש חיוב זימון מן האוכלים פת ולא בעינן ליה אלא להזכרת השם:","(יח) כזית פת - דמחוייב בבהמ\"ז:","(יט) דבכזית דגן וכו' - היינו כגון דייסא וכיוצא בו ממיני מזון שחייב לברך עליו ברכה אחת מעין שלש:","(כ) דבירק ובכל מאכל - וה\"ה שתיה וכנ\"ל בס\"ב לענין עשרה וטעם דעה זו דס\"ל דלענין צירוף לזימון אקילו גם לענין שלשה כיון ששנים מהן אכלו פת ומחויבין בבהמ\"ז והוא שהשלישי אכל כזית שמחויב עכ\"פ לברך ברכה אחרונה:","(כא) הלכך שנים וכו' - הוא מדברי המחבר להכריע בין השיטות דלכתחלה יש לזרזו שיאכל פת דוקא כדי לצאת ידי דעה ראשונה ואם אינו רוצה לא יתנו לו כלל כדי שלא להכניס עצמן לספק חיוב אך בדיעבד אם אירע שנתנו לו איזה דבר שאינו פת צריך לחוש לדעה שניה ולזמן עמו:","(כב) לשתות - ועכשיו נוהגים שאם לא רצה לאכול פת נותנים לו לכתחלה לשתות או לאכול איזה דבר וכדעה האחרונה [אחרונים]:","(כג) מצוה וכו' - דכיון דהרבה מהם אכלו כדי שביעה ומחוייבים בבהמ\"ז מן התורה מוטב שיוציאם ג\"כ אותו שאכל כדי שביעה ומחוייב מן התורה כמותו. וכתבו האחרונים דכ\"ז אם מוציאם בבהמ\"ז אבל אם מברכים כל אחד בפני עצמו אלא שאחד מזמן עליהם לא קפדינן כולי האי ולכתחלה יכול לזמן עליהם אף מי שלא אכל כ\"א כזית:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>חברים שאכלו כא' קצתם אכלו כדי שביעה וקצתם לא אכלו אלא כזית אם כולם יודעים לברך <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>מצוה שיברך אותו שאכל כדי שביעה ויוציא את האחרים ואם אין יודעים כולם לברך מי שאכל כזית <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>יכול להוציא אף אותם שאכלו כדי <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"8\"></i>שביעה: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>וי\"א שאינו חייב לברך מדאורייתא <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>אם לא שתה והוא תאב לשתות (מרדכי פ\"ג שאכלו וב\"י בשם כל בו ושיבולי לקט) וטוב ליזהר לכתחלה אם מקצתן שתו ומקצתן לא שתו שיברך מי <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"9\"></i>ששתה (דברי עצמו):</small>","m":["(כד) יכול להוציא וכו' - דמן התורה יכול להוציא חבירו בבהמ\"ז אע\"פ שלא אכל כלל כיון שחבירו כבר אכל וחייב לברך וכל ישראל ערבים זה בזה אלא מפני שאומר שקר במה שאומר שאכלנו והוא לא אכל הצריכוהו חכמים שיאכל כזית מתחלה ועיין במ\"א שמסתפק דלפ\"ז אם הם רק שנים דבלא\"ה אינם מזמנים אפשר דיכול להוציא חבירו שאינו יודע לברך אפילו אם לא אכל כלל ומצדד להחמיר וכ\"כ בא\"ר דמדרבנן בכל גווני אין אחד מוציא חבירו בבהמ\"ז אא\"כ הוא ג\"כ מחוייב בדבר וכן מוכח בהדיא בחידושי הרא\"ה לברכות ובריטב\"א ר\"ה כ\"ט ובשיטה מקובצת ברכות דף מ\"ח ע\"ש:","(כה) י\"א שאינו חייב וכו' - דס\"ל דמה דדריש ר\"מ בגמרא ואכלת זו אכילה ושבעת זו שתיה הכוונה דאם שתה לאחר אכילה אז חייב לברך ואם לאו אינו חייב אלא מדרבנן:","(כו) והוא תאב לשתות - דאם אינו תאב לשתות לכו\"ע חייב מדאורייתא אף בלי שתיה:","(כז) וטוב ליזהר לכתחלה - ר\"ל דלפי פסק המחבר מקודם דאם יש מי שמחוייב בדבר מדאורייתא שיודע לברך מצוה שיברך הוא להוציא אחרים טוב לחוש גם לשיטה זו שיברך מי ששתה אחר אכילתו להוציא אחרים דהוא מחוייב בודאי מדאורייתא אם לא שאותן ששתו אין יודעין לברך דאז יוכל להוציא אותן אפילו מי שלא שתה וכמו שכתב גם המחבר לענין כדי שביעה:","(כח) שיברך מי ששתה - ואעפ\"כ אם מקצתן אכלו לשובע ולא שתו ומקצתן לא אכלו לשובע ושתו מוטב שיברכו אותן שאכלו לשובע דחייבין מדאורייתא לדעת הפוסקים אף שלא שתו ודעת המרדכי בשם הרא\"מ דעת יחידאה היא. מי שהיה שבע קודם שאכל ואכל אכילה גסה שלא היה צריך לאותה אכילה אעפ\"כ אם נהנה גרונו מאותה אכילה מברך עליו לפניו ולאחריו ומוציא אחרים ואם נפשו קצה עליו ואינו נהנה גרונו אינו ראוי לברך לא לפניה ולא לאחריה לפי שזו אינה חשובה אכילה כלל לכל מצות שבתורה כמו שנתבאר בסימן תע\"ו ובסימן תרי\"ב:\n"]}],"198":[{"s":"<b>אחד נכנס אצל שלשה שאכלו. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>שלשה שאכלו והם מברכין ונכנס א' <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>שלא <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>אכל אם נכנס כשאומר המברך נברך שאכלנו משלו עונה אחריו ברוך ומבורך <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>שמו תמיד לעולם ועד ואם נכנס כשאחרים עונים ברוך שאכלנו משלו עונה אחריהם <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>אמן: <small>הגה וכן בכל הברכו' שאדם שומע חייב לענות אמן (טור ב\"י בשם בה\"ג וסמ\"ג) </small> <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ואם הם י' אומר ברוך <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>אלהינו ומבורך שמו תמיד לעולם ועד <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>וה\"ה אם היה שם כשגמרו מלאכול ולא אכל עמהם כך הוא עונה אחר המברך ואחר העונים:","m":["(א) שלא אכל - ואם שתה אפילו לא נצטרף עמהם כלל יכול לומר ברוך שאכלנו וכו' דשתיה בכלל אכילה ומיהו בעשרה לענין הזכרת השם שיאמר ברוך אלהינו שאכלנו משלו וכו' נשאר הפמ\"ג בספק ע\"ש:","(ב) עונה אחריו ברוך וכו' - דאין מן הראוי שיהיה אדם אצל חבורה שמזמינין עצמן ליתן שבח והודיה לו ית' והוא ימנע מזה:","(ג) כשאחרים עונים - ר\"ל דאז לא יוכל לענות ברוך וכו' כיון שלא שמע מפי המזמן שבקשו לברך:","(ד) עונה אחריהם אמן - ככל הברכות שאדם שומע מפי ישראל שצריך לענות אמן אחריו ואם שמע אח\"כ מפי המזמן כשחזר ואמר ברוך שאכלנו משלו וכו' צריך לענות עוד הפעם אמן ככל הברכות שאדם שומע מפי אחד וחזר ושמע אותה הברכה מפי השני כתב הט\"ז אם נכנס אחר שכבר התחיל המברך לומר ברוך שאכלנו אין צריך לענות אמן אבל כמה אחרונים חולקין ע\"ז:","(ה) בכל הברכות - בין ברכת המצות בין ברכת הנהנין:","(ו) אומר ברוך אלהינו - היינו כששמע להמברך שאמר נברך לאלהינו ואם שמע רק להעונים אומר רק אמן בלבד כנ\"ל. וברכת נשואין עונה ברוך אלהינו ומבורך שמו תמיד לעולם ועד שהשמחה במעונו [אחרונים]:","(ז) ואחר העונים - ר\"ל אף שאמר מתחלה עם המסובין ברוך ומבורך וכו' צריך לענות לבסוף אמן ג\"כ אחר העונים:"]}],"199":[{"s":"<b>על מי מזמנים ועל מי אין מזמנים. ובו יא סעיפים:</b><br><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>השמש שאכל כזית מזמנין עליו:","m":["(א) מזמנין עליו - שאף שלא קבע עצמו בשלחן עמהם שאוכל מעומד וגם הולך ובא באמצע אכילתו ואין לו קביעות כלל עמהם אפ\"ה מצטרף שכיון שדרך אכילתו בכך זו היא קביעתו משא\"כ באיש אחר וכמ\"ש בסימן קצ\"ג ס\"ב במ\"ב:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>כותי בזמן הזה הרי הוא כעובד עבודת אלילים ואין מזמנין עליו:","m":[]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>עם הארץ גמור מזמנין עליו בזמן הזה:","m":[]},{"s":"עכו\"ם אין מזמנין עליו <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ואפי' גר שמל <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>ולא טבל אין מזמנין עליו אבל גר גמור מזמנין עליו ויכול לברך בהמ\"ז <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ולומר על שהנחלת לאבותינו:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>אונן בחול שהוא <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>פטור מלברך אין מזמנין עליו:","m":[]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>נשים ועבדים וקטנים אין מזמנין עליהם אבל מזמנין <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i>לעצמן ולא תהא חבורה של נשים ועבדים וקטנים מזמנין יחד <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>משום פריצותא דעבדים אלא נשים לעצמן ועבדים לעצמן <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>ובלבד שלא יזמנו בשם:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>נשים מזמנות לעצמן רשות אבל כשאוכלות עם האנשי' חייבות ויוצאות בזימון שלנו: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>אע\"פ שאינן מבינות (הרא\"ש ומרדכי ריש פרק שלשה שאכלו בשם רש\"י):</small>","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i> אנדרוגינוס מזמן למינו ואינו מזמן לא לאנשים ולא לנשים:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>טומטום אינו מזמן כלל:","m":[]},{"s":" <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>קטן שהגיע לעונת <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"4\"></i>הפעוטות ויודע למי מברכין מזמנין עליו ומצטרף בין לשלשה <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>בין לעשרה: <small>הגה וי\"א דאין מצרפין אותו כלל עד שיהא בן שלש עשרה שנה דאז <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>מחזקינן ליה כגדול שהביא <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>שתי שערות (הרא\"ש ומרדכי פרק שלשה שאכלו וטור) וכן נוהגין ואין לשנות. <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>וחרש ושוטה אם מכוונים ומבינים מצטרפין לזימון אע\"פ שאין החרש שומע הברכה (מהרי\"ל):</small>","m":["(ב) ע\"ה גמור - דבגמרא אמרינן דאפילו קרא ושנה ולא שימש ת\"ח דהיינו להבין טעמי המשניות להקשות ולפרק אין מזמנין עליו ולכן קאמר דאפילו ע\"ה גמור שאין בו מקרא ומשנה מזמנין עליו בזמן הזה שאם היו פורשין מהם היו גם הם פורשין מן הצבור לגמרי ואם אינו מקיים מצות התורה בדבר המפורסם בכל ישראל כגון שאינו קורא ק\"ש שחרית וערבית י\"א שאעפ\"כ מזמנין עליו ודעת המ\"א שבזה אין מזמנין עליו דבזה כיון דכלל ישראל קוראין ק\"ש לא חיישינן לקלקולא במה שנפרוש עצמנו מיחידים שאין קורין וכן סתמו כמה אחרונים וכ\"ש מי שהוא רשע ועובר עבירות בפרהסיא דאין מזמנין עליו [מ\"א וש\"א]:","(ג) עובד כוכבים אין וכו' - היינו אפילו נתכוין לברך לאלהי ישראל:","(ד) ולא טבל - וכל זמן שלא טבל כדין בפני ב\"ד של שלשה כמבואר ביו\"ד סימן רס\"ח ס\"א מקרי לא טבל [אחרונים]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>מי שנדוהו על עבירה אין מזמנין עליו:","m":["(ה) אין מזמנין עליו - דאינו גר עד שימול ויטבול:","(ו) ויכול לברך - והיינו אפילו להוציא אחרים ידי חובתן בברכת המזון [ב\"י]:","(ז) לאבותינו - לפי שלאברהם נתנה הארץ למורשה ואברהם נקרא אב המון גוים:","(ח) שהוא פטור מלברך - פי' כל זמן שמתו מוטל לפניו כבסימן ע\"א:","(ט) אין מזמנין - ואפילו להאומרים שאם רצה להחמיר ולענות ולברך הרשות בידו מ\"מ כיון שהוא פטור אינו מצטרף ועיין מה שכתבנו לעיל בסימן ע\"א סק\"ד במ\"ב לענין אם יש חבורה בעיר המיוחדים להוצאת המת ומסרהו להם:","(י) עליו - ואפילו בדיעבד אם בירך להוציא לאחרים לא מהני דכל שהוא בעצמו פטור מן הדבר אין יכול להוציא לאחרים [פמ\"ג]:","(יא) וקטנים - עיין לקמיה בסעיף י':","(יב) אין מזמנין עליהן - ר\"ל אם לא היו רק שני אנשים אין אלו מצטרפין לשלשה שיתחייבו על ידם בזימון משום דאלו אינן בני חיובא בזימון וכדלקמיה בס\"ז ואפילו אם רצו לזמן עמהם ג\"כ אין רשאין וגרע מנשים בעצמן או עבדים שיש להם עכ\"פ רשות לזמן וכדלקמיה משום שאין חברתן נאה שיהיה הצירוף של שלשה ע\"י הנשים וכן ע\"י העבדים שהם פרוצים בזמה ואפילו אשה עם בעלה ובניה ג\"כ אין נכון להצטרף מטעם זה:","(יג) אבל מזמנין לעצמן - רשות וקאי אנשים ועבדים ולא אקטנים דקטנים לאו בני מצוה נינהו לומר שיזמנו לעצמן:","(יד) פריצותא דעבדים - שחשודים על הזנות ועל משכב זכור ולכן אפילו יש ג' עבדים אין מזמנין עם הנשים בחבורה אחת דאכתי איכא פריצותא:","(טו) בשם - דהזכרת השם הוא דבר שבקדושה וכל דבר שבקדושה איננו בפחות מעשרה זכרים ובני חורין וכדלעיל בסי' נ\"ה:","(טז) רשות - י\"ל הטעם דלא רצו חכמים להטיל עליהם חיוב ברכת הזימון כשהם בפ\"ע משום שאינו מצוי כ\"כ שיהיו בקיאות בברכת הזימון:","(יז) חייבות וכו' - ואע\"ג דנתבאר בסקי\"ב דאין מזמנין אנשים ונשים ביחד ואפילו רצו משום שאין חבורתן נאה היינו דוקא התם שהאנשים הם רק שנים וחיוב זימון בא ע\"י צירוף נשים להכי מנכר צירופן והתחברותן יחד וגנאי הדבר משא\"כ הכא מיירי כשיש שלשה אנשים זולתן ואין צריך כלל לצירופן לענין חיוב זימון ולכן אף שהנשים ועבדים מצטרפין לצאת ידי חובתן בשמיעה מהמברך ולענות אחריו ברכת הזימון אין בזה משום גנאי:","(יח) ויוצאות וכו' - שכמו שהאנשים מוציאים לאנשים כן הם מוציאים לנשים ועיין בשו\"ע הגר\"ז שדעתו שאם רצו הנשים להתחלק מחבורת האנשים ולזמן בפ\"ע הרשות בידן:","(יט) אע\"פ שאינן מבינות - ועיין בסימן קצ\"ג במ\"ב סק\"ה מש\"כ שם בשם האחרונים דיוצאות גם ידי בהמ\"ז בשמיעה מפי המברך אע\"פ שאינן מבינות לשה\"ק וכתבנו שם דמ\"מ יותר נכון שיאמרו אחר המברך מלה במלה בלחש אם אפשר להם:","(כ) מזמן למינו - דכל אנדרוגינוס אחד הם משא\"כ בטומטום לקמיה דשמא זה כשיקרע ימצא זכר וזה נקבה ואין נשים מצטרפות עם האנשים וכדלעיל בס\"ו:","(כא) לא לאנשים וכו' - דשמא נקבה היא ונתבאר בס\"ו שאין מזמנין עליהן וכן עם הנשים דשמא זכר הוא ואין חברתן נאה וכנ\"ל:","(כב) אינו מזמן כלל - היינו אפילו עם שני טומטומים אחרים וכ\"ש דאינו מצטרף עם אנשים ונשים ומ\"מ פשוט דעם ג' אנשים יכול להצטרף דלא גריעא מאשה וכנ\"ל בס\"ז:","(כג) שהגיע וכו' - ופחות מזה אין דעתו חשיב לכלום אפי' יודע למי מברכין:","(כד) הפעוטות - היינו כבן ט' או כבן י' [מ\"א] וי\"א דה\"ה בפחות משיעור זה אם הוא רק מבן שש ומעלה אם הוא חריף ויודע למי מברכין:","(כה) ומצטרף וכו' - היינו אחד ולא שנים בין לשלשה בין לעשרה:","(כו) בין לשלשה וכו' - והא דאיתא בס\"ו דאין מזמנין על הקטנים מיירי בקטנים ביותר או שאינו יודע למי מברכין:","(כז) דאז מחזקינן וכו' - דאמרינן כיון שהגיע לכלל שנים מסתמא כבר הביא שתי שערות וא\"צ בדיקה אחר זה אבל אם בדקוהו ונמצא שאין בו שתי שערות לא מצרפינן ליה לזימון. וכל אלו הדעות הוא רק לענין צירוף שיהיה מצטרף לשלשה ולעשרה אבל שיהיה הוא המזמן ויוציא אחרים בבהמ\"ז לכו\"ע אינו מוציא עד שיהיה בן י\"ג שנה ויום אחד וידוע שהביא שתי שערות שבהמ\"ז הוא מן התורה ובשל תורה אין סומכין על חזקה זו דמסתמא הביא מיהו אם המזמן אינו אומר כי אם נברך וכל בהמ\"ז מברך כ\"א ואחד לעצמו כמנהגנו [וכמבואר בסימן קפ\"ג ס\"ז] לית לן בה דכיון שהוא בן י\"ג שנה סמכינן בזה על חזקה:","(כח) וחרש - מיירי בחרש המדבר ואינו שומע דאלו בחרש גמור קי\"ל דפטור מכל המצות כקטן דלאו בר דעה הוא וכדלעיל בסימן נ\"ה ס\"ח ואינו מצטרף. וחרש השומע ואינו מדבר עיין בפמ\"ג:","(כט) ושוטה - לא מיירי בשוטה גמור דזה אין מצטרף אלא שאינו חכם כ\"כ כשאר אינשי והעם מחזיקין אותו לשוטה:","(ל) אין מזמנין עליו - בין לג' בין לעשרה שזהו לשון נידוי שמרחיקין ומבדילין אותו מאגודתם ועיין לעיל בסימן נ\"ה סי\"ב בבה\"ל:"]}],"200":[{"s":"<b>דין המפסיק כדי לברך. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>שלשה שאכלו כאחד אחד <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>מפסיק על <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>כרחו לב' ועונה עמהם ברכת <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>זימון ואפילו לא רצה להפסיק מזמנין עליו בין עונה בין אינו עונה כל שהוא עומד שם <i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>אבל שנים אין חייבים להפסיק לאחד הלכך אין חיוב זימון חל עד שיתרצו להפסיק לאחד ולברך ואם לא רצו להפסיק וזימן הוא עליהם לא עשה כלום <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ואם לא רצו להפסיק <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אף הוא <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אינו רשאי לברך ולצאת <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>לשוק עד שיגמרו השנים ויזמן עליהם שהרי כבר נתחייב הוא בזימון והיאך יברך בלא זימון:","m":["(א) שאכלו כאחד וכו' - ר\"ל שהתחילו לאכול כאחד וגמרו שנים מהם תחלה ורוצים לברך בהמ\"ז:","(ב) מפסיק על כרחו - ר\"ל שאין הדבר תלוי ברצונו אם רוצה להפסיק מסעודתו ולענות אלא מן הדין מחויב לזה כיון שהם רבים נגדו אין צריכים להמתין עליו:","(ג) בין אינו עונה וכו' - ר\"ל שאעפ\"כ הם יוצאים ידי זימון כיון שהוא עומד שם ושומע ויכול לענות (ולאפוקי כשיצא לחוץ וכדלעיל בסימן קצ\"ד ס\"ב) ומיהו הוא בודאי אינו יוצא אא\"כ הפסיק וענה עמהם:","(ד) אין חיוב זימון חל וכו' - הלשון מגומגם קצת והכוונה דאין חייבים עתה לזמן עם האחד:","(ה) אינו רשאי - הב\"ח חולק ע\"ז ודעתו דאין חיוב זימון חל עד שיגמרו כל השלשה את סעודתם ועל כן קודם שגמרו השנים רשאי האחד לברך בפני עצמו ולצאת והעתיקו המ\"א להלכה אבל כל האחרונים חולקין עליו ודעתם כהשו\"ע דמכיון שהתחילו לאכול ביחד חל מיד חובת זימון עליהם ואין שום אחד מהם שגמר סעודתו קודם רשאי לברך בפ\"ע ולצאת מיהו אם היה דבר נחוץ מאד שנוגע להפסד ממון וכדומה אפשר שיש להקל להאחד לברך בפ\"ע קודם שגמרו השנים סעודתם ולצאת. אך באופן זה טוב יותר שהשנים יתנהגו בזה לפנים משורת הדין ויפסיקו מסעודתם ויזמן עליהם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אינו צריך להפסיק אלא <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>עד שיאמר ברוך שאכלנו משלו וכו': <small>הגה וי\"א שצריך להפסיק עד שיאמר הזן את הכל וכן נוהגין (הרא\"ש ותו' והר\"י בשם בה\"ג והטור) ואם היה דעתו <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>לחזור ולאכול <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>פת אע\"פ שלא אכל אח\"כ <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>כשרוצ' לברך מברך מתחיל' ברכת הזן <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>וכ\"ש אם חזר ואכל (הר\"י פרק שלשה שאכלו) (טור) </small> וחוזר וגומר סעודתו <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>בלא ברכה בתחילה:","m":["(ו) עד שיאמר וכו' - דבזה לבד יוצאים ידי ברכת הזימון:","(ז) בלא ברכה בתחלה - דהיינו שאין צריך עוד הפעם נט\"י והמוציא שהרי כשפסק בשביל ברכת הזימון לא הסיח דעתו מלאכול עוד. ואם לא היה דעתו לחזור ולאכול וחוזר ואוכל צריך ברכת המוציא בתחלה וגם נט\"י ממילא:","(ח) וי\"א שצריך להפסיק - ס\"ל דאף דברכת הזן לאו לגמרי מברכת זימון היא דהרי היחיד אומר אותה ג\"כ אפ\"ה שייכא לברכת זימון דנברך לבד אינה ברכה שאין בה שם ומלכות וקאי על מה שמברך המזמן אח\"כ ברכת הזן:","(ט) עד שיאמר הזן - וחוזר וגומר סעודתו כמו שכתב המחבר ואח\"כ מברך מתחלת בהמ\"ז כמו שסיים הרמ\"א לבסוף והטעם דאף דשמע ברכת הזן מפי המזמן מ\"מ הרי צריך לברך כל הבהמ\"ז בשביל מה שאכל אח\"כ ומסיים הרמ\"א עוד דאפי' לא אכל אח\"כ אם רק בדעתו היה [בעת שפסק כדי לשמוע ברכת הזימון] לחזור אח\"כ לגמור סעודתו כשיברך אח\"כ מתחיל מתחלת ברכת הזן דכיון דדעתו היה לאכול עוד מסתמא לא כוון לצאת בברכת הזן מפי המזמן אך אם לא היה בדעתו לאכול עוד ולא אכל כשמברך בהמ\"ז מתחיל מן נודה לך כמו בכל מקום כששומע ברכת הזימון ועיין לעיל סימן קפ\"ג ס\"ז ובמ\"ב שם. כתבו הפוסקים דאחד המפסיק לשנים יכול להפסיק כמה פעמים כגון שמתחלה אכלו ג' והפסיק להם א' ואח\"כ באו שנים אחרים ואכלו עם האחד יכול זה עוד הפעם להפסיק לשנים אלו דלא שייך לומר פרח זימון מינייהו כיון שנצטרפו עמו שנים שלא זימנו יכולין לזמן עליו וכן פעם ג' ויותר אבל אם היו חמשה בחבורה אחת והפסיק א' לשנים שוב אינו יכול לזמן עם שנים מהנשארים דפרח זימון מינייהו [מ\"א וש\"א] ומשמע אפילו אכלו אח\"כ ביחד [ובספר אבן העוזר חולק ע\"ז אך כמה אחרונים מיישבין את דבריו] אבל אם היו ז' או ח' והפסיק לשנים מהם יכול אח\"כ להפסיק עוד הפעם להשאר דלא שייך בזה פרח זימון מינייהו כיון שהיה בהן כדי זימון. עוד כתבו הפוסקים כשם שאחד מפסיק לשנים להצטרף לזימון ה\"ה שלשה או ארבעה צריכין להפסיק מסעודתם להשלים לעשרה ולברך בשם אך דבזה לכו\"ע אין צריכין להפסיק רק עד ברוך אלהינו שאכלנו וכו' ולא יותר ואם אכלו ביחד אחר כך לאחר שהפסיקו יכולין לברך בזימון ולא פרח זימון מינייהו כי לא נצטרפו מעיקרא רק להזכרת השם וכן יכולין אח\"כ להצטרף לששה אחרים שאכלו אצלם לזמן בשם דלא שייך לומר פרח זימון דאמירת אלהינו דאכל בי עשרה שכינתא שריא וכן אם יש אפי' חמשה שהפסיקו לחמשה אחרים מצטרפין אח\"כ לחמשה אחרים לברכת אלהינו כשאוכלים עכ\"פ כזית פת ביחד [אחרונים]:\n"]}]};